// 자동 생성 — 종목↔free-exercise-db 미디어 매핑(빌드 스크립트). 직접 수정 금지. @plm SRS-032
// s=시작 이미지 경로, e=끝 이미지 경로(free-exercise-db exercises/<경로>), k=한국어 스텝, en=영문 스텝.

export interface RawMedia {
  s?: string; // 시작 이미지 경로 — steps-only 엔트리(무매칭 자체 스텝)는 생략. @plm SRS-032
  e?: string;
  k: string[];
  en: string[];
}

// 키=종목 한국어명(nameKo). 129종목(무매칭 7종 제외). @plm SRS-032
export const RAW_MEDIA: Record<string, RawMedia> = {
  "바벨 벤치프레스": { s: "Barbell_Bench_Press_-_Medium_Grip/0.jpg", e: "Barbell_Bench_Press_-_Medium_Grip/1.jpg", k: ["플랫 벤치에 등을 대고 눕는다. 미디엄 그립(동작 중간 지점에서 아래팔과 위팔이 90도를 이루는 너비)으로 랙에서 바를 들어 올려 팔을 편 채 몸 위로 곧게 세운다. 이것이 시작 자세다.", "시작 자세에서 숨을 들이마시며 바가 가슴 중앙에 닿을 때까지 천천히 내린다.", "잠깐 멈춘 뒤 숨을 내쉬며 바를 시작 자세로 밀어 올린다. 가슴 근육으로 바를 밀어 올리는 데 집중한다. 동작 맨 위에서 팔을 펴고 가슴을 수축시켜 1초간 유지한 뒤 다시 천천히 내린다. 팁: 이상적으로는 내리는 시간이 올리는 시간의 약 두 배가 되도록 한다.", "정해진 반복 횟수만큼 동작을 반복한다.", "끝나면 바를 랙에 다시 걸어 둔다."], en: ["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.", "After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."] },
  "인클라인 프레스": { s: "Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg", e: "Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg", k: ["인클라인 벤치에 등을 대고 눕는다. 미디엄 그립(동작 중간 지점에서 아래팔과 위팔이 90도를 이루는 너비)으로 랙에서 바를 들어 올려 팔을 편 채 몸 위로 곧게 세운다. 이것이 시작 자세다.", "숨을 들이마시며 바가 윗가슴에 닿는 느낌이 들 때까지 천천히 내린다.", "1초간 멈춘 뒤 숨을 내쉬며 가슴 근육으로 바를 밀어 시작 자세로 되돌린다. 수축 자세에서 팔을 펴고 가슴을 쥐어짜듯 수축시켜 1초간 유지한 뒤 다시 천천히 내린다. 팁: 내리는 시간이 올리는 시간의 최소 두 배가 되도록 한다.", "정해진 반복 횟수만큼 동작을 반복한다.", "끝나면 바를 랙에 다시 걸어 둔다."], en: ["Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "As you breathe in, come down slowly until you feel the bar on you upper chest.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."] },
  "디클라인 프레스 (바벨)": { s: "Decline_Barbell_Bench_Press/0.jpg", e: "Decline_Barbell_Bench_Press/1.jpg", k: ["디클라인 벤치 끝에 다리를 고정하고 천천히 벤치에 눕는다.", "미디엄 그립(동작 중간 지점에서 아래팔과 위팔이 90도를 이루는 너비)으로 랙에서 바를 들어 올려 팔을 편 채 몸 위로 곧게 세운다. 팔은 바닥과 수직이어야 한다. 이것이 시작 자세다. 팁: 회전근개를 보호하려면 보조자가 랙에서 바벨을 들어 올리는 것을 도와주는 것이 가장 좋다.", "숨을 들이마시며 바가 아랫가슴에 닿는 느낌이 들 때까지 천천히 내린다.", "1초간 멈춘 뒤 숨을 내쉬며 가슴 근육으로 바를 밀어 시작 자세로 되돌린다. 수축 자세에서 팔을 펴고 가슴을 수축시켜 1초간 유지한 뒤 다시 천천히 내린다. 팁: 내리는 시간이 올리는 시간의 최소 두 배가 되도록 한다.", "정해진 반복 횟수만큼 동작을 반복한다.", "끝나면 바를 랙에 다시 걸어 둔다."], en: ["Secure your legs at the end of the decline bench and slowly lay down on the bench.", "Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.", "As you breathe in, come down slowly until you feel the bar on your lower chest.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."] },
  "덤벨 벤치프레스": { s: "Dumbbell_Bench_Press/0.jpg", e: "Dumbbell_Bench_Press/1.jpg", k: ["플랫 벤치에 누워 양손에 덤벨을 하나씩 들고 허벅지 위에 올려 둔다. 손바닥은 서로 마주 보게 한다.", "허벅지의 반동을 이용해 덤벨을 하나씩 들어 올려 어깨너비로 몸 앞에 든다.", "어깨너비에 오면 손목을 앞으로 돌려 손바닥이 앞쪽(몸 반대편)을 향하게 한다. 덤벨은 가슴 양옆에 위치하고, 위팔과 아래팔이 90도를 이루어야 한다. 항상 덤벨을 완전히 통제한다. 이것이 시작 자세다.", "숨을 내쉬며 가슴 근육으로 덤벨을 밀어 올린다. 동작 맨 위에서 팔을 펴고 가슴을 수축시켜 1초간 유지한 뒤 천천히 내린다. 팁: 이상적으로는 내리는 시간이 올리는 시간의 약 두 배가 되도록 한다.", "트레이닝 프로그램에 정해진 반복 횟수만큼 동작을 반복한다."], en: ["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.", "Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.", "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.", "Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions of your training program."] },
  "디클라인 프레스 (덤벨)": { s: "Decline_Dumbbell_Bench_Press/0.jpg", e: "Decline_Dumbbell_Bench_Press/1.jpg", k: ["디클라인 벤치 끝에 다리를 고정하고 양손에 덤벨을 하나씩 들어 허벅지 위에 올린 채 눕는다. 손바닥은 서로 마주 보게 한다.", "누운 뒤 덤벨을 어깨너비로 몸 앞에 위치시킨다.", "어깨너비에 오면 손목을 앞으로 돌려 손바닥이 앞쪽(몸 반대편)을 향하게 한다. 이것이 시작 자세다.", "숨을 내쉬며 덤벨을 천천히 양옆으로 내린다. 항상 덤벨을 완전히 통제한다. 팁: 동작 내내 아래팔은 항상 바닥과 수직을 유지해야 한다.", "숨을 내쉬며 가슴 근육으로 덤벨을 밀어 올린다. 수축 자세에서 팔을 펴고 가슴을 쥐어짜듯 수축시켜 1초간 유지한 뒤 천천히 내린다. 팁: 내리는 시간이 올리는 시간의 최소 두 배가 되도록 한다.", "트레이닝 프로그램에 정해진 반복 횟수만큼 동작을 반복한다."], en: ["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.", "Once you are laying down, move the dumbbells in front of you at shoulder width.", "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.", "As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..", "Repeat the movement for the prescribed amount of repetitions of your training program."] },
  "덤벨 플라이": { s: "Dumbbell_Flyes/0.jpg", e: "Dumbbell_Flyes/1.jpg", k: ["플랫 벤치에 누워 양손에 덤벨을 하나씩 들어 허벅지 위에 올린다. 손바닥은 서로 마주 보게 한다.", "허벅지의 반동을 이용해 덤벨을 하나씩 들어 올려 손바닥이 서로 마주 본 채 어깨너비로 몸 앞에 든다. 프레스하듯 덤벨을 밀어 올리되 팔을 완전히 펴기 직전에 멈추고 유지한다. 이것이 시작 자세다.", "이두근 힘줄에 부담이 가지 않도록 팔꿈치를 살짝 구부린 상태에서, 가슴이 늘어나는 느낌이 들 때까지 양팔을 넓은 호를 그리며 양옆으로 내린다. 이 동작을 하는 동안 숨을 들이마신다. 팁: 동작 내내 팔은 고정된 상태를 유지하고, 움직임은 오직 어깨 관절에서만 일어나야 한다.", "가슴 근육을 쥐어짜듯 수축시키고 숨을 내쉬며 양팔을 시작 자세로 되돌린다. 팁: 내릴 때와 같은 호의 궤적을 사용한다.", "수축 자세에서 1초간 유지하고 정해진 반복 횟수만큼 동작을 반복한다."], en: ["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.", "Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."] },
  "인클라인 덤벨 플라이": { s: "Incline_Dumbbell_Flyes/0.jpg", e: "Incline_Dumbbell_Flyes/1.jpg", k: ["양손에 덤벨을 하나씩 들고 각도가 30도를 넘지 않게 세팅한 인클라인 벤치에 눕는다.", "팔꿈치를 살짝 구부린 채 양팔을 몸 위로 뻗는다.", "이제 손목을 돌려 손바닥이 자신을 향하게 한다. 팁: 새끼손가락이 서로 나란히 오도록 한다. 이것이 시작 자세다.", "숨을 들이마시며 팔을 뻗은 상태를 유지한 채 천천히 양옆으로 내리고, 손바닥이 서로 마주 볼 때까지 손목을 돌린다. 팁: 동작이 끝나면 팔은 몸 옆에 오고 손바닥은 천장을 향한다.", "숨을 내쉬며 동작을 반대로 하여 덤벨을 시작 자세로 되돌리고, 새끼손가락이 다시 나란히 오도록 손을 돌린다. 팁: 움직임은 오직 어깨 관절과 손목에서만 일어난다는 점을 명심한다. 팔꿈치 관절에서는 어떤 움직임도 일어나지 않는다.", "권장 반복 횟수만큼 반복한다."], en: ["Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.", "Extend your arms above you with a slight bend at the elbows.", "Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.", "As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.", "As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.", "Repeat for the recommended amount of repetitions."] },
  "케이블 크로스오버": { s: "Cable_Crossover/0.jpg", e: "Cable_Crossover/1.jpg", k: ["시작 자세를 잡기 위해 도르래를 높은 위치(머리 위)에 두고 사용할 무게를 선택한 뒤 양손에 도르래 손잡이를 잡는다.", "양쪽 도르래 사이의 가상의 직선 앞으로 한 걸음 나가면서 양팔을 몸 앞으로 모은다. 상체는 허리에서 앞으로 살짝 숙인다. 이것이 시작 자세다.", "이두근 힘줄에 부담이 가지 않도록 팔꿈치를 살짝 구부린 상태에서, 가슴이 늘어나는 느낌이 들 때까지 양팔을 넓은 호를 그리며 양옆으로 뻗는다. 이 동작을 하는 동안 숨을 들이마신다. 팁: 동작 내내 팔과 상체는 고정된 상태를 유지하고, 움직임은 오직 어깨 관절에서만 일어나야 한다.", "숨을 내쉬며 양팔을 시작 자세로 되돌린다. 내릴 때와 같은 호의 궤적을 사용한다.", "시작 자세에서 1초간 유지하고 정해진 반복 횟수만큼 동작을 반복한다."], en: ["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.", "Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."] },
  "로우 케이블 플라이": { s: "Low_Cable_Crossover/0.jpg", e: "Low_Cable_Crossover/1.jpg", k: ["시작 자세로 들어가기 위해 도르래를 낮은 위치에 두고 사용할 무게를 선택한 뒤 양손에 손잡이를 하나씩 잡는다.", "앞으로 한 걸음 나가 도르래에 장력을 준다. 손바닥은 앞을 향하고, 손은 허리 아래에 두며, 팔은 편 상태다. 이것이 시작 자세다.", "팔을 살짝 구부린 채 양손을 위쪽과 몸 중심선 방향으로 끌어 올린다. 손바닥이 위를 향한 채 양손이 가슴 앞에서 모이게 한다.", "잠깐 멈춘 뒤 양팔을 시작 자세로 되돌린다."], en: ["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.", "Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.", "With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.", "Return your arms back to the starting position after a brief pause."] },
  "펙 덱 플라이": { s: "Butterfly/0.jpg", e: "Butterfly/1.jpg", k: ["등을 패드에 밀착시킨 채 머신에 앉는다.", "손잡이를 잡는다. 팁: 위팔이 바닥과 평행이 되도록 한다. 그에 맞게 머신을 조절한다. 이것이 시작 자세다.", "가슴을 중앙으로 쥐어짜듯 수축시키며 손잡이를 천천히 모은다. 이 동작을 하는 동안 숨을 내쉬고 수축을 1초간 유지한다.", "숨을 들이마시며 가슴 근육이 완전히 늘어날 때까지 천천히 시작 자세로 되돌린다.", "권장 반복 횟수만큼 반복한다."], en: ["Sit on the machine with your back flat on the pad.", "Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.", "Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.", "Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.", "Repeat for the recommended amount of repetitions."] },
  "체스트 프레스 머신": { s: "Leverage_Chest_Press/0.jpg", e: "Leverage_Chest_Press/1.jpg", k: ["핀에 적절한 무게를 걸고 자신의 키에 맞게 좌석을 조절한다. 동작 시작 시 손잡이는 가슴 아래쪽이나 중앙 근처에 와야 한다.", "가슴과 머리를 세우고 견갑골을 뒤로 모은다. 이것이 시작 자세다.", "팔꿈치를 펴며 손잡이를 앞으로 민다.", "맨 위에서 잠깐 멈춘 뒤 시작 자세 바로 위까지 무게를 되돌리되, 세트가 끝날 때까지 무게를 완전히 스톱에 내려놓지 않아 근육에 긴장을 유지한다."], en: ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.", "Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."] },
  "스미스 벤치프레스": { s: "Smith_Machine_Bench_Press/0.jpg", e: "Smith_Machine_Bench_Press/1.jpg", k: ["스미스 머신 아래에 플랫 벤치를 놓는다. 누웠을 때 팔을 거의 다 편 상태에서 닿을 수 있는 높이에 바벨을 위치시킨다. 필요한 무게를 선택한 뒤 플랫 벤치에 눕는다. 어깨너비보다 넓은 오버핸드 그립으로 랙에서 바를 풀어 팔을 편 채 몸 위로 곧게 세운다. 이것이 시작 자세다.", "숨을 들이마시며 바가 가슴 중앙에 닿는 느낌이 들 때까지 천천히 내린다.", "1초간 멈춘 뒤 숨을 내쉬며 가슴 근육으로 바를 밀어 시작 자세로 되돌린다. 수축 자세에서 팔을 펴고 1초간 유지한 뒤 다시 천천히 내린다. 팁: 내리는 시간이 올리는 시간의 최소 두 배가 되도록 한다.", "정해진 반복 횟수만큼 동작을 반복한다.", "끝나면 바를 랙에 다시 잠근다."], en: ["Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "As you breathe in, come down slowly until you feel the bar on your middle chest.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, lock the bar back in the rack."] },
  "딥스": { s: "Dips_-_Chest_Version/0.jpg", e: "Dips_-_Chest_Version/1.jpg", k: ["이 운동을 하려면 평행봉이 필요하다. 시작 자세를 잡기 위해 팔을 편 채(팔을 곧게 편 상태) 바 위로 몸을 지탱한다.", "숨을 들이마시며 상체를 약 30도 정도 앞으로 기울이고 팔꿈치를 살짝 벌린 채, 가슴이 살짝 늘어나는 느낌이 들 때까지 몸을 천천히 내린다.", "늘어나는 느낌이 들면 숨을 내쉬며 가슴 힘으로 몸을 시작 자세로 되돌린다. 팁: 동작 맨 위에서 가슴을 1초간 수축시키는 것을 잊지 않는다.", "정해진 반복 횟수만큼 동작을 반복한다."], en: ["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.", "While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.", "Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.", "Repeat the movement for the prescribed amount of repetitions."] },
  "푸시업": { s: "Pushups/0.jpg", e: "Pushups/1.jpg", k: ["바닥에 엎드려 양손을 약 90cm 정도 벌리고 팔을 편 채 상체를 지탱한다.", "숨을 들이마시며 가슴이 바닥에 거의 닿을 때까지 몸을 내린다.", "숨을 내쉬며 가슴을 수축시켜 상체를 시작 자세로 밀어 올린다.", "맨 위 수축 자세에서 잠깐 멈춘 뒤 필요한 반복 횟수만큼 다시 몸을 내리기 시작한다."], en: ["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.", "Next, lower yourself downward until your chest almost touches the floor as you inhale.", "Now breathe out and press your upper body back up to the starting position while squeezing your chest.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."] },
  "인클라인 푸시업": { s: "Incline_Push-Up/0.jpg", e: "Incline_Push-Up/1.jpg", k: ["벤치나 튼튼한 높은 받침대를 마주 보고 선다. 양손을 벤치나 받침대 가장자리에 어깨너비보다 살짝 넓게 올린다.", "팔과 몸을 곧게 편 채 발 앞부분을 벤치나 받침대에서 뒤로 위치시킨다. 팔은 몸과 수직이 되어야 한다. 몸을 곧게 유지하며 팔을 구부려 가슴을 박스나 받침대 가장자리로 내린다.", "팔이 펴질 때까지 몸을 밀어 올린다. 반복한다."], en: ["Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.", "Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.", "Push body up until arms are extended. Repeat."] },
  "데드리프트": { s: "Barbell_Deadlift/0.jpg", e: "Barbell_Deadlift/1.jpg", k: ["무게가 실린 바벨 앞에 선다.", "등을 최대한 곧게 편 채 무릎을 구부리고 상체를 앞으로 숙여 미디엄(어깨너비) 오버핸드 그립으로 바를 잡는다. 이것이 운동의 시작 자세다. 팁: 이 그립으로 바를 잡기 어렵다면 그립을 교차(얼터네이트 그립)하거나 손목 스트랩을 사용한다.", "바를 잡은 채 다리로 밀며 동시에 숨을 내쉬면서 상체를 바로 세워 리프트를 시작한다. 선 자세에서 가슴을 내밀고 견갑골을 뒤로 모아 등을 수축시킨다. 군인이 차렷 자세로 서 있을 때의 모습을 떠올린다.", "등을 곧게 편 채 무릎을 구부리며 동시에 허리에서 상체를 앞으로 기울여 시작 자세로 돌아간다. 바의 무게가 바닥에 닿으면 시작 자세로 돌아온 것이며 다음 반복을 수행할 준비가 된다.", "프로그램에 정해진 반복 횟수만큼 수행한다."], en: ["Stand in front of a loaded barbell.", "While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.", "While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.", "Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.", "Perform the amount of repetitions prescribed in the program."] },
  "스모 데드리프트": { s: "Sumo_Deadlift/0.jpg", e: "Sumo_Deadlift/1.jpg", k: ["바를 바닥에 놓고 무게를 싣는 것으로 시작한다. 바가 양발 중앙을 지나도록 바에 다가선다. 발은 아주 넓게, 칼라 가까이에 둔다. 엉덩이를 접어 바를 잡는다. 팔은 어깨 바로 아래, 다리 안쪽에 두고, 오버핸드 그립, 얼터네이트 그립, 또는 훅 그립을 사용할 수 있다. 어깨의 힘을 빼면 사실상 팔이 길어지는 효과가 있다.", "숨을 들이마신 뒤 엉덩이를 낮추고 머리는 앞을 보며 가슴을 세운다. 발을 양옆으로 벌리듯 바닥을 밀며, 체중은 발의 뒤쪽 절반에 싣는다. 엉덩이와 무릎을 편다.", "바가 무릎을 지날 때 뒤로 젖히며 엉덩이를 바 쪽으로 밀어 넣고 견갑골을 모은다.", "엉덩이를 접고 내려가는 동안 무게를 통제하며 바를 바닥으로 되돌린다."], en: ["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.", "Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.", "As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.", "Return the weight to the ground by bending at the hips and controlling the weight on the way down."] },
  "랙 풀": { s: "Rack_Pulls/0.jpg", e: "Rack_Pulls/1.jpg", k: ["파워랙에서 바를 핀 위에 올려 세팅한다. 핀은 원하는 지점(무릎 바로 아래, 바로 위, 또는 허벅지 중간 위치)에 맞춘다. 올바른 데드리프트 자세로 바 앞에 위치한다. 발은 엉덩이 아래에, 그립은 어깨너비로, 등은 아치를 만들고, 엉덩이를 뒤로 빼 햄스트링을 활성화한다. 무게가 대개 무겁기 때문에 얼터네이트 그립, 훅 그립을 쓰거나 스트랩으로 무게를 잡는 데 도움을 받을 수 있다.", "머리는 앞을 본 채 엉덩이와 무릎을 펴며 락아웃될 때까지 무게를 위로, 뒤로 끌어 올린다. 동작을 마무리하면서 어깨를 뒤로 당기는 것을 잊지 않는다.", "무게를 핀으로 되돌리고 반복한다."], en: ["Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.", "With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.", "Return the weight to the pins and repeat."] },
  "바벨 로우": { s: "Bent_Over_Barbell_Row/0.jpg", e: "Bent_Over_Barbell_Row/1.jpg", k: ["오버핸드 그립(손바닥이 아래를 향함)으로 바벨을 잡고 무릎을 살짝 구부린 뒤 등을 곧게 편 채 허리에서 상체를 앞으로 숙여 바닥과 거의 평행이 될 때까지 기울인다. 팁: 머리를 든 상태를 유지한다. 팔이 바닥과 상체에 수직으로 늘어뜨려진 채 바벨이 몸 바로 앞에 매달려야 한다. 이것이 시작 자세다.", "이제 상체를 고정한 채 숨을 내쉬며 바벨을 몸 쪽으로 들어 올린다. 팔꿈치를 몸에 가깝게 유지하고 아래팔은 무게를 잡는 역할만 한다. 맨 위 수축 자세에서 등 근육을 쥐어짜듯 수축시키고 잠깐 멈춘다.", "숨을 들이마시며 바벨을 천천히 시작 자세로 내린다.", "권장 반복 횟수만큼 반복한다."], en: ["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.", "Then inhale and slowly lower the barbell back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "티바 로우": { s: "T-Bar_Row_with_Handle/0.jpg", e: "T-Bar_Row_with_Handle/1.jpg", k: ["바를 랜드마인이나 코너에 고정해 움직이지 않게 한다. 바 끝쪽에 적절한 무게를 싣는다.", "바 위에 서서 더블 D 로우 핸들을 칼라 옆 바 둘레에 건다. 엉덩이와 다리를 사용해 선 자세로 일어선다.", "엉덩이를 뒤로 빼고 가슴을 세운 채 다리를 넓게 벌린다. 팔은 편 상태여야 한다. 이것이 시작 자세다.", "견갑골을 모으고 팔꿈치를 구부려 무게를 윗배 쪽으로 당긴다. 무게를 반동으로 튕기거나 반칙 동작을 하지 않는다.", "잠깐 멈춘 뒤 시작 자세로 되돌린다."], en: ["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.", "Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.", "Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.", "Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.", "After a brief pause, return to the starting position."] },
  "덤벨 로우": { s: "One-Arm_Dumbbell_Row/0.jpg", e: "One-Arm_Dumbbell_Row/1.jpg", k: ["플랫 벤치를 골라 양옆에 덤벨을 하나씩 놓는다.", "오른쪽 다리를 벤치 끝에 올리고 상체가 바닥과 평행이 될 때까지 허리에서 앞으로 숙인 뒤 오른손을 벤치 반대쪽 끝에 짚어 지탱한다.", "왼손으로 바닥의 덤벨을 잡고 허리를 곧게 편 채 무게를 든다. 손바닥은 상체를 향해야 한다. 이것이 시작 자세다.", "위팔을 몸 옆에 가깝게 유지하고 상체를 고정한 채 무게를 가슴 옆까지 곧게 들어 올린다. 이 동작을 하는 동안 숨을 내쉰다. 팁: 완전히 수축된 지점에 도달하면 등 근육을 쥐어짜듯 수축시키는 데 집중한다. 또한 힘은 팔이 아니라 등 근육으로 내야 한다. 상체는 고정된 상태를 유지하고 팔만 움직여야 한다. 아래팔은 덤벨을 잡는 것 외에 다른 일을 하지 않으므로 아래팔로 덤벨을 당기려 하지 않는다.", "무게를 시작 자세로 곧게 내린다. 이 동작을 하는 동안 숨을 들이마신다.", "정해진 반복 횟수만큼 동작을 반복한다.", "반대쪽으로 바꿔 다른 팔로 다시 반복한다."], en: ["Choose a flat bench and place a dumbbell on each side of it.", "Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.", "Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.", "Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.", "Lower the resistance straight down to the starting position. Breathe in as you perform this step.", "Repeat the movement for the specified amount of repetitions.", "Switch sides and repeat again with the other arm."] },
  "시티드 케이블 로우": { s: "Seated_Cable_Rows/0.jpg", e: "Seated_Cable_Rows/1.jpg", k: ["이 운동을 하려면 V바가 달린 로우 풀리 로우 머신이 필요하다. 참고: V바는 손바닥이 서로 마주 보는 중립 그립을 가능하게 한다. 시작 자세를 잡기 위해 먼저 머신에 앉아 무릎을 살짝 구부린 채(완전히 펴지 않음) 앞쪽 발판이나 크로스바에 발을 올린다.", "등의 자연스러운 정렬을 유지한 채 상체를 숙여 V바 손잡이를 잡는다.", "팔을 편 채 상체가 다리와 90도를 이룰 때까지 뒤로 당긴다. 등은 살짝 아치를 만들고 가슴은 내민다. 바를 몸 앞에 든 상태에서 광배근이 시원하게 늘어나는 느낌이 들어야 한다. 이것이 운동의 시작 자세다.", "상체를 고정한 채 팔을 몸에 가깝게 유지하며 손잡이를 복근에 닿을 때까지 상체 쪽으로 당긴다. 이 동작을 하는 동안 숨을 내쉰다. 이때 등 근육을 강하게 쥐어짜듯 수축시켜야 한다. 그 수축을 1초간 유지하고 숨을 들이마시며 천천히 원래 자세로 돌아간다.", "권장 반복 횟수만큼 반복한다."], en: ["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.", "Lean over as you keep the natural alignment of your back and grab the V-bar handles.", "With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.", "Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.", "Repeat for the recommended amount of repetitions."] },
  "랫 풀다운": { s: "Wide-Grip_Lat_Pulldown/0.jpg", e: "Wide-Grip_Lat_Pulldown/1.jpg", k: ["위쪽 도르래에 와이드 바가 달린 풀다운 머신에 앉는다. 머신의 무릎 패드를 자신의 키에 맞게 조절한다. 이 패드는 바에 걸린 무게에 의해 몸이 위로 들리는 것을 막아 준다.", "정해진 그립으로 손바닥이 앞을 향하게 바를 잡는다. 그립 참고: 와이드 그립은 어깨너비보다 넓게, 미디엄 그립은 어깨너비와 같게, 클로즈 그립은 어깨너비보다 좁게 손을 벌린다.", "선택한 그립 너비로 바를 잡고 양팔을 몸 앞으로 편 상태에서, 상체를 약 30도 정도 뒤로 젖히며 허리에 커브를 만들고 가슴을 내민다. 이것이 시작 자세다.", "숨을 내쉬며 어깨와 위팔을 아래로, 뒤로 당겨 바가 윗가슴에 닿을 때까지 내린다. 팁: 완전히 수축된 지점에 도달하면 등 근육을 쥐어짜듯 수축시키는 데 집중한다. 상체는 고정된 상태를 유지하고 팔만 움직여야 한다. 아래팔은 바를 잡는 것 외에 다른 일을 하지 않으므로 아래팔로 바를 당기려 하지 않는다.", "수축 자세에서 견갑골을 모은 채 1초간 유지한 뒤, 팔이 완전히 펴지고 광배근이 완전히 늘어날 때까지 바를 천천히 시작 자세로 올린다. 이 동작을 하는 동안 숨을 들이마신다.", "정해진 반복 횟수만큼 이 동작을 반복한다."], en: ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.", "After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."] },
  "클로즈그립 풀다운": { s: "Close-Grip_Front_Lat_Pulldown/0.jpg", e: "Close-Grip_Front_Lat_Pulldown/1.jpg", k: ["위쪽 도르래에 와이드 바가 달린 풀다운 머신에 앉는다. 머신의 무릎 패드를 자신의 키에 맞게 조절한다. 이 패드는 바에 걸린 무게에 의해 몸이 위로 들리는 것을 막아 준다.", "정해진 그립으로 손바닥이 앞을 향하게 바를 잡는다. 그립 참고: 와이드 그립은 어깨너비보다 넓게, 미디엄 그립은 어깨너비와 같게, 클로즈 그립은 어깨너비보다 좁게 손을 벌린다.", "선택한 그립 너비로 바를 잡고 양팔을 몸 앞으로 편 상태에서, 상체를 약 30도 정도 뒤로 젖히며 허리에 커브를 만들고 가슴을 내민다. 이것이 시작 자세다.", "숨을 내쉬며 어깨와 위팔을 아래로, 뒤로 당겨 바가 윗가슴에 닿을 때까지 내린다. 팁: 완전히 수축된 지점에 도달하면 등 근육을 쥐어짜듯 수축시키는 데 집중한다. 상체는 고정된 상태를 유지한다(팔만 움직여야 한다). 아래팔은 바를 잡는 것 외에 다른 일을 하지 않으므로 아래팔로 바를 당기려 하지 않는다.", "수축 자세에서 견갑골을 모은 채 1초간 유지한 뒤, 팔이 완전히 펴지고 광배근이 완전히 늘어날 때까지 바를 천천히 시작 자세로 올린다. 이 동작을 하는 동안 숨을 들이마신다.", "정해진 반복 횟수만큼 이 동작을 반복한다."], en: ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.", "After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "6. Repeat this motion for the prescribed amount of repetitions."] },
  "스트레이트암 풀다운": { s: "Straight-Arm_Pulldown/0.jpg", e: "Straight-Arm_Pulldown/1.jpg", k: ["풀다운 머신의 위쪽 도르래에서 와이드 바를 잡는 것으로 시작하며, 어깨너비보다 넓은 오버핸드 그립(손바닥이 아래를 향함)을 사용한다. 60cm 정도 뒤로 물러선다.", "팔을 몸 앞으로 완전히 편 채 팔꿈치를 살짝 구부리고, 상체를 허리에서 약 30도 앞으로 숙인다. 팔이 완전히 펴지지 않으면 펴질 때까지 조금 더 뒤로 물러서야 한다. 팔이 완전히 펴지고 상체가 허리에서 살짝 숙여지면 광배근에 힘을 준 뒤 시작할 준비가 된다.", "팔을 편 상태를 유지한 채 광배근을 수축시켜 손이 허벅지 옆에 올 때까지 바를 아래로 당긴다. 이 동작을 하는 동안 숨을 내쉰다.", "팔을 편 상태를 유지한 채 숨을 들이마시며 시작 자세로 돌아간다.", "권장 반복 횟수만큼 반복한다."], en: ["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.", "Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.", "While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.", "While keeping the arms straight, go back to the starting position while breathing in.", "Repeat for the recommended amount of repetitions."] },
  "풀업": { s: "Pullups/0.jpg", e: "Pullups/1.jpg", k: ["정해진 그립으로 손바닥이 앞을 향하게 풀업 바를 잡는다. 그립 참고: 와이드 그립은 어깨너비보다 넓게, 미디엄 그립은 어깨너비와 같게, 클로즈 그립은 어깨너비보다 좁게 손을 벌린다.", "선택한 그립 너비로 바를 잡고 양팔을 편 상태에서, 상체를 약 30도 정도 뒤로 젖히며 허리에 커브를 만들고 가슴을 내민다. 이것이 시작 자세다.", "어깨와 위팔을 아래로, 뒤로 당겨 바가 윗가슴에 닿을 때까지 상체를 끌어 올린다. 이 동작을 하는 동안 숨을 내쉰다. 팁: 완전히 수축된 지점에 도달하면 등 근육을 쥐어짜듯 수축시키는 데 집중한다. 상체는 공간을 이동하는 동안에도 고정된 상태를 유지하고 팔만 움직여야 한다. 아래팔은 바를 잡는 것 외에 다른 일을 하지 않는다.", "수축 자세에서 1초간 유지한 뒤, 숨을 들이마시며 팔이 완전히 펴지고 광배근이 완전히 늘어날 때까지 상체를 천천히 시작 자세로 내린다.", "정해진 반복 횟수만큼 이 동작을 반복한다."], en: ["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.", "Repeat this motion for the prescribed amount of repetitions."] },
  "친업": { s: "Chin-Up/0.jpg", e: "Chin-Up/1.jpg", k: ["손바닥이 몸통을 향하도록 어깨너비보다 좁은 그립으로 풀업 바를 잡는다.", "선택한 그립 너비로 바를 잡고 양팔을 앞으로 뻗은 상태에서, 허리에 아치를 만들고 가슴을 내밀며 몸통을 최대한 곧게 편다. 이것이 시작 자세다. 팁: 몸통을 최대한 곧게 유지하면 등 개입을 최소화하면서 이두근 자극을 극대화할 수 있다.", "숨을 내쉬면서 머리가 풀업 바 높이에 오도록 몸통을 끌어올린다. 이두근을 사용해 동작을 수행하는 데 집중한다. 팔꿈치는 몸에 가깝게 유지한다. 팁: 상체는 공간을 이동하는 동안 고정된 상태를 유지하고 오직 팔만 움직여야 한다. 전완은 바를 잡는 것 외에 다른 일을 해서는 안 된다.", "수축된 자세에서 1초간 이두근을 짜준 뒤, 팔이 완전히 펴질 때까지 몸통을 천천히 시작 자세로 내린다. 이 구간에서는 숨을 들이쉰다.", "권장 반복 횟수만큼 이 동작을 반복한다."], en: ["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.", "As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."] },
  "머신 로우": { s: "Leverage_Iso_Row/0.jpg", e: "Leverage_Iso_Row/1.jpg", k: ["핀에 적절한 중량을 걸고 핸들이 가슴 높이에 오도록 시트 높이를 조절한다. 뉴트럴 또는 오버핸드(엎어 쥐기) 그립으로 핸들을 잡는다. 이것이 시작 자세다.", "팔꿈치를 굽히면서 견갑골을 모아 핸들을 몸통 쪽으로 당긴다.", "동작의 끝에서 잠시 멈춘 뒤, 핸들을 천천히 시작 자세로 되돌린다. 여러 번 반복할 때는 근육에 긴장을 유지하기 위해 중량을 완전히 멈춤 지점까지 되돌리지 않는다."], en: ["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."] },
  "하이퍼익스텐션": { s: "Hyperextensions_Back_Extensions/0.jpg", e: "Hyperextensions_Back_Extensions/1.jpg", k: ["하이퍼익스텐션 벤치에 엎드려 발목을 발판 아래에 단단히 고정한다.", "가능하다면 상단 패드를 조절해 허벅지 윗부분이 넓은 패드에 평평하게 놓이도록 하고, 허리를 자유롭게 굽힐 수 있는 공간을 확보한다.", "몸을 곧게 편 상태에서 양팔을 가슴 앞에서 교차하거나(추천) 머리 뒤로 둔다. 이것이 시작 자세다. 팁: 교차한 팔 아래에 원판을 들면 추가 저항을 줄 수 있다.", "등을 편평하게 유지하면서 허리를 천천히 가능한 만큼 앞으로 굽힌다. 이 동작을 하는 동안 숨을 들이쉰다. 햄스트링이 시원하게 늘어나는 느낌이 들고 등을 둥글게 말지 않고는 더 내려갈 수 없을 때까지 계속 앞으로 굽힌다. 팁: 이 운동을 할 때 절대 등을 둥글게 말지 않는다. 사람마다 가동 범위가 다를 수 있는데, 핵심은 등을 말지 않는 선에서 몸이 허락하는 만큼만 내려가는 것이다.", "숨을 들이쉬면서 몸통을 천천히 시작 자세로 다시 들어올린다. 팁: 일직선을 넘어 등을 과도하게 아치로 젖히려는 유혹을 피한다. 또한 부상을 막기 위해 어느 순간에도 몸통을 반동으로 휘두르지 않는다.", "권장 반복 횟수만큼 반복한다."], en: ["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.", "Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.", "With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.", "Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.", "Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.", "Repeat for the recommended amount of repetitions."] },
  "굿모닝": { s: "Good_Morning/0.jpg", e: "Good_Morning/1.jpg", k: ["바를 어깨 높이의 랙에 걸어 시작한다. 파워 스쿼트를 하듯 바를 어깨 위가 아니라 어깨 뒤쪽에 얹는다. 등을 단단히 조이고 견갑골을 모으며 무릎을 살짝 굽힌다. 랙에서 한 걸음 물러선다.", "엉덩이를 뒤로 빼면서 굽혀 상체가 바닥과 거의 평행이 될 때까지 숙인다. 등은 아치를 유지하고 경추(목뼈)는 올바른 정렬을 유지한다.", "둔근과 햄스트링을 사용해 엉덩이를 펴며 동작을 반대로 되돌린다. 시작 자세로 돌아올 때까지 계속한다."], en: ["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.", "Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.", "Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."] },
  "오버헤드 프레스": { s: "Barbell_Shoulder_Press/0.jpg", e: "Barbell_Shoulder_Press/1.jpg", k: ["스쿼트 랙 안의 등받이가 있는 벤치에 앉는다. 바벨을 머리 바로 위 높이에 위치시킨다. 오버핸드 그립(손바닥이 앞을 향하게)으로 바벨을 잡는다.", "올바른 그립 너비로 바벨을 들어올린 뒤, 팔을 완전히 펴 바를 머리 위로 들어올린다. 어깨 높이쯤, 머리보다 약간 앞에서 잡는다. 이것이 시작 자세다.", "숨을 들이쉬면서 바를 어깨까지 천천히 내린다.", "숨을 내쉬면서 바를 다시 시작 자세로 들어올린다.", "권장 반복 횟수만큼 반복한다."], en: ["Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).", "Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.", "Lower the bar down to the shoulders slowly as you inhale.", "Lift the bar back up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."] },
  "밀리터리 프레스": { s: "Standing_Military_Press/0.jpg", e: "Standing_Military_Press/1.jpg", k: ["가슴 높이쯤의 바벨을 스쿼트 랙에 걸어 시작한다. 중량을 선택한 뒤 오버핸드(손바닥이 앞을 향하게) 그립으로 바벨을 잡는다. 양손 간격은 어깨너비보다 넓게 잡는다.", "무릎을 살짝 굽히고 바벨을 쇄골 위에 올린다. 가슴에 얹은 채로 바벨을 들어올린다. 한 걸음 물러서서 발을 어깨너비로 벌린다.", "올바른 그립 너비로 바벨을 든 뒤, 팔을 완전히 펴 바를 머리 위로 들어올린다. 어깨 높이쯤, 머리보다 약간 앞에서 잡는다. 이것이 시작 자세다.", "숨을 들이쉬면서 바를 쇄골까지 천천히 내린다.", "숨을 내쉬면서 바를 다시 시작 자세로 들어올린다.", "권장 반복 횟수만큼 반복한다."], en: ["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.", "Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.", "Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.", "Lower the bar down to the collarbone slowly as you inhale.", "Lift the bar back up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."] },
  "덤벨 숄더 프레스": { s: "Dumbbell_Shoulder_Press/0.jpg", e: "Dumbbell_Shoulder_Press/1.jpg", k: ["양손에 덤벨을 든 채 등받이가 있는 밀리터리 프레스 벤치나 일반 벤치에 앉는다. 덤벨을 허벅지 위에 세워 올린다.", "이제 허벅지의 반동을 이용해 덤벨을 한쪽씩 어깨 높이까지 들어올린다.", "손바닥이 앞을 향하도록 손목을 돌린다. 이것이 시작 자세다.", "숨을 내쉬면서 덤벨이 맨 위에서 서로 닿을 때까지 위로 밀어올린다.", "맨 위 수축 자세에서 잠깐 멈춘 뒤, 숨을 들이쉬면서 천천히 중량을 시작 자세로 내린다.", "권장 반복 횟수만큼 반복한다."], en: ["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.", "Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.", "Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.", "Now, exhale and push the dumbbells upward until they touch at the top.", "Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."] },
  "아놀드 프레스": { s: "Arnold_Dumbbell_Press/0.jpg", e: "Arnold_Dumbbell_Press/1.jpg", k: ["등받이가 있는 벤치에 앉아 손바닥이 몸을 향하고 팔꿈치를 굽힌 채로 덤벨 두 개를 가슴 위쪽 높이에서 몸 앞에 든다. 팁: 팔은 몸통 옆에 붙어 있어야 한다. 시작 자세는 덤벨 컬의 수축된 부분과 비슷해 보여야 한다.", "동작을 수행하려면, 손바닥이 앞을 향할 때까지 회전시키면서 덤벨을 들어올린다.", "팔이 머리 위로 곧게 펴질 때까지 계속 덤벨을 들어올린다. 이 구간에서는 숨을 내쉰다.", "맨 위에서 1초간 멈춘 뒤, 손바닥을 다시 몸 쪽으로 회전시키면서 덤벨을 원래 자세로 내리기 시작한다. 팁: 왼팔은 시계 반대 방향으로, 오른팔은 시계 방향으로 회전한다. 이 구간에서는 숨을 들이쉰다.", "권장 반복 횟수만큼 반복한다."], en: ["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.", "Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.", "Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.", "After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."] },
  "숄더 프레스 머신": { s: "Leverage_Shoulder_Press/0.jpg", e: "Leverage_Shoulder_Press/1.jpg", k: ["핀에 적절한 중량을 걸고 키에 맞게 시트를 조절한다. 동작 시작 시 핸들이 어깨 위쪽 근처에 와야 한다. 가슴과 머리를 세우고 오버핸드 그립으로 핸들을 잡는다. 이것이 시작 자세다.", "팔꿈치를 펴며 핸들을 위로 밀어올린다.", "맨 위에서 잠깐 멈춘 뒤, 중량을 시작 자세 바로 위까지 되돌린다. 세트가 끝날 때까지 중량을 멈춤 지점까지 내리지 않아 근육의 긴장을 유지한다."], en: ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.", "Press the handles upward by extending through the elbow.", "After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."] },
  "덤벨 레터럴 레이즈": { s: "Side_Lateral_Raise/0.jpg", e: "Side_Lateral_Raise/1.jpg", k: ["덤벨 두 개를 들고 몸통을 곧게 편 채 서서, 손바닥이 몸을 향하도록 덤벨을 팔을 편 상태로 몸 옆에 둔다. 이것이 시작 자세다.", "몸통을 고정한 채(반동 금지) 팔꿈치를 살짝 굽히고 물을 잔에 따르듯 손을 약간 앞으로 기울여 덤벨을 옆으로 들어올린다. 팔이 바닥과 평행해질 때까지 계속 올린다. 이 동작을 하는 동안 숨을 내쉬고 맨 위에서 1초간 멈춘다.", "숨을 들이쉬면서 덤벨을 천천히 시작 자세로 다시 내린다.", "권장 반복 횟수만큼 반복한다."], en: ["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.", "While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.", "Lower the dumbbells back down slowly to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."] },
  "케이블 레터럴 레이즈": { s: "Cable_Seated_Lateral_Raise/0.jpg", e: "Cable_Seated_Lateral_Raise/1.jpg", k: ["서로 마주 보는 두 개의 로우 풀리 중앙에 서서 바로 뒤에 플랫 벤치를 놓는다(몸과 수직 방향으로, 벤치의 좁은 끝이 뒤쪽에 오도록). 각 풀리에 사용할 중량을 선택한다.", "이제 뒤의 플랫 벤치 끝에 앉아 발을 무릎보다 앞에 둔다.", "등을 편평하게 유지하면서 앞으로 굽혀 몸통을 허벅지에 기댄다.", "누군가에게 풀리에 연결된 단일 핸들을 건네받는다. 중량을 선택한 뒤 오른손으로 왼쪽 풀리를, 왼손으로 오른쪽 풀리를 잡는다. 케이블은 무릎 아래로 지나가고 팔은 손바닥이 서로 마주 본 채 팔꿈치를 살짝 굽혀 뻗은 상태다. 이것이 시작 자세다.", "팔을 고정한 채 위팔을 옆으로 들어올려 바닥과 평행하고 어깨 높이가 될 때까지 올린다. 이 동작 중에 숨을 내쉬고 수축을 1초간 유지한다.", "숨을 들이쉬면서 팔을 천천히 시작 자세로 내린다.", "권장 반복 횟수만큼 반복한다. 팁: 운동 내내 위팔을 몸통과 수직으로, 팔꿈치를 고정된 각도(10~30도)로 유지한다."], en: ["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.", "Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.", "Bend forward while keeping your back flat and rest your torso on the thighs.", "Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.", "While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.", "Slowly lower your arms to the starting position as you inhale.", "Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise."] },
  "프론트 레이즈": { s: "Front_Dumbbell_Raise/0.jpg", e: "Front_Dumbbell_Raise/1.jpg", k: ["덤벨 두 개를 들고 몸통을 곧게 편 채 서서, 손바닥이 허벅지를 향하도록 덤벨을 팔을 편 상태로 허벅지 앞에 둔다. 이것이 시작 자세다.", "몸통을 고정한 채(반동 금지) 팔꿈치를 살짝 굽히고 손바닥이 항상 아래를 향하도록 하여 왼쪽 덤벨을 앞으로 들어올린다. 팔이 바닥과 평행선보다 약간 위에 올 때까지 계속 올린다. 이 구간에서 숨을 내쉬고 맨 위에서 1초간 멈춘다. 1초 멈춤 후 숨을 들이쉰다.", "이제 오른쪽 덤벨을 동시에 들어올리면서 왼쪽 덤벨을 천천히 시작 자세로 내린다.", "양팔 모두 권장 반복 횟수를 채울 때까지 이런 식으로 번갈아 계속한다."], en: ["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.", "While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.", "Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.", "Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."] },
  "덤벨 리어 델트 플라이": { s: "Reverse_Flyes/0.jpg", e: "Reverse_Flyes/1.jpg", k: ["시작하려면 가슴과 배가 인클라인 면에 눌리도록 인클라인 벤치에 엎드린다. 양손에 손바닥이 서로 마주 보도록(뉴트럴 그립) 덤벨을 든다.", "팔을 앞으로 뻗어 벤치의 각도와 수직이 되게 한다. 발끝으로 바닥을 누르며 다리는 고정한다. 이것이 시작 자세다.", "팔꿈치를 살짝 굽힌 상태를 유지하며 숨을 내쉬면서 덤벨을 호를 그리듯 바깥쪽 옆으로 벌려 올린다. 팁: 견갑골을 모아주면 이 운동의 효과를 가장 잘 얻을 수 있다.", "팔은 바닥과 평행해질 때까지 들어올린다.", "수축을 느끼며 숨을 들이쉬면서 천천히 덤벨을 시작 자세로 내린다.", "권장 반복 횟수만큼 반복한다."], en: ["To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).", "Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.", "Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.", "The arms should be elevated until they are parallel to the floor.", "Feel the contraction and slowly lower the weights back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."] },
  "리버스 펙 덱": { s: "Reverse_Machine_Flyes/0.jpg", e: "Reverse_Machine_Flyes/1.jpg", k: ["핸들이 완전히 뒤쪽으로 오도록 조절한다. 적절한 중량을 선택하고 핸들이 어깨 높이에 오도록 시트 높이를 조절한다. 손바닥이 안쪽을 향하도록 핸들을 잡는다. 이것이 시작 자세다.", "반원을 그리는 동작으로 후면 삼각근을 수축시키며 손을 옆으로 그리고 뒤로 당긴다.", "동작 내내 팔을 살짝 굽힌 상태를 유지하고, 모든 움직임이 어깨 관절에서 일어나도록 한다.", "동작의 끝에서 잠시 멈춘 뒤, 천천히 중량을 시작 자세로 되돌린다."], en: ["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.", "In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.", "Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.", "Pause at the rear of the movement, and slowly return the weight to the starting position."] },
  "페이스 풀": { s: "Face_Pull/0.jpg", e: "Face_Pull/1.jpg", k: ["로프나 듀얼 핸들이 달린 하이 풀리를 마주 보고 서서, 당기면서 양손을 벌리며 중량을 얼굴 쪽으로 곧장 당긴다. 위팔은 바닥과 평행하게 유지한다."], en: ["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."] },
  "업라이트 로우": { s: "Upright_Barbell_Row/0.jpg", e: "Upright_Barbell_Row/1.jpg", k: ["어깨너비보다 약간 좁은 오버핸드 그립으로 바벨을 잡는다. 바는 팔을 편 채 팔꿈치를 살짝 굽혀 허벅지 위쪽에 놓여 있어야 한다. 등도 곧게 편다. 이것이 시작 자세다.", "이제 숨을 내쉬면서 어깨 측면을 사용해 바를 들어올리며 팔꿈치를 위로 옆으로 올린다. 바를 몸에 가깝게 유지하며 들어올린다. 바가 턱에 거의 닿을 때까지 계속 올린다. 팁: 팔꿈치가 동작을 주도해야 하며 항상 전완보다 높아야 한다. 몸통은 고정하고 동작의 맨 위에서 1초간 멈춘다.", "바를 천천히 시작 자세로 다시 내린다. 이 구간에서는 숨을 들이쉰다.", "권장 반복 횟수만큼 반복한다."], en: ["Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.", "Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.", "Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."] },
  "바벨 컬": { s: "Barbell_Curl/0.jpg", e: "Barbell_Curl/1.jpg", k: ["몸통을 곧게 세우고 서서 어깨너비 그립으로 바벨을 든다. 손바닥은 앞을 향하고 팔꿈치는 몸통에 가깝게 둔다. 이것이 시작 자세다.", "위팔을 고정한 채, 숨을 내쉬면서 이두근을 수축시켜 중량을 앞으로 컬한다. 팁: 오직 전완만 움직여야 한다.", "이두근이 완전히 수축되고 바가 어깨 높이에 올 때까지 동작을 계속한다. 수축 자세를 1초간 유지하며 이두근을 강하게 짜준다.", "숨을 들이쉬면서 천천히 바를 시작 자세로 되돌리기 시작한다.", "권장 반복 횟수만큼 반복한다."], en: ["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.", "While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.", "Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.", "Slowly begin to bring the bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."] },
  "이지바 컬": { s: "EZ-Bar_Curl/0.jpg", e: "EZ-Bar_Curl/1.jpg", k: ["EZ 컬 바의 넓은 바깥쪽 손잡이를 잡고 곧게 선다. 손바닥은 앞을 향하되 바의 모양 때문에 약간 안쪽으로 기울어진다. 팔꿈치는 몸통에 가깝게 둔다. 이것이 시작 자세다.", "이제 위팔을 고정한 채 숨을 내쉬면서 이두근을 수축시켜 중량을 앞으로 컬한다. 오직 전완만 움직이는 데 집중한다.", "이두근이 완전히 수축되고 바가 어깨 높이에 올 때까지 계속 들어올린다. 맨 위 수축 자세를 잠시 유지하며 이두근을 짜준다.", "그다음 숨을 들이쉬면서 천천히 바를 시작 자세로 내린다.", "권장 반복 횟수만큼 반복한다."], en: ["Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.", "Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.", "Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.", "Then inhale and slowly lower the bar back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "덤벨 컬": { s: "Dumbbell_Bicep_Curl/0.jpg", e: "Dumbbell_Bicep_Curl/1.jpg", k: ["양손에 덤벨을 든 채 팔을 펴고 곧게 선다. 팔꿈치를 몸통에 가깝게 두고 손바닥이 앞을 향할 때까지 돌린다. 이것이 시작 자세다.", "이제 위팔을 고정한 채 숨을 내쉬면서 이두근을 수축시켜 중량을 컬한다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 들어올린다. 이두근을 짜주며 수축 자세를 잠시 유지한다.", "그다음 숨을 들이쉬면서 천천히 덤벨을 시작 자세로 내리기 시작한다.", "권장 반복 횟수만큼 반복한다."], en: ["Stand up straight with a dumbbell in each hand at arm's length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.", "Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "해머 컬": { s: "Hammer_Curls/0.jpg", e: "Hammer_Curls/1.jpg", k: ["몸통을 곧게 세우고 서서 양손에 덤벨을 팔을 편 상태로 든다. 팔꿈치는 몸통에 가깝게 둔다.", "손바닥은 몸통을 향해야 한다. 이것이 시작 자세다.", "이제 위팔을 고정한 채 숨을 내쉬면서 이두근을 수축시켜 중량을 앞으로 컬한다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 들어올린다. 이두근을 짜주며 수축 자세를 잠시 유지한다. 팁: 팔꿈치를 고정하고 오직 전완만 움직이는 데 집중한다.", "잠시 멈춘 뒤, 숨을 들이쉬면서 천천히 덤벨을 시작 자세로 내리기 시작한다.", "권장 반복 횟수만큼 반복한다."], en: ["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.", "The palms of the hands should be facing your torso. This will be your starting position.", "Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.", "After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "인클라인 덤벨 컬": { s: "Incline_Dumbbell_Curl/0.jpg", e: "Incline_Dumbbell_Curl/1.jpg", k: ["양손에 덤벨을 팔을 편 상태로 들고 인클라인 벤치에 기대어 앉는다. 팔꿈치를 몸통에 가깝게 두고 손바닥이 앞을 향할 때까지 돌린다. 이것이 시작 자세다.", "위팔을 고정한 채 숨을 내쉬면서 이두근을 수축시켜 중량을 앞으로 컬한다. 오직 전완만 움직여야 한다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 동작을 계속한다. 수축 자세를 1초간 유지한다.", "숨을 들이쉬면서 천천히 덤벨을 시작 자세로 되돌리기 시작한다.", "권장 반복 횟수만큼 반복한다."], en: ["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.", "While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.", "Slowly begin to bring the dumbbells back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."] },
  "프리처 컬": { s: "Preacher_Curl/0.jpg", e: "Preacher_Curl/1.jpg", k: ["이 동작을 하려면 프리처 벤치와 EZ 바가 필요하다. EZ 컬 바의 가까운 안쪽 손잡이를 잡는다(누군가 바를 건네주는 것이 가장 좋고, 아니면 대부분의 프리처 벤치에 있는 앞쪽 거치대에서 바를 잡는다). 손바닥은 앞을 향하되 바의 모양 때문에 약간 안쪽으로 기울어진다.", "위팔을 프리처 벤치 패드에 대고 가슴을 붙인 채, EZ 컬 바를 팔을 편 상태로 어깨 높이에 든다. 이것이 시작 자세다.", "숨을 들이쉬면서 위팔이 펴지고 이두근이 완전히 늘어날 때까지 천천히 바를 내린다.", "숨을 내쉬면서 이두근을 사용해 이두근이 완전히 수축되고 바가 어깨 높이에 올 때까지 중량을 컬한다. 이두근을 강하게 짜주며 이 자세를 1초간 유지한다.", "권장 반복 횟수만큼 반복한다."], en: ["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.", "With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.", "As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.", "As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.", "Repeat for the recommended amount of repetitions."] },
  "컨센트레이션 컬": { s: "Concentration_Curls/0.jpg", e: "Concentration_Curls/1.jpg", k: ["플랫 벤치에 앉아 다리 사이 앞에 덤벨 하나를 둔다. 다리는 벌리고 무릎을 굽혀 발을 바닥에 붙인다.", "오른팔로 덤벨을 집어 든다. 오른쪽 위팔 뒤쪽을 오른쪽 허벅지 안쪽 위에 댄다. 손바닥이 허벅지에서 멀어져 앞을 향할 때까지 돌린다. 팁: 팔은 펴져 있고 덤벨은 바닥 위에 떠 있어야 한다. 이것이 시작 자세다.", "위팔을 고정한 채 숨을 내쉬면서 이두근을 수축시켜 중량을 앞으로 컬한다. 오직 전완만 움직여야 한다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 동작을 계속한다. 팁: 동작의 맨 위에서 새끼손가락이 엄지보다 높게 오도록 한다. 이렇게 하면 확실한 수축이 보장된다. 이두근을 짜주며 수축 자세를 1초간 유지한다.", "숨을 들이쉬면서 천천히 덤벨을 시작 자세로 되돌리기 시작한다. 주의: 어느 순간에도 반동 동작을 피한다.", "권장 반복 횟수만큼 반복한다. 그다음 왼팔로 동작을 반복한다."], en: ["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.", "Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.", "While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.", "Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.", "Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."] },
  "케이블 컬": { s: "Standing_Biceps_Cable_Curl/0.jpg", e: "Standing_Biceps_Cable_Curl/1.jpg", k: ["로우 풀리에 연결된 케이블 컬 바를 든 채 몸통을 곧게 세우고 선다. 어깨너비로 케이블 바를 잡고 팔꿈치를 몸통에 가깝게 둔다. 손바닥은 위를 향해야 한다(언더핸드 그립). 이것이 시작 자세다.", "위팔을 고정한 채 숨을 내쉬면서 이두근을 수축시켜 중량을 컬한다. 오직 전완만 움직여야 한다. 이두근이 완전히 수축되고 바가 어깨 높이에 올 때까지 동작을 계속한다. 근육을 짜주며 수축 자세를 1초간 유지한다.", "숨을 들이쉬면서 천천히 컬 바를 시작 자세로 되돌리기 시작한다.", "권장 반복 횟수만큼 반복한다."], en: ["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.", "While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.", "Slowly begin to bring the curl bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."] },
  "스파이더 컬": { s: "Spider_Curl/0.jpg", e: "Spider_Curl/1.jpg", k: ["평소 앉는 프리처 벤치 부분에 바를 올려놓고 시작한다. 바벨이 균형을 잃고 떨어지지 않도록 제대로 정렬한다.", "프리처 벤치의 앞쪽(보통 팔을 얹는 부분)으로 이동해, 몸통과 배가 프리처 벤치 앞면에 눌리도록 45도 경사로 엎드린다.", "발(특히 발끝)이 바닥에 잘 고정되도록 하고, 위팔을 프리처 벤치 안쪽 패드 위에 올린다.", "팔을 사용해 언더핸드 그립(손바닥이 위를 향하게)으로 어깨너비 정도 또는 그보다 약간 좁게 바벨을 잡는다.", "숨을 내쉬면서 천천히 바벨을 위로 들어올리기 시작한다. 이두근을 짜주며 수축 자세를 1초간 유지한다.", "숨을 들이쉬면서 천천히 바벨을 시작 자세로 되돌리기 시작한다.", "권장 반복 횟수만큼 반복한다."], en: ["Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.", "Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.", "Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.", "Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.", "Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.", "Slowly begin to bring the barbell back to the starting position as your breathe in. .", "Repeat for the recommended amount of repetitions."] },
  "머신 컬": { s: "Machine_Bicep_Curl/0.jpg", e: "Machine_Bicep_Curl/1.jpg", k: ["시트를 적절한 높이로 조절하고 중량을 선택한다. 위팔을 패드에 대고 핸들을 잡는다. 이것이 시작 자세다.", "팔꿈치를 굽혀 전완을 위팔 쪽으로 당기며 동작을 수행한다.", "동작의 맨 위에서 잠시 멈춘 뒤, 천천히 중량을 시작 자세로 되돌린다.", "세트가 끝날 때까지 중량을 멈춤 지점까지 완전히 되돌리지 않아 근육의 긴장을 유지한다."], en: ["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.", "Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.", "Pause at the top of the movement, and then slowly return the weight to the starting position.", "Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."] },
  "클로즈 그립 벤치프레스": { s: "Close-Grip_Barbell_Bench_Press/0.jpg", e: "Close-Grip_Barbell_Bench_Press/1.jpg", k: ["플랫 벤치에 등을 대고 눕습니다. 어깨너비 정도의 좁은 그립으로 바를 랙에서 들어 팔을 완전히 편 채 몸 위로 곧게 듭니다. 이 자세가 시작 자세입니다.", "숨을 들이마시며 바가 가슴 중앙에 닿을 때까지 천천히 내립니다. 팁: 일반 벤치프레스와 달리 삼두 개입을 극대화하기 위해 팔꿈치를 항상 몸통 가까이 붙이세요.", "1초 멈춘 뒤 숨을 내쉬며 삼두 힘으로 바를 밀어 시작 자세로 되돌립니다. 수축 지점에서 팔을 완전히 펴 1초간 버틴 뒤 다시 천천히 내립니다. 팁: 내리는 동작은 올리는 동작보다 최소 두 배 느리게 하세요.", "정해진 반복 횟수만큼 동작을 반복합니다.", "끝나면 바를 랙에 다시 걸어둡니다."], en: ["Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."] },
  "트라이셉스 푸시다운": { s: "Triceps_Pushdown/0.jpg", e: "Triceps_Pushdown/1.jpg", k: ["하이 풀리에 스트레이트 바나 앵글 바를 걸고 어깨너비로 오버핸드 그립(손바닥이 아래를 향함)으로 잡습니다.", "상체를 곧게 세우고 아주 살짝 앞으로 기울인 채 서서, 위팔을 몸에 붙이고 바닥과 수직이 되게 합니다. 바를 잡은 팔뚝은 풀리를 향해 위쪽을 가리킵니다. 이 자세가 시작 자세입니다.", "삼두 힘으로 바를 허벅지 앞에 닿고 팔이 바닥과 수직으로 완전히 펴질 때까지 내립니다. 위팔은 항상 몸통 옆에 고정하고 팔뚝만 움직여야 합니다. 이 동작을 하며 숨을 내쉽니다.", "수축 지점에서 1초간 버틴 뒤 바를 천천히 시작 지점으로 올립니다. 이 동작을 하며 숨을 들이마십니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.", "Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."] },
  "로프 푸시다운": { s: "Triceps_Pushdown_-_Rope_Attachment/0.jpg", e: "Triceps_Pushdown_-_Rope_Attachment/1.jpg", k: ["하이 풀리에 로프를 걸고 뉴트럴 그립(손바닥이 서로 마주보게)으로 잡습니다.", "상체를 곧게 세우고 아주 살짝 앞으로 기울인 채 서서, 위팔을 몸에 붙이고 바닥과 수직이 되게 합니다. 로프를 손바닥이 마주보게 잡은 팔뚝은 풀리를 향해 위쪽을 가리킵니다. 이 자세가 시작 자세입니다.", "삼두 힘으로 로프를 내리면서 로프 양쪽 끝을 허벅지 옆으로 벌립니다. 동작이 끝나면 팔이 완전히 펴져 바닥과 수직이 됩니다. 위팔은 항상 몸통 옆에 고정하고 팔뚝만 움직여야 합니다. 이 동작을 하며 숨을 내쉽니다.", "수축 지점에서 1초간 버틴 뒤 로프를 천천히 시작 지점으로 올립니다. 이 동작을 하며 숨을 들이마십니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.", "Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."] },
  "오버헤드 트라이셉스 익스텐션": { s: "Seated_Triceps_Press/0.jpg", e: "Seated_Triceps_Press/1.jpg", k: ["등받이가 있는 벤치에 앉아 덤벨 하나를 양손으로 잡고 팔을 편 채 머리 위로 듭니다. 팁: 무게가 무겁다면 다른 사람에게 건네받는 편이 좋습니다. 덤벨은 손바닥 위에 얹고 엄지로 감싸 쥐며, 손바닥은 안쪽을 향하게 합니다. 이 자세가 시작 자세입니다.", "위팔을 머리 가까이(팔꿈치를 안으로 모으고) 바닥과 수직으로 유지한 채, 팔뚝이 이두에 닿을 때까지 덤벨을 머리 뒤로 반원을 그리며 내립니다. 팁: 위팔은 고정하고 팔뚝만 움직여야 합니다. 이 동작을 하며 숨을 들이마십니다.", "삼두 힘으로 덤벨을 들어올려 시작 자세로 되돌립니다. 이 동작을 하며 숨을 내쉽니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm's length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.", "Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.", "Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.", "Repeat for the recommended amount of repetitions."] },
  "케이블 오버헤드 익스텐션": { s: "Cable_Rope_Overhead_Triceps_Extension/0.jpg", e: "Cable_Rope_Overhead_Triceps_Extension/1.jpg", k: ["케이블 머신의 로우 풀리에 로프를 겁니다.", "로프를 양손으로 잡고 뉴트럴 그립(손바닥이 서로 마주보게)으로 손을 머리 바로 위로 뻗어 팔을 폅니다. 팔꿈치는 머리 가까이 모으고 팔은 바닥과 수직으로 하며 주먹은 천장을 향하게 합니다. 이 자세가 시작 자세입니다.", "위팔을 고정한 채 로프를 천천히 머리 뒤로 내립니다. 이 동작을 하며 숨을 들이마시고 삼두가 완전히 늘어난 지점에서 멈춥니다.", "숨을 내쉬며 삼두를 수축시켜 시작 자세로 되돌아갑니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Attach a rope to the bottom pulley of the pulley machine.", "Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.", "Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.", "Return to the starting position by flexing your triceps as you breathe out.", "Repeat for the recommended amount of repetitions."] },
  "스컬 크러셔": { s: "EZ-Bar_Skullcrusher/0.jpg", e: "EZ-Bar_Skullcrusher/1.jpg", k: ["벤치에 누워 좁은 그립으로 이지바를 들고 팔꿈치를 안으로 모아 잡습니다. 팔은 바닥과 수직이 되게 합니다. 이 자세가 시작 자세입니다.", "위팔을 고정한 채 팔꿈치를 굽혀 바를 내립니다. 이 동작을 하며 숨을 들이마십니다. 바가 이마 바로 위에 오면 멈춥니다.", "숨을 내쉬며 팔꿈치를 펴 바를 시작 자세로 들어올립니다.", "반복합니다."], en: ["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.", "Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.", "Lift the bar back to the starting position by extending the elbow and exhaling.", "Repeat."] },
  "트라이셉스 킥백": { s: "Tricep_Dumbbell_Kickback/0.jpg", e: "Tricep_Dumbbell_Kickback/1.jpg", k: ["양손에 덤벨을 들고 손바닥이 몸통을 향하게 합니다. 등을 곧게 펴고 무릎을 살짝 굽힌 채 허리를 앞으로 숙입니다. 상체는 바닥과 거의 평행이 되어야 합니다. 머리는 들고 있으세요. 위팔은 몸통에 붙이고 바닥과 평행하게 하며, 덤벨을 든 팔뚝은 바닥을 향하게 합니다. 팔뚝과 위팔은 90도 각도를 이뤄야 합니다. 이 자세가 시작 자세입니다.", "이제 위팔을 고정한 채 숨을 내쉬며 삼두 힘으로 팔이 완전히 펴질 때까지 덤벨을 들어올립니다. 팔뚝만 움직이는 데 집중하세요.", "정점의 수축 지점에서 잠시 멈춘 뒤 숨을 들이마시며 덤벨을 천천히 시작 자세로 내립니다.", "정해진 반복 횟수만큼 동작을 반복합니다."], en: ["Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.", "Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.", "After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.", "Repeat the movement for the prescribed amount of repetitions."] },
  "벤치 딥스": { s: "Bench_Dips/0.jpg", e: "Bench_Dips/1.jpg", k: ["이 운동을 하려면 등 뒤에 벤치를 놓아야 합니다. 벤치를 몸과 수직으로 두고 벤치를 등진 채, 팔을 완전히 펴 어깨너비로 벤치 모서리를 잡습니다. 다리는 앞으로 뻗어 골반에서 굽혀 상체와 수직이 되게 합니다. 이 자세가 시작 자세입니다.", "숨을 들이마시며 팔꿈치를 굽혀 위팔과 팔뚝 사이 각도가 90도보다 조금 작아질 때까지 몸을 천천히 내립니다. 팁: 동작 내내 팔꿈치를 최대한 붙이세요. 팔뚝은 항상 아래를 향해야 합니다.", "삼두 힘으로 상체를 다시 밀어올려 시작 자세로 되돌아갑니다.", "권장 반복 횟수만큼 반복합니다."], en: ["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.", "Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.", "Using your triceps to bring your torso up again, lift yourself back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "다이아몬드 푸시업": { s: "Push-Ups_-_Close_Triceps_Position/0.jpg", e: "Push-Ups_-_Close_Triceps_Position/1.jpg", k: ["바닥에 엎드려 손을 어깨너비보다 좁게 모아 짚습니다. 팔을 편 채 상체를 들어 지탱하세요.", "숨을 들이마시며 가슴이 바닥에 거의 닿을 때까지 몸을 내립니다.", "삼두와 가슴 근육의 일부를 사용해 상체를 시작 자세로 밀어올리며 가슴을 쥐어짭니다. 이 동작을 하며 숨을 내쉽니다.", "수축 지점에서 1초 멈춘 뒤 정해진 반복 횟수만큼 동작을 반복합니다."], en: ["Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms' length.", "Lower yourself until your chest almost touches the floor as you inhale.", "Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."] },
  "리스트 컬": { s: "Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg", e: "Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg", k: ["손바닥이 위를 향하게 양손으로 바벨을 잡고, 손 간격은 어깨너비 정도로 벌립니다.", "발을 어깨너비보다 조금 넓게 벌려 바닥에 평평하게 딛습니다.", "앞으로 숙여 손바닥이 위를 향한 채 팔뚝을 허벅지 위에 올립니다. 팁: 손목 앞쪽이 무릎 위에 오도록 하세요. 이 자세가 시작 자세입니다.", "그립을 단단히 유지하며 숨을 들이마시고 바를 최대한 낮게 내립니다.", "이제 숨을 내쉬며 팔뚝을 수축시켜 바를 최대한 높이 말아 올립니다. 정점에서 1초간 수축을 유지하세요. 팁: 손목만 움직여야 합니다."], en: ["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.", "Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.", "Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position.", "Lower the bar as far as possible while inhaling and keeping a tight grip.", "Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."] },
  "리버스 리스트 컬": { s: "Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg", e: "Seated_Palms-Down_Barbell_Wrist_Curl/1.jpg", k: ["손바닥이 아래를 향하게 양손으로 바벨을 잡고, 손 간격은 어깨너비 정도로 벌립니다.", "발을 어깨너비보다 조금 넓게 벌려 바닥에 평평하게 딛습니다.", "앞으로 숙여 손바닥이 아래를 향한 채 팔뚝을 허벅지 위에 올립니다. 팁: 손목 뒤쪽이 무릎 위에 오도록 하세요. 이 자세가 시작 자세입니다.", "그립을 단단히 유지하며 숨을 들이마시고 바를 최대한 낮게 내립니다.", "이제 숨을 내쉬며 팔뚝을 수축시켜 바를 최대한 높이 말아 올립니다. 정점에서 1초간 수축을 유지하세요. 팁: 손목만 움직여야 합니다."], en: ["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.", "Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.", "Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position.", "Lower the bar as far as possible while inhaling and keeping a tight grip.", "Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."] },
  "리버스 바벨 컬": { s: "Reverse_Barbell_Curl/0.jpg", e: "Reverse_Barbell_Curl/1.jpg", k: ["상체를 곧게 세우고 서서 팔꿈치를 몸통에 붙인 채 어깨너비로 바벨을 잡습니다. 손바닥은 아래를 향하게 합니다(오버핸드 그립). 이 자세가 시작 자세입니다.", "위팔을 고정한 채 숨을 내쉬며 이두를 수축시켜 바를 말아 올립니다. 팔뚝만 움직여야 합니다. 이두가 완전히 수축되고 바가 어깨 높이에 올 때까지 동작을 이어갑니다. 수축 지점에서 근육을 쥐어짜며 1초간 버팁니다.", "숨을 들이마시며 바를 천천히 시작 자세로 되돌립니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.", "While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.", "Slowly begin to bring the bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."] },
  "바벨 스쿼트": { s: "Barbell_Squat/0.jpg", e: "Barbell_Squat/1.jpg", k: ["이 운동은 안전을 위해 스쿼트 랙 안에서 하는 것이 가장 좋습니다. 먼저 바를 어깨보다 살짝 아래 높이의 랙에 겁니다. 높이를 맞추고 무게를 걸었으면 바 아래로 들어가 어깨 뒤쪽(목보다 살짝 아래)에 바를 얹습니다.", "양팔로 바 양쪽을 잡고, 다리로 밀면서 동시에 상체를 세워 바를 랙에서 들어올립니다.", "랙에서 물러나 발끝을 살짝 바깥으로 향한 어깨너비의 중간 스탠스로 다리를 벌립니다. 머리는 항상 들고 등은 곧게 유지하세요. 이 자세가 시작 자세입니다. (참고: 여기서는 전반적 발달을 목표로 하는 위 중간 스탠스를 기준으로 설명하지만, 발 스탠스 항목에서 다룬 세 가지 스탠스 중 어느 것이든 선택할 수 있습니다.)", "머리를 든 곧은 자세를 유지하며 무릎과 고관절을 굽혀 바를 천천히 내리기 시작합니다. 허벅지와 종아리 사이 각도가 90도보다 조금 작아질 때까지 내립니다. 이 동작을 하며 숨을 들이마십니다. 팁: 올바로 수행했다면 무릎 앞이 발끝과 정면에 수직인 가상의 직선을 이뤄야 합니다. 무릎이 그 선을 넘어가면(발끝을 넘어가면) 무릎에 과도한 부담이 가는 것으로 잘못 수행한 것입니다.", "숨을 내쉬며 발뒤꿈치로 바닥을 밀어 다리를 다시 펴면서 바를 들어올려 시작 자세로 돌아갑니다.", "권장 반복 횟수만큼 반복합니다."], en: ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "프론트 스쿼트": { s: "Front_Barbell_Squat/0.jpg", e: "Front_Barbell_Squat/1.jpg", k: ["이 운동은 안전을 위해 스쿼트 랙 안에서 하는 것이 가장 좋습니다. 먼저 자신의 키에 가장 잘 맞는 높이의 랙에 바를 겁니다. 높이를 맞추고 무게를 걸었으면 팔꿈치를 높이 들고 위팔을 바닥과 평행보다 살짝 위로 유지한 채 바 아래로 팔을 넣습니다. 바를 삼각근 위에 얹고, 완전히 제어하기 위해 팔을 교차해 바를 잡습니다.", "다리로 밀면서 동시에 상체를 세워 바를 랙에서 들어올립니다.", "랙에서 물러나 발끝을 살짝 바깥으로 향한 어깨너비의 중간 스탠스로 다리를 벌립니다. 아래를 보면 균형을 잃으니 머리는 항상 들고 등은 곧게 유지하세요. 이 자세가 시작 자세입니다. (참고: 여기서는 전반적 발달을 목표로 하는 위 중간 스탠스를 기준으로 설명하지만, 발 위치 항목에서 다룬 세 가지 스탠스 중 어느 것이든 선택할 수 있습니다.)", "머리를 든 곧은 자세를 유지하며 무릎을 굽혀 바를 천천히 내리기 시작합니다. 허벅지와 종아리 사이 각도가 90도보다 조금 작아질 때까지(허벅지가 바닥과 평행보다 아래로 내려가는 지점) 내립니다. 이 동작을 하며 숨을 들이마십니다. 팁: 올바로 수행했다면 무릎 앞이 발끝과 정면에 수직인 가상의 직선을 이뤄야 합니다. 무릎이 그 선을 넘어가면(발끝을 넘어가면) 무릎에 과도한 부담이 가는 것으로 잘못 수행한 것입니다.", "숨을 내쉬며 주로 발 중앙으로 바닥을 밀어 다리를 다시 펴면서 바를 들어올려 시작 자세로 돌아갑니다.", "권장 반복 횟수만큼 반복합니다."], en: ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.", "Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "하이바 스쿼트": { s: "Barbell_Squat/0.jpg", e: "Barbell_Squat/1.jpg", k: ["이 운동은 안전을 위해 스쿼트 랙 안에서 하는 것이 가장 좋습니다. 먼저 바를 어깨보다 살짝 아래 높이의 랙에 겁니다. 높이를 맞추고 무게를 걸었으면 바 아래로 들어가 어깨 뒤쪽(목보다 살짝 아래)에 바를 얹습니다.", "양팔로 바 양쪽을 잡고, 다리로 밀면서 동시에 상체를 세워 바를 랙에서 들어올립니다.", "랙에서 물러나 발끝을 살짝 바깥으로 향한 어깨너비의 중간 스탠스로 다리를 벌립니다. 머리는 항상 들고 등은 곧게 유지하세요. 이 자세가 시작 자세입니다. (참고: 여기서는 전반적 발달을 목표로 하는 위 중간 스탠스를 기준으로 설명하지만, 발 스탠스 항목에서 다룬 세 가지 스탠스 중 어느 것이든 선택할 수 있습니다.)", "머리를 든 곧은 자세를 유지하며 무릎과 고관절을 굽혀 바를 천천히 내리기 시작합니다. 허벅지와 종아리 사이 각도가 90도보다 조금 작아질 때까지 내립니다. 이 동작을 하며 숨을 들이마십니다. 팁: 올바로 수행했다면 무릎 앞이 발끝과 정면에 수직인 가상의 직선을 이뤄야 합니다. 무릎이 그 선을 넘어가면(발끝을 넘어가면) 무릎에 과도한 부담이 가는 것으로 잘못 수행한 것입니다.", "숨을 내쉬며 발뒤꿈치로 바닥을 밀어 다리를 다시 펴면서 바를 들어올려 시작 자세로 돌아갑니다.", "권장 반복 횟수만큼 반복합니다."], en: ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "핵 스쿼트": { s: "Hack_Squat/0.jpg", e: "Hack_Squat/1.jpg", k: ["상체 뒤쪽을 머신의 등받이 패드에 대고 어깨를 어깨 패드 아래에 겁니다.", "발끝을 살짝 바깥으로 향한 어깨너비의 중간 스탠스로 발판에 다리를 놓습니다. 팁: 머리는 항상 들고 등은 항상 패드에 붙여 유지하세요.", "팔을 머신 옆쪽 손잡이에 얹고 안전바를 해제합니다(대부분의 기종에서는 옆 손잡이를 정면 위치에서 대각선 위치로 돌려 해제합니다).", "이제 무릎을 완전히 잠그지 않은 채 다리를 폅니다. 이 자세가 시작 자세입니다. (참고: 여기서는 전반적 발달을 목표로 하는 위 중간 스탠스를 기준으로 설명하지만, 발 위치 항목에서 다룬 세 가지 스탠스 중 어느 것이든 선택할 수 있습니다.)", "머리를 들고(등은 항상 패드에 붙인 채) 곧은 자세를 유지하며 무릎을 굽혀 기구를 천천히 내리기 시작합니다. 허벅지와 종아리 사이 각도가 90도보다 조금 작아질 때까지(허벅지가 바닥과 평행보다 아래로 내려가는 지점) 내립니다. 이 동작을 하며 숨을 들이마십니다. 팁: 올바로 수행했다면 무릎 앞이 발끝과 정면에 수직인 가상의 직선을 이뤄야 합니다. 무릎이 그 선을 넘어가면(발끝을 넘어가면) 무릎에 과도한 부담이 가는 것으로 잘못 수행한 것입니다.", "숨을 내쉬며 주로 발뒤꿈치로 발판을 밀어 다리를 다시 펴면서 기구를 올려 시작 자세로 돌아갑니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.", "Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.", "Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).", "Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "레그 프레스": { s: "Leg_Press/0.jpg", e: "Leg_Press/1.jpg", k: ["레그 프레스 머신에 앉아 발을 어깨너비의 중간 스탠스로 바로 앞 발판에 놓습니다. (참고: 여기서는 전반적 발달을 목표로 하는 위 중간 스탠스를 기준으로 설명하지만, 발 위치 항목에서 다룬 세 가지 스탠스 중 어느 것이든 선택할 수 있습니다.)", "무게가 실린 발판을 고정하는 안전바를 내리고, 다리가 앞으로 완전히 펴질 때까지 발판을 끝까지 밀어 올립니다. 팁: 무릎을 완전히 잠그지 마세요. 상체와 다리가 정확히 90도 각도를 이뤄야 합니다. 이 자세가 시작 자세입니다.", "숨을 들이마시며 허벅지와 종아리가 90도 각도를 이룰 때까지 발판을 천천히 내립니다.", "숨을 내쉬며 주로 발뒤꿈치로 밀고 대퇴사두를 사용해 시작 자세로 돌아갑니다.", "권장 반복 횟수만큼 반복하고, 끝나면 안전핀을 반드시 제대로 잠그세요. 무게가 가득 실린 발판이 몸 위로 떨어지면 안 됩니다."], en: ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.", "As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.", "Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.", "Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."] },
  "레그 익스텐션": { s: "Leg_Extensions/0.jpg", e: "Leg_Extensions/1.jpg", k: ["이 운동은 레그 익스텐션 머신을 사용합니다. 먼저 무게를 고른 뒤 다리를 패드 아래(발끝은 앞을 향함)에 두고 옆 손잡이를 잡은 채 머신에 앉습니다. 이 자세가 시작 자세입니다. 팁: 패드가 정강이 위쪽(발 바로 위)에 오도록 조절하세요. 또한 종아리와 허벅지가 90도 각도를 이루도록 하세요. 각도가 90도보다 작으면 무릎이 발끝을 넘어간다는 뜻이며 무릎 관절에 과도한 부담을 줍니다. 머신이 그렇게 설계돼 있다면 다른 머신을 찾거나, 운동 시작 시 90도에 도달하면 더 내려가지 않도록 하세요.", "숨을 내쉬며 대퇴사두를 사용해 다리를 최대한 폅니다. 나머지 몸은 시트에 고정된 채로 유지하세요. 수축 지점에서 1초간 멈춥니다.", "숨을 들이마시며 무게를 천천히 원래 위치로 내립니다. 90도 각도 한계를 넘지 않도록 하세요.", "권장 반복 횟수만큼 반복합니다."], en: ["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.", "Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.", "Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.", "Repeat for the recommended amount of times."] },
  "고블릿 스쿼트": { s: "Goblet_Squat/0.jpg", e: "Goblet_Squat/1.jpg", k: ["가벼운 케틀벨의 뿔(손잡이 양옆)을 잡아 가슴 가까이 든 채 섭니다. 이 자세가 시작 자세입니다.", "허벅지 뒤가 종아리에 닿을 때까지 다리 사이로 앉아 내려갑니다. 가슴과 머리는 들고 등은 곧게 유지하세요.", "맨 아래 지점에서 잠시 멈추고 팔꿈치로 무릎을 바깥으로 밀어줍니다. 시작 자세로 돌아가 10~20회 반복합니다."], en: ["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.", "Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.", "At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."] },
  "런지": { s: "Dumbbell_Lunges/0.jpg", e: "Dumbbell_Lunges/1.jpg", k: ["상체를 곧게 세우고 양손에 덤벨을 들어 옆구리에 둔 채 섭니다. 이 자세가 시작 자세입니다.", "뒤에 고정된 발에서 약 60cm 앞으로 오른발을 내딛고, 상체를 곧게 세우고 균형을 유지한 채 몸을 낮춥니다. 내려가며 숨을 들이마십니다. 참고: 다른 운동과 마찬가지로 내려갈 때 무릎이 발끝을 넘어가지 않게 하세요. 무릎 관절에 과도한 부담을 줍니다. 앞쪽 정강이가 바닥과 수직이 되도록 유지하세요.", "숨을 내쉬며 주로 발뒤꿈치로 밀어 시작 자세로 돌아갑니다.", "권장 반복 횟수만큼 동작을 반복한 뒤 왼발로 수행합니다."], en: ["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.", "Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.", "Using mainly the heel of your foot, push up and go back to the starting position as you exhale.", "Repeat the movement for the recommended amount of repetitions and then perform with the left leg."] },
  "워킹 런지": { s: "Bodyweight_Walking_Lunge/0.jpg", e: "Bodyweight_Walking_Lunge/1.jpg", k: ["발을 어깨너비로 벌리고 손을 허리에 얹은 채 섭니다.", "한쪽 다리를 앞으로 내딛으며 무릎을 굽혀 골반을 낮춥니다. 뒤쪽 무릎이 바닥에 거의 닿을 때까지 내려갑니다. 자세는 곧게 유지하고 앞쪽 무릎은 앞발 위에 오도록 합니다.", "앞발 뒤꿈치로 밀고 양 무릎을 펴 몸을 다시 일으킵니다.", "뒤쪽 발을 앞으로 내딛어 반대쪽 다리로 런지를 반복합니다."], en: ["Begin standing with your feet shoulder width apart and your hands on your hips.", "Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.", "Drive through the heel of your lead foot and extend both knees to raise yourself back up.", "Step forward with your rear foot, repeating the lunge on the opposite leg."] },
  "불가리안 스플릿 스쿼트": { s: "Split_Squat_with_Dumbbells/0.jpg", e: "Split_Squat_with_Dumbbells/1.jpg", k: ["뒷발을 높은 곳에 올리고 앞발을 앞으로 둔 스태거드 스탠스를 취합니다.", "양손에 덤벨을 들어 옆으로 늘어뜨립니다. 이 자세가 시작 자세입니다.", "무릎과 고관절을 굽혀 몸을 낮추며 내려가기 시작합니다. 동작 내내 바른 자세를 유지하세요. 운동하는 동안 앞쪽 무릎이 발과 일직선을 이루도록 유지합니다.", "맨 아래 지점에서 발뒤꿈치로 밀어 무릎과 고관절을 펴 시작 자세로 돌아갑니다."], en: ["Position yourself into a staggered stance with the rear foot elevated and front foot forward.", "Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.", "Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.", "At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."] },
  "스미스 스쿼트": { s: "Smith_Machine_Squat/0.jpg", e: "Smith_Machine_Squat/1.jpg", k: ["먼저 자신의 키에 가장 잘 맞는 높이에 바를 설정합니다. 높이를 맞추고 무게를 걸었으면 바 아래로 들어가 어깨 뒤쪽(목보다 살짝 아래)에 바를 얹습니다.", "양팔로 바 양쪽을 잡고(손바닥은 앞을 향함) 잠금을 풀어, 다리로 밀면서 동시에 상체를 세워 바를 랙에서 들어올립니다.", "발끝을 살짝 바깥으로 향한 어깨너비의 중간 스탠스로 다리를 벌립니다. 머리는 항상 들고 등은 곧게 유지하세요. 이 자세가 시작 자세입니다. (참고: 여기서는 전반적 발달을 목표로 하는 중간 스탠스를 기준으로 설명하지만, 발 스탠스 항목에서 다룬 세 가지 스탠스 중 어느 것이든 선택할 수 있습니다.)", "머리를 든 곧은 자세를 유지하며 무릎을 굽혀 바를 천천히 내리기 시작합니다. 허벅지와 종아리 사이 각도가 90도보다 조금 작아질 때까지(허벅지가 바닥과 평행보다 아래로 내려가는 지점) 내립니다. 이 동작을 하며 숨을 들이마십니다. 팁: 올바로 수행했다면 무릎 앞이 발끝과 정면에 수직인 가상의 직선을 이뤄야 합니다. 무릎이 그 선을 넘어가면(발끝을 넘어가면) 무릎에 과도한 부담이 가는 것으로 잘못 수행한 것입니다.", "숨을 내쉬며 발뒤꿈치로 바닥을 밀어 다리를 다시 펴면서 바를 들어올려 시작 자세로 돌아갑니다.", "권장 반복 횟수만큼 반복합니다."], en: ["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "스텝업": { s: "Dumbbell_Step_Ups/0.jpg", e: "Dumbbell_Step_Ups/1.jpg", k: ["양손에 덤벨을 들고(손바닥은 다리 옆을 향함) 똑바로 섭니다.", "오른발을 높은 발판에 올립니다. 오른쪽 고관절과 무릎을 펴 발판 위로 올라섭니다. 주로 뒤꿈치로 나머지 몸을 밀어 올리며 왼발도 발판에 올립니다. 올라서는 힘을 쓸 때 숨을 내쉽니다.", "숨을 들이마시며 오른쪽 고관절과 무릎을 굽혀 왼발부터 내려딛습니다. 오른발을 처음 위치의 왼발 옆에 놓아 원래 서 있던 자세로 돌아갑니다.", "오른발로 권장 반복 횟수만큼 반복한 뒤 왼발로 수행합니다."], en: ["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).", "Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.", "Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.", "Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."] },
  "루마니안 데드리프트": { s: "Romanian_Deadlift/0.jpg", e: "Romanian_Deadlift/1.jpg", k: ["바벨을 앞쪽 바닥에 두고 어깨너비보다 조금 넓게 오버핸드 그립(손바닥이 아래를 향함)으로 잡습니다. 팁: 사용하는 무게에 따라 손목 스트랩이 필요할 수 있고, 가동 범위를 넓히기 위해 높은 발판이 필요할 수도 있습니다.", "무릎을 살짝 굽히고 정강이를 수직으로 유지하며, 엉덩이를 뒤로 빼고 등을 곧게 폅니다. 이 자세가 시작 자세입니다.", "등과 팔을 항상 완전히 곧게 유지한 채 숨을 내쉬며 고관절을 사용해 바를 들어올립니다. 팁: 동작은 빠르게가 아니라 꾸준하고 통제된 상태로 해야 합니다.", "완전히 곧게 선 뒤에는 스쿼트와 달리 무릎은 살짝만 굽히고 엉덩이를 뒤로 밀며 바를 내립니다. 팁: 동작 시작 시 깊게 숨을 들이마시고 가슴을 편 상태를 유지하세요. 내리는 동안 숨을 참고 동작을 마칠 때 내쉽니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.", "Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.", "Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.", "Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.", "Repeat for the recommended amount of repetitions."] },
  "스티프 레그 데드리프트": { s: "Stiff-Legged_Barbell_Deadlift/0.jpg", e: "Stiff-Legged_Barbell_Deadlift/1.jpg", k: ["오버핸드 그립(손바닥이 아래를 향함)으로 바를 잡습니다. 상당한 무게를 사용한다면 손목 스트랩이 필요할 수 있습니다.", "상체를 곧게 세우고 어깨너비 또는 그보다 좁은 스탠스로 다리를 벌려 섭니다. 무릎은 살짝 굽힙니다. 이 자세가 시작 자세입니다.", "무릎을 고정한 채 등을 곧게 유지하며 고관절을 굽혀 바벨을 발등 위까지 내립니다. 바닥에서 무언가를 집으려는 것처럼 햄스트링에 스트레칭이 느껴질 때까지 계속 숙입니다. 이 동작을 하며 숨을 들이마십니다.", "고관절을 펴 상체를 다시 곧게 세워 시작 자세로 돌아갑니다. 이 동작을 하며 숨을 내쉽니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.", "Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.", "Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.", "Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.", "Repeat for the recommended amount of repetitions."] },
  "라잉 레그 컬": { s: "Lying_Leg_Curls/0.jpg", e: "Lying_Leg_Curls/1.jpg", k: ["레그 컬 머신의 레버를 자기 키에 맞게 조절하고, 머신에 엎드려 레버 패드를 종아리 조금 아래(다리 뒤쪽)에 오도록 위치시킨다. 팁: 평평한 것보다 각도가 있는 레그 컬 머신을 쓰는 편이 좋다. 각진 자세가 햄스트링 자극에 더 유리하다.", "상체를 벤치에 평평하게 붙인 채 다리를 완전히 편 상태에서 머신 양옆 손잡이를 잡는다. 발끝은 정면을 향하게 둔다(또는 발 위치 파트에서 설명한 나머지 두 자세를 써도 된다). 이것이 시작 자세다.", "숨을 내쉬면서 허벅지(윗다리)가 패드에서 들리지 않도록 하며 다리를 최대한 위로 감아올린다. 완전히 수축된 지점에 도달하면 1초간 유지한다.", "숨을 들이마시면서 다리를 처음 위치로 되돌린다. 권장 반복 횟수만큼 반복한다."], en: ["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.", "Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.", "As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."] },
  "시티드 레그 컬": { s: "Seated_Leg_Curl/0.jpg", e: "Seated_Leg_Curl/1.jpg", k: ["머신 레버를 자기 키에 맞게 조절하고, 등을 등받이 패드에 붙인 채 머신에 앉는다.", "종아리 조금 아래(정강이 뒤 아랫부분)를 패드가 달린 레버 위에 올리고, 무릎 바로 위 허벅지에 랩 패드를 고정한다. 그런 다음 발끝을 정면으로 향한 채(또는 다른 두 자세를 써도 된다) 머신 양옆 손잡이를 잡고, 다리를 앞으로 완전히 편 상태로 둔다. 이것이 시작 자세다.", "숨을 내쉬면서 무릎을 굽혀 레버를 허벅지 뒤쪽으로 최대한 당긴다. 상체는 항상 고정된 상태를 유지한다. 수축된 자세를 1초간 유지한다.", "숨을 들이마시면서 천천히 시작 자세로 돌아온다.", "권장 반복 횟수만큼 반복한다."], en: ["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.", "Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.", "As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."] },
  "레그 컬": { s: "Lying_Leg_Curls/0.jpg", e: "Lying_Leg_Curls/1.jpg", k: ["레그 컬 머신의 레버를 자기 키에 맞게 조절하고, 머신에 엎드려 레버 패드를 종아리 조금 아래(다리 뒤쪽)에 오도록 위치시킨다. 팁: 평평한 것보다 각도가 있는 레그 컬 머신을 쓰는 편이 좋다. 각진 자세가 햄스트링 자극에 더 유리하다.", "상체를 벤치에 평평하게 붙인 채 다리를 완전히 편 상태에서 머신 양옆 손잡이를 잡는다. 발끝은 정면을 향하게 둔다(또는 발 위치 파트에서 설명한 나머지 두 자세를 써도 된다). 이것이 시작 자세다.", "숨을 내쉬면서 허벅지(윗다리)가 패드에서 들리지 않도록 하며 다리를 최대한 위로 감아올린다. 완전히 수축된 지점에 도달하면 1초간 유지한다.", "숨을 들이마시면서 다리를 처음 위치로 되돌린다. 권장 반복 횟수만큼 반복한다."], en: ["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.", "Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.", "As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."] },
  "힙 쓰러스트": { s: "Barbell_Hip_Thrust/0.jpg", e: "Barbell_Hip_Thrust/1.jpg", k: ["벤치를 등 바로 뒤에 두고 바닥에 앉아서 시작한다. 무게를 건 바벨을 다리 위에 올려둔다. 두꺼운 바를 쓰거나 바에 패드를 대면 이 운동에서 오는 불편함을 크게 줄일 수 있다.", "바가 엉덩이 바로 위에 오도록 굴린 뒤, 벤치에 기대어 견갑골이 벤치 윗부분 근처에 오게 한다.", "발로 바닥을 밀어내며 엉덩이를 수직으로 밀어 올려 바를 들어올리면서 동작을 시작한다. 체중은 견갑골과 발로 지탱해야 한다. 최대한 밀어 올린 뒤, 동작을 반대로 하여 시작 자세로 돌아온다."], en: ["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.", "Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.", "Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."] },
  "글루트 브릿지": { s: "Barbell_Glute_Bridge/0.jpg", e: "Barbell_Glute_Bridge/1.jpg", k: ["무게를 건 바벨을 다리 위에 올린 채 바닥에 앉아서 시작한다. 두꺼운 바를 쓰거나 바에 패드를 대면 이 운동에서 오는 불편함을 크게 줄일 수 있다. 바가 엉덩이 바로 위에 오도록 굴린 뒤 바닥에 평평하게 눕는다.", "발뒤꿈치로 바닥을 밀어내며 엉덩이를 수직으로 밀어 올려 바를 들어올리면서 동작을 시작한다. 체중은 상부 등과 발뒤꿈치로 지탱해야 한다.", "최대한 밀어 올린 뒤, 동작을 반대로 하여 시작 자세로 돌아온다."], en: ["Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.", "Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.", "Extend as far as possible, then reverse the motion to return to the starting position."] },
  "케이블 킥백": { s: "One-Legged_Cable_Kickback/0.jpg", e: "One-Legged_Cable_Kickback/1.jpg", k: ["가죽 발목 스트랩을 낮은 케이블 도르래에 걸고 발목에 채운다.", "약 60cm(2피트) 거리에서 웨이트 스택을 마주보고 서서 철제 프레임을 잡아 몸을 지지한다.", "무릎과 엉덩이를 살짝 굽히고 복근을 조인 상태에서 숨을 내쉬며 둔근을 수축시켜 운동하는 다리를 반원을 그리듯 편하게 올라가는 최대한 높이까지 천천히 '차 올린다'. 팁: 완전히 뻗은 지점에서 최고 수축을 위해 둔근을 1초간 쥐어짠다.", "이제 케이블의 당김에 저항하며 운동하는 다리를 천천히 앞으로 가져와 시작 자세까지 돌아온다.", "권장 반복 횟수만큼 반복한다.", "다리를 바꿔 반대쪽도 같은 동작을 반복한다."], en: ["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.", "Face the weight stack from a distance of about two feet, grasping the steel frame for support.", "While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.", "Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.", "Repeat for the recommended amount of repetitions.", "Switch legs and repeat the movement for the other side."] },
  "힙 어브덕션 머신": { s: "Thigh_Abductor/0.jpg", e: "Thigh_Abductor/1.jpg", k: ["먼저 어브덕터 머신에 앉아 편한 무게를 선택한다. 다리를 제대로 위치시켰으면 양옆 손잡이를 잡는다. 허리 위쪽 상체 전체는 고정된 상태를 유지해야 한다. 이것이 시작 자세다.", "숨을 내쉬면서 다리로 머신을 천천히 밀어 양다리를 서로 바깥쪽으로 벌린다.", "1초간 수축을 느낀 뒤, 숨을 들이마시면서 다리를 시작 자세로 되돌리기 시작한다. 참고: 부상을 막기 위해 상체는 항상 고정된 상태를 유지한다.", "권장 반복 횟수만큼 반복한다."], en: ["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.", "Slowly press against the machine with your legs to move them away from each other while exhaling.", "Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.", "Repeat for the recommended amount of repetitions."] },
  "케틀벨 스윙": { s: "One-Arm_Kettlebell_Swings/0.jpg", e: "One-Arm_Kettlebell_Swings/1.jpg", k: [], en: [] },
  "스탠딩 카프 레이즈": { s: "Standing_Calf_Raises/0.jpg", e: "Standing_Calf_Raises/1.jpg", k: ["카프 레이즈 머신의 패드 레버를 자기 키에 맞게 조절한다.", "제공된 패드 아래에 어깨를 넣고 발끝이 정면을 향하게 둔다(또는 이 장 앞부분에서 설명한 다른 두 자세를 써도 된다). 발 앞꿈치를 카프 블록 위에 고정하고 발뒤꿈치는 블록 밖으로 나오게 한다. 엉덩이와 무릎을 펴서 레버를 밀어 올려 상체를 곧게 세운다. 무릎은 완전히 잠그지 말고 살짝 굽힌 상태를 유지한다. 발끝은 이 장 앞부분에서 설명한 대로 정면, 바깥쪽 또는 안쪽을 향하게 한다. 이것이 시작 자세다.", "숨을 내쉬면서 발목을 최대한 펴고 종아리를 수축시켜 발뒤꿈치를 들어 올린다. 무릎은 항상 고정된 상태를 유지한다. 어떤 순간에도 굽혀서는 안 된다. 수축된 자세를 1초간 유지한 뒤 내려가기 시작한다.", "숨을 들이마시면서 발목을 굽혀 발뒤꿈치를 종아리가 늘어날 때까지 내리며 천천히 시작 자세로 돌아온다.", "권장 반복 횟수만큼 반복한다."], en: ["Adjust the padded lever of the calf raise machine to fit your height.", "Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.", "Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."] },
  "시티드 카프 레이즈": { s: "Seated_Calf_Raise/0.jpg", e: "Seated_Calf_Raise/1.jpg", k: ["머신에 앉아 발끝을 제공된 발판의 아랫부분에 올리고 발뒤꿈치는 밖으로 나오게 한다. 이 장 앞부분에 따라 원하는 발끝 방향(정면, 안쪽, 바깥쪽)을 선택한다.", "허벅지 아랫부분을 레버 패드 아래에 넣는데, 이 패드는 허벅지 높이에 맞게 조절해야 한다. 이제 패드가 앞으로 미끄러지지 않도록 양손을 레버 패드 위에 올린다.", "발뒤꿈치를 밀어 올려 레버를 살짝 들어 올린 뒤 안전바를 푼다. 이것이 시작 자세다.", "발목을 굽혀 종아리가 완전히 늘어날 때까지 발뒤꿈치를 천천히 내린다. 이 동작을 하는 동안 숨을 들이마신다.", "숨을 내쉬며 종아리를 수축시켜 발목을 최대한 펴며 발뒤꿈치를 들어 올린다. 꼭대기에서 수축을 1초간 유지한다.", "권장 반복 횟수만큼 반복한다."], en: ["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.", "Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.", "Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.", "Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.", "Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.", "Repeat for the recommended amount of repetitions."] },
  "레그 프레스 카프 레이즈": { s: "Calf_Press_On_The_Leg_Press_Machine/0.jpg", e: "Calf_Press_On_The_Leg_Press_Machine/1.jpg", k: ["레그 프레스 머신에 앉아 두 발을 바로 앞의 발판에 어깨너비 정도로 벌려 올린다.", "무게가 실린 발판을 고정하던 안전바를 내리고, 무릎을 완전히 잠그지 않은 채 다리를 앞으로 완전히 펴질 때까지 발판을 끝까지 밀어 올린다. (참고: 일부 레그 프레스 기구는 안전을 위해 안전바를 걸어둔 채로 할 수 있다. 기구가 이를 허용한다면 이 방식으로 운동하는 편이 좋다.) 상체와 다리는 정확히 90도를 이뤄야 한다. 이제 발끝과 발 앞꿈치를 발판 아랫부분에 조심스럽게 올리고 발뒤꿈치는 밖으로 나오게 한다. 발끝은 이 장 앞부분에서 설명한 대로 정면, 바깥쪽 또는 안쪽을 향하게 한다. 이것이 시작 자세다.", "숨을 내쉬면서 발목을 최대한 펴고 종아리를 수축시켜 발뒤꿈치를 들어 올려 발판을 민다. 무릎은 항상 고정된 상태를 유지한다. 어떤 순간에도 굽혀서는 안 된다. 수축된 자세를 1초간 유지한 뒤 내려가기 시작한다.", "숨을 들이마시면서 발목을 굽혀 발뒤꿈치를 종아리가 늘어날 때까지 내리며 천천히 시작 자세로 돌아온다.", "권장 반복 횟수만큼 반복한다."], en: ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.", "Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.", "Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.", "Repeat for the recommended amount of repetitions."] },
  "덤벨 카프 레이즈": { s: "Standing_Dumbbell_Calf_Raise/0.jpg", e: "Standing_Dumbbell_Calf_Raise/1.jpg", k: ["상체를 곧게 세우고 양손에 덤벨을 들어 몸 옆에 둔다. 발 앞꿈치를 튼튼하고 안정적인 나무판(약 5~8cm 높이) 위에 올리고 발뒤꿈치는 밖으로 나와 바닥에 닿게 한다. 이것이 시작 자세다.", "발끝을 정면(모든 부위를 고르게 자극), 안쪽(바깥쪽 종아리 강조), 또는 바깥쪽(안쪽 종아리 강조)으로 향한 채, 숨을 내쉬며 종아리를 수축시켜 발뒤꿈치를 바닥에서 들어 올린다. 꼭대기에서 수축을 1초간 유지한다.", "숨을 들이마시면서 발뒤꿈치를 천천히 내려 시작 자세로 돌아온다.", "권장 횟수만큼 반복한다."], en: ["Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.", "With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.", "As you inhale, go back to the starting position by slowly lowering the heels.", "Repeat for the recommended amount of times."] },
  "플랭크": { s: "Plank/0.jpg", e: "Plank/1.jpg", k: ["바닥에 엎드린 자세를 취하고 발끝과 팔뚝으로 체중을 지지한다. 팔은 굽혀 어깨 바로 아래에 오게 한다.", "몸을 항상 일직선으로 유지한 채 가능한 한 오래 이 자세를 버틴다. 난이도를 높이려면 팔이나 다리를 하나 들어 올린다."], en: ["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."] },
  "사이드 플랭크": { s: "Side_Bridge/0.jpg", e: "Side_Bridge/1.jpg", k: [], en: [] },
  "크런치": { s: "Crunches/0.jpg", e: "Crunches/1.jpg", k: ["등을 바닥에 대고 평평하게 누워 발을 바닥에 붙이거나, 무릎을 90도로 굽혀 벤치 위에 올린다. 발을 벤치에 올리는 경우 8~10cm 정도 벌리고 발끝을 안쪽으로 모아 서로 닿게 한다.", "이제 팔꿈치를 안으로 모은 채 양손을 머리 양옆에 가볍게 댄다. 팁: 손가락을 머리 뒤에서 깍지 끼지 않는다.", "복근을 더 잘 고립시키기 위해 허리를 바닥으로 눌러 붙이면서 어깨를 바닥에서 말아 올리기 시작한다.", "복근을 수축시키고 숨을 내쉬면서 허리로 최대한 세게 바닥을 눌러준다. 어깨는 바닥에서 약 10cm 정도만 들리고 허리는 바닥에 붙어 있어야 한다. 동작의 꼭대기에서 복근을 강하게 수축시켜 1초간 유지한다. 팁: 반동을 쓰지 말고 느리고 통제된 동작에 집중한다.", "1초간 수축한 뒤, 숨을 들이마시면서 다시 천천히 시작 자세로 내려온다.", "권장 반복 횟수만큼 반복한다."], en: ["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.", "Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.", "While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.", "Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.", "After the one second contraction, begin to come down slowly again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."] },
  "바이시클 크런치": { s: "Air_Bike/0.jpg", e: "Air_Bike/1.jpg", k: ["허리를 바닥에 눌러 붙인 채 바닥에 평평하게 눕는다. 이 운동에서는 양손을 머리 옆에 둔다. 단, 동작 중 목에 무리가 가지 않도록 주의한다. 이제 어깨를 들어 크런치 자세를 취한다.", "무릎을 바닥과 수직이 되도록 들어 올리고, 정강이는 바닥과 평행하게 둔다. 이것이 시작 자세다.", "이제 동시에, 자전거 페달을 밟듯 천천히 오른쪽 다리를 앞으로 차내며 왼쪽 무릎을 몸쪽으로 당긴다. 숨을 내쉬면서 옆으로 크런치하여 오른쪽 팔꿈치를 왼쪽 무릎에 가까이 가져간다.", "숨을 들이마시면서 처음 자세로 돌아온다.", "숨을 내쉬며 다리를 반대로 움직여 왼쪽 팔꿈치를 오른쪽 무릎에 가까이 가져가며 반대쪽으로 크런치한다.", "이런 식으로 좌우를 번갈아, 양쪽 모두 권장 반복 횟수를 채울 때까지 계속한다."], en: ["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.", "Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.", "Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.", "Go back to the initial position as you breathe in.", "Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.", "Continue alternating in this manner until all of the recommended repetitions for each side have been completed."] },
  "행잉 레그 레이즈": { s: "Hanging_Leg_Raise/0.jpg", e: "Hanging_Leg_Raise/1.jpg", k: ["와이드 그립이나 미디엄 그립으로 턱걸이 바를 잡고 양팔을 머리 위로 완전히 뻗어 매달린다. 다리는 곧게 아래로 내리고 골반은 약간 뒤로 말아준다. 이것이 시작 자세다.", "상체와 다리가 90도를 이룰 때까지 다리를 들어 올린다. 이 동작을 하면서 숨을 내쉬고 수축을 1초 정도 유지한다.", "숨을 들이마시면서 천천히 시작 자세로 돌아온다.", "권장 반복 횟수만큼 반복한다."], en: ["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.", "Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.", "Go back slowly to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."] },
  "리버스 크런치": { s: "Reverse_Crunch/0.jpg", e: "Reverse_Crunch/1.jpg", k: ["다리를 완전히 펴고 팔은 상체 옆에 두어 손바닥을 바닥에 댄 채 바닥에 눕는다. 운동 내내 팔은 고정된 상태를 유지해야 한다.", "허벅지가 바닥과 수직이 되도록 다리를 들어 올리고, 두 발은 모아 바닥과 평행하게 둔다. 이것이 시작 자세다.", "숨을 들이마시면서 골반을 뒤로 말고 엉덩이를 바닥에서 들어 올리며 다리를 상체 쪽으로 가져온다. 이 동작의 끝에서 무릎이 가슴에 닿게 된다.", "수축을 1초간 유지한 뒤, 숨을 내쉬면서 다리를 시작 자세로 되돌린다.", "권장 반복 횟수만큼 반복한다."], en: ["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.", "Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.", "While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.", "Hold the contraction for a second and move your legs back to the starting position while exhaling.", "Repeat for the recommended amount of repetitions."] },
  "케이블 크런치": { s: "Cable_Crunch/0.jpg", e: "Cable_Crunch/1.jpg", k: ["로프가 달린 높은 도르래 아래에 무릎을 꿇고 앉는다.", "케이블 로프를 잡고 손이 얼굴 옆에 오도록 로프를 내린다.", "엉덩이를 살짝 굽혀 무게가 허리를 뒤로 젖히도록 둔다. 이것이 시작 자세다.", "엉덩이는 고정한 채 복근을 수축시키며 허리를 굽혀 팔꿈치가 허벅지 가운데를 향해 내려가도록 한다. 이 부분의 동작을 하는 동안 숨을 내쉬고 수축을 1초간 유지한다.", "숨을 들이마시면서 천천히 시작 자세로 돌아온다. 팁: 동작 내내 복근에 일정한 긴장을 유지한다. 또한 허리가 부담을 대신 감당할 만큼 무거운 무게를 고르지 않는다.", "권장 반복 횟수만큼 반복한다."], en: ["Kneel below a high pulley that contains a rope attachment.", "Grasp cable rope attachment and lower the rope until your hands are placed next to your face.", "Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.", "With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.", "Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.", "Repeat for the recommended amount of repetitions."] },
  "러시안 트위스트": { s: "Russian_Twist/0.jpg", e: "Russian_Twist/1.jpg", k: ["움직이지 않는 것 아래에 발을 넣거나 파트너가 발을 잡아주게 하여 바닥에 눕는다. 다리는 무릎에서 굽힌다.", "상체를 들어 허벅지와 상상의 V자를 이루게 한다. 팔은 상체와 수직으로 앞으로 완전히 뻗고 양손은 맞잡는다. 이것이 시작 자세다.", "숨을 내쉬면서 팔이 바닥과 평행해질 때까지 상체를 오른쪽으로 비튼다.", "수축을 1초간 유지한 뒤 숨을 내쉬면서 시작 자세로 돌아온다. 이제 오른쪽에 적용한 것과 같은 방법으로 반대쪽으로 움직인다.", "권장 반복 횟수만큼 반복한다."], en: ["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.", "Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.", "Twist your torso to the right side until your arms are parallel with the floor while breathing out.", "Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.", "Repeat for the recommended amount of repetitions."] },
  "앱 휠 롤아웃": { s: "Ab_Roller/0.jpg", e: "Ab_Roller/1.jpg", k: ["양손으로 앱 롤러를 잡고 바닥에 무릎을 꿇는다.", "이제 앱 롤러를 앞쪽 바닥에 두어 무릎 꿇은 푸시업 자세처럼 양손과 무릎으로 바닥을 짚는다. 이것이 시작 자세다.", "앱 롤러를 앞으로 천천히 굴려 몸을 일직선으로 뻗는다. 팁: 몸이 바닥에 닿지 않는 선에서 최대한 낮게 내려간다. 이 부분의 동작에서 숨을 들이마신다.", "뻗은 자세에서 잠시 멈춘 뒤, 숨을 내쉬면서 몸을 시작 자세로 다시 당겨온다. 팁: 천천히 하고 복근을 항상 조인 상태로 유지한다."], en: ["Hold the Ab Roller with both hands and kneel on the floor.", "Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.", "Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.", "After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."] },
  "디클라인 싯업": { s: "Sit-Up/0.jpg", e: "Sit-Up/1.jpg", k: ["움직이지 않는 것 아래에 발을 넣거나 파트너가 발을 잡아주게 하여 바닥에 눕는다. 다리는 무릎에서 굽힌다.", "양손을 머리 뒤에 대고 손가락을 깍지 껴 맞잡는다. 이것이 시작 자세다.", "상체를 들어 허벅지와 상상의 V자를 이루게 한다. 이 부분의 동작을 할 때 숨을 내쉰다.", "1초간 수축을 느끼면, 숨을 들이마시면서 상체를 다시 시작 자세로 내린다.", "권장 반복 횟수만큼 반복한다."], en: ["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.", "Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.", "Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.", "Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."] },
  "마운틴 클라이머": { s: "Mountain_Climbers/0.jpg", e: "Mountain_Climbers/1.jpg", k: ["양손과 발끝으로 체중을 지지하는 푸시업 자세에서 시작한다. 무릎과 엉덩이를 굽혀 한쪽 다리를 무릎이 엉덩이 아래 근처에 올 때까지 당긴다. 이것이 시작 자세다.", "폭발적으로 두 다리의 위치를 바꿔, 굽힌 다리를 곧게 펴 발끝으로 지지하고 다른 발은 엉덩이와 무릎을 굽혀 앞으로 당긴다. 20~30초간 번갈아 반복한다."], en: ["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.", "Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."] },
  "바벨 슈러그": { s: "Barbell_Shrug/0.jpg", e: "Barbell_Shrug/1.jpg", k: ["발을 어깨너비로 벌려 곧게 서서 오버핸드 그립(손바닥이 허벅지를 향함)으로 바벨을 양손으로 앞에 든다. 팁: 손은 어깨너비보다 약간 넓게 잡는다. 더 나은 그립을 위해 손목 랩을 사용해도 된다. 이것이 시작 자세다.", "숨을 내쉬면서 어깨를 최대한 높이 들어 올리고 수축을 1초간 유지한다. 팁: 이두근을 써서 바벨을 들어 올리려 하지 않는다.", "숨을 들이마시면서 천천히 시작 자세로 돌아온다.", "권장 반복 횟수만큼 반복한다."], en: ["Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.", "Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."] },
  "덤벨 슈러그": { s: "Dumbbell_Shrug/0.jpg", e: "Dumbbell_Shrug/1.jpg", k: ["양손에 덤벨을 하나씩 들고(손바닥이 몸통을 향함) 팔을 옆으로 뻗은 채 곧게 선다.", "숨을 내쉬면서 어깨를 최대한 높이 들어 올려 덤벨을 든다. 꼭대기에서 수축을 1초간 유지한다. 팁: 팔은 항상 뻗은 상태를 유지한다. 이두근을 써서 덤벨을 들어 올리지 않는다. 어깨만 위아래로 움직여야 한다.", "덤벨을 원래 위치로 내린다.", "권장 반복 횟수만큼 반복한다."], en: ["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.", "Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.", "Lower the dumbbells back to the original position.", "Repeat for the recommended amount of repetitions."] },
  "바벨 클린": { s: "Power_Clean/0.jpg", e: "Power_Clean/1.jpg", k: ["발을 어깨너비보다 약간 넓게 벌리고 발끝을 살짝 바깥쪽으로 향하게 하여 선다.", "스쿼트 자세로 앉아 클로즈드 오버핸드 그립으로 바를 잡는다. 손은 무릎 바깥쪽에서 어깨너비보다 약간 넓게 잡고 팔꿈치는 완전히 편다.", "바를 정강이 앞 약 2.5cm(1인치) 지점, 발 앞꿈치 위에 위치시킨다.", "등은 평평하거나 약간 아치를 이루고, 가슴은 들어 내밀며 견갑골은 뒤로 모아야 한다.", "머리는 중립 자세(척추와 일직선, 기울이거나 돌리지 않음)로 유지하고 시선은 정면을 향한다. 이 단계에서 숨을 들이마신다.", "숨을 내쉬면서 엉덩이와 무릎을 힘차게 펴서 바를 바닥에서 들어 올린다. 팁: 상체는 같은 각도를 유지해야 한다. 아직 허리를 굽히지 말고, 어깨보다 엉덩이가 먼저 올라가지 않도록 한다(그러면 엉덩이가 위로 솟고 햄스트링이 늘어나게 된다).", "팔꿈치를 완전히 편 상태로 머리는 중립으로 유지하고 어깨는 바 위에 둔다.", "바가 올라갈 때 정강이에 최대한 가깝게 유지한다.", "바가 무릎을 지나면 엉덩이를 앞으로 밀고 무릎을 살짝 굽혀 잠기지 않게 한다. 팁: 이 시점에서 허벅지가 바에 닿아야 한다.", "등은 평평하거나 약간 아치를 이루고, 팔꿈치는 완전히 펴며 머리는 중립으로 유지한다. 팁: 다음 단계까지 숨을 참는다.", "숨을 들이마신 뒤 엉덩이와 무릎을 힘차고 빠르게 펴며 발끝으로 선다.", "바를 몸에 최대한 가깝게 유지한다. 팁: 등은 평평하게, 팔꿈치는 옆으로 향하게 하고 머리는 중립으로 둔다. 또한 어깨를 바 위에 두고 팔을 최대한 오래 곧게 유지한다.", "하체 관절이 완전히 펴지면 팔꿈치를 아직 굽히지 않은 채 어깨를 빠르게 위로 으쓱 들어 올린다. 이 부분의 동작에서 숨을 내쉰다.", "어깨가 가장 높이 올라가면 팔꿈치를 굽혀 몸을 바 아래로 당기기 시작한다.", "팔을 최대한 높고 오래 계속 당긴다. 팁: 이 단계의 폭발적인 특성 때문에 상체는 곧게 서거나 등이 아치를 이루고, 머리는 살짝 뒤로 젖혀지며 발이 바닥에서 떨어질 수도 있다.", "하체가 완전히 펴지고 바가 최대 높이 근처에 도달하면, 몸을 바 아래로 당기고 팔을 바 주위로 돌려 바 아래로 넣는다.", "동시에 엉덩이와 무릎을 굽혀 쿼터 스쿼트 자세를 취한다.", "팔이 바 아래에 오면 숨을 들이마신 뒤 팔꿈치를 들어 올려 상완이 바닥과 평행하게 위치시킨다. 바를 쇄골과 앞쪽 어깨 근육 앞에 걸쳐 랙 포지션을 만든다.", "상체를 곧고 단단히 세우고 머리는 중립, 발은 평평하게 붙인 채 바를 받아낸다. 이 동작에서 숨을 내쉰다.", "엉덩이와 무릎을 펴서 완전히 곧게 선 자세로 일어선다.", "팔의 근긴장을 서서히 풀어 바를 통제된 상태로 허벅지까지 내린다. 이 동작에서 숨을 들이마신다.", "동시에 엉덩이와 무릎을 굽혀 바가 허벅지에 닿는 충격을 완화한다.", "팔꿈치를 완전히 편 채 바가 바닥에 닿을 때까지 스쿼트 자세로 앉는다.", "1단계부터 다시 시작하여 권장 반복 횟수만큼 반복한다."], en: ["Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.", "Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.", "Place the bar about 1 inch in front of your shins and over the balls of your feet.", "Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.", "Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.", "Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.", "Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.", "As the bar raises keep it as close to the shins as possible.", "As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.", "Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.", "Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.", "Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.", "When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.", "As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.", "Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.", "After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.", "Simultaneously, flex the hips and knees into a quarter squat position.", "Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.", "Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.", "Stand up by extending the hips and knees to a fully erect position.", "Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.", "Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.", "Squat down with the elbows fully extended until the bar touches the floor.", "Start over at Phase 1 and repeat for the recommended amount of repetitions."] },
  "클린 앤 저크": { s: "Clean_and_Jerk/0.jpg", e: "Clean_and_Jerk/1.jpg", k: ["바벨을 정강이에 가깝게 바닥에 두고, 다리 바로 바깥쪽에서 오버핸드 그립 또는 훅 그립으로 잡습니다. 무게중심을 뒤꿈치에 두고 엉덩이를 낮추되, 허리는 곧게 펴고 시선은 정면을 향하며 가슴은 세우고 어깨가 바보다 살짝 앞으로 나오게 합니다. 이것이 시작 자세입니다.", "뒤꿈치로 바닥을 밀며 무릎을 펴 1차 당김(퍼스트 풀)을 시작합니다. 허리 각도는 그대로 유지하고 팔은 곧게 편 상태를 유지합니다. 무릎 위까지 계속 이어가면서 무게를 통제하며 들어 올립니다.", "다음은 클린의 주된 가속 구간인 2차 당김(세컨드 풀)입니다. 바가 허벅지 중간 위치에 도달하면 엉덩이를 펴기 시작합니다. 점프하는 동작처럼 엉덩이, 무릎, 발목을 펴며 속도를 이용해 바를 위로 가속시킵니다. 무게를 가속하기 위해 팔로 능동적으로 당길 필요는 없습니다. 2차 당김이 끝나는 지점에서 몸은 완전히 펴지고 약간 뒤로 기울며, 팔은 여전히 곧게 편 상태여야 합니다.", "완전히 신전되면 팔꿈치를 위·바깥으로 든 채 강하게 슈러그하고 팔을 굽히며 3차 당김(서드 풀)으로 전환합니다. 신전이 최고점에 이르면 몸을 강하게 아래로 당기면서 팔꿈치를 바 아래로 회전시킵니다. 프론트 스쿼트 자세로 바를 받아내며, 그 깊이는 3차 당김이 끝날 때 바의 높이에 따라 결정됩니다. 바는 앞으로 내민 어깨 위에 걸치듯 얹고, 손에 힘을 뺀 채 목에 가볍게 닿게 합니다. 계속 스쿼트 최저점까지 내려가면 일어서는 데 도움이 됩니다.", "곧바로 뒤꿈치로 밀며 상체를 세우고 팔꿈치를 든 채 일어섭니다. 완전히 선 자세가 될 때까지 이어갑니다.", "두 번째 단계는 무게를 머리 위로 들어 올리는 저크입니다. 무게를 어깨 앞쪽에 걸친 채 서서 딥 동작으로 시작합니다. 발을 엉덩이 바로 아래에 두고, 엉덩이를 뒤로 빼지 않은 채 무릎만 굽힙니다. 살짝만 내려간 뒤 최대한 힘차게 방향을 반대로 전환합니다.", "뒤꿈치로 밀며 최대한의 속도와 힘을 내고, 바가 어깨를 떠날 때 머리를 옆으로 피해 길을 비켜 줍니다.", "발이 바닥에서 떨어지는 이 순간, 발을 최대한 빠르게 받는 자세로 옮겨야 합니다. 발이 바닥을 능동적으로 밀지 않는 그 짧은 순간에, 바를 위로 밀어 올리려는 힘이 몸을 아래로 밀어 넣습니다. 발은 한쪽은 앞, 다른 쪽은 뒤로 갈라 벌립니다. 팔을 머리 위로 완전히 편 채 바를 받아냅니다. 그런 다음 선 자세로 돌아옵니다."], en: ["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.", "Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.", "Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.", "As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.", "Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.", "The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.", "Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.", "At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position."] },
  "스내치": { s: "Snatch/0.jpg", e: "Snatch/1.jpg", k: ["발을 어깨너비로 벌리고, 발가락과 발의 나머지 부분이 연결되는 지점 바로 위에 바벨이 오도록 섭니다.", "손바닥이 아래를 향하는 그립으로, 무릎을 굽히고 허리를 편평하게 유지한 채 어깨너비보다 넓게 바를 잡습니다. 엉덩이를 낮추고 의자에 앉듯 몸을 내립니다. 이것이 시작 자세입니다.", "발로 바닥을 움직이는 발판처럼 밀기 시작하면서 동시에 바벨을 다리에 가깝게 붙인 채 들어 올리기 시작합니다.", "바가 허벅지 중간에 도달하면 다리로 바닥을 밀며 몸을 폭발적으로 완전히 펴 올립니다.", "바를 위로 올리면서 슈러그하듯 어깨를 뒤로 들어 올리고, 팔꿈치를 옆으로 든 채 가능한 한 오래 바보다 높게 유지합니다.", "이제 매우 빠르지만 강한 동작으로, 바벨이 통제 가능할 만큼 충분히 높은 지점에 도달하면 몸을 바벨 아래로 넣고, 팔을 잠근 채 바벨을 머리 위로 든 상태로 스쿼트 자세를 취하며 내려갑니다.", "스쿼트 자세에서 일어서며 동작을 마무리합니다. 리프트가 끝날 때 두 발은 일직선상에 있고 팔은 완전히 펴 바벨을 머리 위로 든 상태여야 합니다."], en: ["Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.", "With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.", "Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.", "As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.", "Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.", "Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.", "Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead."] },
  "배틀 로프": { s: "Battling_Ropes/0.jpg", e: "Battling_Ropes/1.jpg", k: ["이 운동에는 중앙이 4.5~6미터(15~20피트) 떨어진 곳에 고정된 무거운 로프가 필요합니다. 로프 앞에 서서 양손에 로프 끝을 하나씩 잡고 팔을 옆구리 옆으로 편 채 섭니다. 이것이 시작 자세입니다.", "한쪽 팔을 최대한 빠르게 어깨 높이까지 재빨리 들어 올리며 동작을 시작합니다.", "그 팔을 시작 자세로 떨어뜨리면서 반대쪽 팔을 들어 올립니다.", "좌우 팔을 번갈아 가며 최대한 빠르게 로프를 위아래로 후려칩니다."], en: ["For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.", "Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.", "As you let that arm drop to the starting position, raise the opposite side.", "Continue alternating your left and right arms, whipping the ropes up and down as fast as you can."] },
  "로잉 머신": { s: "Rowing_Stationary/0.jpg", e: "Rowing_Stationary/1.jpg", k: ["먼저 로잉 머신에 앉습니다. 뒤꿈치가 발판 바닥에 편안히 닿고 스트랩이 고정되었는지 확인합니다. 해당된다면 사용할 프로그램을 선택합니다. 허리를 곧게 펴고 앉아 엉덩이에서부터 앞으로 숙입니다.", "로잉 머신을 사용할 때는 세 단계의 동작이 있습니다. 첫 번째 단계는 머신 앞쪽으로 나아가는 구간입니다. 무릎은 굽혀 가슴 쪽에 붙이고, 상체는 바른 자세를 유지하면서 살짝 앞으로 기울입니다. 다음으로 발판을 밀며 다리를 펴고, 손을 상복부까지 당기면서 어깨를 뒤로 조입니다. 허리에 무리가 가지 않도록 주로 다리와 엉덩이 근육을 사용합니다.", "회복 단계는 단순히 팔을 펴고 무릎을 굽혀 몸을 다시 앞으로 가져와 첫 번째 단계로 전환하는 과정입니다."], en: ["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.", "There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.", "The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."] },
  "어시스트 풀업": { s: "Band_Assisted_Pull-Up/0.jpg", e: "Band_Assisted_Pull-Up/1.jpg", k: ["밴드를 풀업 바 중앙에 감아 조입니다. 여러 종류의 밴드를 사용해 보조 강도를 다르게 조절할 수 있습니다.", "밴드 끝을 아래로 당겨 굽힌 한쪽 무릎을 고리에 넣고, 빠지지 않도록 확실히 고정합니다. 바를 중간에서 넓은 그립으로 잡습니다. 이것이 시작 자세입니다.", "팔꿈치를 굽히며 광배근을 수축시켜 몸을 위로 당깁니다. 팔꿈치는 몸 옆으로 당겨 내립니다. 앞쪽으로 당겨 턱이 바 위로 올라오게 합니다. 몸을 흔들거나 반동을 쓰는 동작은 피합니다.", "잠시 멈춘 뒤 시작 자세로 돌아옵니다."], en: ["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.", "Pull the end of the band down, and place one bent knee into the loop, ensuring it won't slip out. Take a medium to wide grip on the bar. This will be your starting position.", "Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.", "After a brief pause, return to the starting position."] },
  "어시스트 친업": { s: "Chin-Up/0.jpg", e: "Chin-Up/1.jpg", k: ["손바닥이 상체를 향하도록 하고 어깨너비보다 좁은 그립으로 풀업 바를 잡습니다.", "선택한 그립 너비로 바를 잡고 양팔을 앞으로 편 상태에서, 허리를 아래로 살짝 아치를 만들고 가슴을 내밀며 상체를 최대한 곧게 유지합니다. 이것이 시작 자세입니다. 팁: 상체를 최대한 곧게 유지하면 등의 개입을 최소화하면서 이두근 자극을 극대화할 수 있습니다.", "숨을 내쉬며 머리가 풀업 바 높이에 이를 때까지 상체를 당겨 올립니다. 이두근을 사용해 동작을 수행하는 데 집중합니다. 팔꿈치는 몸에 가깝게 유지합니다. 팁: 상체는 공간을 이동하는 동안에도 고정된 상태를 유지하고 팔만 움직여야 합니다. 전완은 바를 잡는 것 외에 다른 일을 해서는 안 됩니다.", "수축된 자세에서 이두근을 1초간 조인 뒤, 팔이 완전히 펴질 때까지 상체를 천천히 시작 자세로 내립니다. 이 구간에서 숨을 들이마십니다.", "정해진 반복 횟수만큼 이 동작을 반복합니다."], en: ["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.", "As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."] },
  "어시스트 딥스": { s: "Parallel_Bar_Dip/0.jpg", e: "Parallel_Bar_Dip/1.jpg", k: ["평행봉 사이에 섭니다. 양쪽 봉에 손을 하나씩 얹고, 작게 점프해 팔을 완전히 편 시작 자세를 잡습니다.", "팔꿈치를 굽혀 팔이 90도 아래로 내려갈 때까지 몸을 내립니다. 몸을 흔들지 말고 내려가는 내내 바른 자세를 유지합니다.", "팔꿈치를 펴며 동작을 반대로 하여 몸을 다시 시작 자세로 밀어 올립니다.", "원하는 반복 횟수만큼 반복합니다."], en: ["Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.", "Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.", "Reverse the motion by extending the elbow, pushing yourself back up into the starting position.", "Repeat for the desired number of repetitions."] },
  "하이 로우": { s: "Leverage_High_Row/0.jpg", e: "Leverage_High_Row/1.jpg", k: ["핀에 적절한 무게를 걸고, 위쪽 손잡이에 손이 겨우 닿을 정도로 시트 높이를 조절합니다. 무릎 패드를 조절해 몸이 뜨지 않도록 고정합니다. 손잡이를 오버핸드(엎은) 그립으로 잡습니다. 이것이 시작 자세입니다.", "팔꿈치를 굽히며 견갑골을 모아 손잡이를 상체 쪽으로 당깁니다.", "동작 끝에서 잠시 멈춘 뒤 손잡이를 천천히 시작 자세로 되돌립니다.", "여러 번 반복할 때는 무게를 완전히 스톱까지 내리지 않아 작용 근육에 긴장을 유지합니다."], en: ["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position.", "For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."] },
  "로우 로우": { s: "Leverage_Iso_Row/0.jpg", e: "Leverage_Iso_Row/1.jpg", k: ["핀에 적절한 무게를 걸고, 손잡이가 가슴 높이에 오도록 시트 높이를 조절합니다. 손잡이를 뉴트럴(중립) 또는 오버핸드(엎은) 그립으로 잡습니다. 이것이 시작 자세입니다.", "팔꿈치를 굽히며 견갑골을 모아 손잡이를 상체 쪽으로 당깁니다.", "동작 끝에서 잠시 멈춘 뒤 손잡이를 천천히 시작 자세로 되돌립니다. 여러 번 반복할 때는 무게를 완전히 스톱까지 내리지 않아 작용 근육에 긴장을 유지합니다."], en: ["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."] },
  "체스트 서포티드 로우": { s: "Lying_T-Bar_Row/0.jpg", e: "Lying_T-Bar_Row/1.jpg", k: ["T바 로우 머신에 원하는 무게를 걸고, 상부 가슴이 패드 맨 위에 오도록 다리 높이를 조절합니다. 팁: 일부 머신은 상부 가슴이 패드 맨 위에 오는 높이가 되도록 알맞은 발판에 올라서는 것만 가능합니다.", "패드에 엎드려 손잡이를 잡습니다. 등의 어느 부위를 강조하고 싶은지에 따라 손바닥이 아래·위·서로 마주보는 위치 중에서 선택할 수 있습니다.", "바를 거치대에서 들어 올려 팔을 앞으로 폅니다. 이것이 시작 자세입니다.", "숨을 내쉬며 천천히 무게를 당겨 올리고 동작 정점에서 등을 조입니다. 팁: 등 근육을 더 잘 쓰기 위해 동작 내내 상완을 상체에 최대한 가깝게 유지합니다. 또한 어느 순간에도 몸을 패드에서 떼지 말고 이두근으로 무게를 들지 않습니다.", "동작 정점에서 1초간 수축한 뒤, 숨을 들이마시며 천천히 시작 자세로 내려갑니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.", "Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.", "Lift the bar off the rack and extend your arms in front of you. This will be your starting position.", "As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.", "After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "인버티드 로우": { s: "Inverted_Row/0.jpg", e: "Inverted_Row/1.jpg", k: ["랙에 바를 대략 허리 높이로 설치합니다. 스미스 머신을 사용해도 됩니다.", "바를 어깨너비보다 넓게 잡고 바 아래에 매달리는 자세를 잡습니다. 몸은 곧게 펴고 뒤꿈치는 바닥에 대며 팔은 완전히 편 상태여야 합니다. 이것이 시작 자세입니다.", "팔꿈치를 굽히며 가슴을 바 쪽으로 당깁니다. 동작을 수행하며 견갑골을 모읍니다.", "동작 정점에서 잠시 멈춘 뒤 시작 자세로 돌아옵니다.", "원하는 반복 횟수만큼 반복합니다."], en: ["Position a bar in a rack to about waist height. You can also use a smith machine.", "Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.", "Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.", "Pause at the top of the motion, and return yourself to the start position.", "Repeat for the desired number of repetitions."] },
  "원암 랫풀다운": { s: "One_Arm_Lat_Pulldown/0.jpg", e: "One_Arm_Lat_Pulldown/1.jpg", k: ["적절한 무게를 선택하고 무릎 패드를 조절해 몸이 뜨지 않도록 고정합니다. 손잡이를 오버핸드(엎은) 그립으로 잡습니다. 이것이 시작 자세입니다.", "팔꿈치를 굽히며 팔꿈치를 옆구리 쪽으로 조여 손잡이를 아래로 당깁니다.", "동작 끝에서 잠시 멈춘 뒤 손잡이를 천천히 시작 자세로 되돌립니다.", "여러 번 반복할 때는 무게를 완전히 되돌리지 않아 작용 근육에 긴장을 유지합니다."], en: ["Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.", "Pull the handle down, squeezing your elbow to your side as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handle to the starting position.", "For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked."] },
  "덤벨 풀오버": { s: "Bent-Arm_Dumbbell_Pullover/0.jpg", e: "Bent-Arm_Dumbbell_Pullover/1.jpg", k: ["덤벨 하나를 평벤치 위에 세워 둡니다.", "덤벨이 벤치 위쪽에 안정적으로 놓여 있도록 유지하면서, 어깨만 벤치 표면에 닿도록 벤치와 수직으로(십자 모양처럼 상체를 가로질러) 눕습니다. 엉덩이는 벤치보다 낮게 두고 다리는 굽혀 발을 바닥에 단단히 붙입니다. 머리도 벤치 밖으로 나오게 합니다.", "양손으로 덤벨을 잡고 팔을 살짝 굽힌 채 가슴 바로 위로 곧게 듭니다. 양 손바닥은 덤벨 한쪽 원판의 아랫면을 받치듯 눌러야 합니다. 이것이 시작 자세입니다. 주의: 이 운동에 사용하는 덤벨이 확실히 고정되어 있는지 항상 확인하세요. 원판이 헐거운 덤벨을 쓰면 덤벨이 분리되어 얼굴 위로 떨어질 수 있습니다.", "팔을 굽힌 자세로 잠근 채, 숨을 들이마시며 가슴에 늘어나는 느낌이 들 때까지 무게를 머리 뒤로 호를 그리며 천천히 내립니다.", "그 지점에서 무게를 내렸던 호를 따라 덤벨을 시작 자세로 되가져오며 숨을 내쉽니다.", "시작 위치에서 1초간 무게를 유지한 뒤 정해진 반복 횟수만큼 동작을 반복합니다."], en: ["Place a dumbbell standing up on a flat bench.", "Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.", "Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.", "While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.", "At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.", "Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."] },
  "랜드마인 프레스": { s: "Landmine_Linear_Jammer/0.jpg", e: "Landmine_Linear_Jammer/1.jpg", k: ["바를 랜드마인 거치대에 끼우거나, 없다면 모서리에 단단히 고정합니다. 바에 적절한 무게를 걸고 손잡이 부착물을 바에 끼웁니다.", "바를 바닥에서 들어 올려 손잡이를 어깨로 가져옵니다. 이것이 시작 자세입니다.", "운동선수 자세로, 팔은 굽힌 채 엉덩이를 굽히고 뒤로 빼며 스쿼트합니다.", "엉덩이, 무릎, 발목을 힘차게 펴는 동시에 팔꿈치를 펴 팔을 곧게 뻗으며 동작을 반대로 합니다. 이 동작은 폭발적으로 수행하여 스쿼트에서 완전 신전까지 최대한 힘차게 올라와야 합니다.", "시작 자세로 돌아옵니다."], en: ["Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.", "Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.", "In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.", "Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.", "Return to the starting position."] },
  "케이블 리어 델트 플라이": { s: "Cable_Rear_Delt_Fly/0.jpg", e: "Cable_Rear_Delt_Fly/1.jpg", k: ["도르래를 적절한 높이로 조절하고 무게를 설정합니다. 도르래는 머리 위쪽에 있어야 합니다.", "오른손으로 왼쪽 도르래를, 왼손으로 오른쪽 도르래를 잡아 몸 앞에서 교차시킵니다. 이것이 시작 자세입니다.", "팔을 곧게 편 상태를 유지하며 팔을 뒤·바깥쪽으로 벌려 동작을 시작합니다.", "동작 끝에서 잠시 멈춘 뒤 손잡이를 시작 자세로 되돌립니다."], en: ["Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.", "Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.", "Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.", "Pause at the end of the motion before returning the handles to the start position."] },
  "시시 스쿼트": { s: "Weighted_Sissy_Squat/0.jpg", e: "Weighted_Sissy_Squat/1.jpg", k: ["발을 어깨너비로 벌리고 발끝을 든 채 똑바로 서서, 한 손으로 스쿼트 랙 기둥을 잡고 반대 팔로는 원판을 가슴 위에 얹어 잡습니다. 이것이 시작 자세입니다.", "한 팔로 몸을 지탱하면서 무릎을 굽히고 골반과 무릎을 앞으로 내밀며 상체를 천천히 바닥 쪽으로 내립니다. 내려가면서 숨을 들이마시고 허벅지와 종아리가 거의 90도 각도를 이룰 때 멈춥니다. 늘어난 자세를 1초간 유지합니다.", "1초간 멈춘 뒤 허벅지 근육을 사용해 상체를 시작 자세로 되올립니다. 올라오면서 숨을 내쉽니다.", "권장 횟수만큼 반복합니다."], en: ["Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.", "As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.", "After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.", "Repeat for the recommended amount of times."] },
  "힙 어덕션 머신": { s: "Thigh_Adductor/0.jpg", e: "Thigh_Adductor/1.jpg", k: ["먼저 어덕터(모음) 머신에 앉아 편안한 무게를 선택합니다. 다리를 머신의 다리 패드에 알맞게 위치시킨 뒤 양쪽 손잡이를 잡습니다. 상체 전체(허리 위로)는 고정된 상태여야 합니다. 이것이 시작 자세입니다.", "숨을 내쉬며 다리로 머신을 천천히 밀어 양다리를 서로 모읍니다.", "1초간 수축을 느낀 뒤 숨을 들이마시며 다리를 시작 자세로 되돌리기 시작합니다. 참고: 부상을 예방하기 위해 상체를 고정한 상태로 유지하고 빠르게 반동을 쓰는 동작을 피하세요.", "권장 반복 횟수만큼 반복합니다."], en: ["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.", "Slowly press against the machine with your legs to move them towards each other while exhaling.", "Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.", "Repeat for the recommended amount of repetitions."] },
  "스미스 힙 쓰러스트": { s: "Barbell_Hip_Thrust/0.jpg", e: "Barbell_Hip_Thrust/1.jpg", k: ["벤치를 바로 뒤에 둔 채 바닥에 앉아 시작합니다. 무게를 건 바벨을 다리 위에 놓습니다. 두꺼운 바를 쓰거나 바에 패드를 대면 이 운동으로 인한 불편함을 크게 줄일 수 있습니다.", "바를 굴려 엉덩이 바로 위에 오게 하고, 견갑골이 벤치 윗부분 근처에 오도록 벤치에 기댑니다.", "발로 밀며 엉덩이를 수직으로 펴 바를 밀어 올려 동작을 시작합니다. 체중은 견갑골과 발로 지탱해야 합니다. 최대한 멀리 편 뒤 동작을 반대로 하여 시작 자세로 돌아옵니다."], en: ["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.", "Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.", "Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."] },
  "JM 프레스": { s: "JM_Press/0.jpg", e: "JM_Press/1.jpg", k: ["클로즈 그립 벤치프레스와 같은 방식으로 운동을 시작합니다. 평벤치에 누워 팔꿈치를 붙인 채 바벨을 팔 길이만큼(완전히 편 상태) 듭니다. 다만 팔을 상체와 수직으로 두는 대신, 바가 상부 가슴 바로 위 일직선상에 오도록 합니다. 이것이 시작 자세입니다.", "이제 완전히 편 자세에서 시작해 라잉 트라이셉스 익스텐션을 하듯 바를 아래로 내립니다. 이 동작을 하면서 숨을 들이마십니다. 중간 지점에 도달하면 상완을 다리 쪽으로 움직여 상체와 수직이 될 때까지 바를 약 2.5센티미터(1인치) 정도 뒤로 굴립니다. 팁: 상완을 앞으로 가져오는 동안 팔꿈치 굽힘 각도를 일정하게 유지하세요.", "숨을 내쉬며 삼두근을 사용해 클로즈 그립 벤치프레스를 하듯 바를 다시 밀어 올립니다.", "이제 시작 자세로 돌아가 다시 시작합니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.", "Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.", "As you exhale, press the bar back up by using the triceps to perform a close grip bench press.", "Now go back to the starting position and start over.", "Repeat for the recommended amount of repetitions."] },
  "딥 머신": { s: "Dip_Machine/0.jpg", e: "Dip_Machine/1.jpg", k: ["딥 머신에 안정적으로 앉아 무게를 선택하고 손잡이를 단단히 잡습니다.", "이제 삼두근에 집중이 가도록 팔꿈치를 옆구리에 붙입니다. 팔꿈치는 90도로 굽혀야 합니다.", "삼두근을 수축하면서 숨을 내쉬며 팔을 아래로 폅니다. 팁: 동작 맨 아래에서 삼두근에 긴장을 유지하기 위해 팔을 완전히 펴지 말고 약간 굽힌 상태를 유지하는 데 집중하세요.", "이제 숨을 들이마시며 천천히 팔을 시작 자세로 되올립니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Sit securely in a dip machine, select the weight and firmly grasp the handles.", "Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.", "As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.", "Now slowly let your arms come back up to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."] },
  "케이블 해머 컬": { s: "Cable_Hammer_Curls_-_Rope_Attachment/0.jpg", e: "Cable_Hammer_Curls_-_Rope_Attachment/1.jpg", k: ["로프 부착물을 낮은 도르래에 연결하고 머신을 마주 본 채 약 30센티미터(12인치) 떨어져 섭니다.", "로프를 뉴트럴(손바닥이 마주보는) 그립으로 잡고, 허리의 자연스러운 아치와 상체를 고정한 채 똑바로 섭니다.", "팔꿈치를 옆구리에 붙이고 동작 내내 그 위치에 고정합니다. 팁: 전완만 움직이고 상완은 움직이지 않아야 합니다. 이것이 시작 자세입니다.", "이두근을 사용해 숨을 내쉬며 이두근이 전완에 닿을 때까지 팔을 당겨 올립니다. 팁: 팔꿈치를 붙인 채 상완을 고정한 상태를 유지하세요.", "이두근을 조이며 1초간 수축한 뒤 천천히 무게를 원래 위치로 되돌리기 시작합니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.", "Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.", "Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.", "Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.", "After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.", "Repeat for the recommended amount of repetitions."] },
  "라잉 레그 레이즈": { s: "Flat_Bench_Lying_Leg_Raise/0.jpg", e: "Flat_Bench_Lying_Leg_Raise/1.jpg", k: ["등을 벤치에 편평하게 대고 눕고, 다리는 벤치 끝 밖으로 앞으로 편 상태로 둡니다.", "손은 손바닥을 아래로 하여 엉덩이 밑에 넣거나, 벤치 양옆을 잡습니다. 이것이 시작 자세입니다.", "다리를 최대한 곧게 편 상태로, 무릎을 살짝 굽히되 고정한 채 다리가 바닥과 90도 각도를 이룰 때까지 들어 올립니다. 이 구간에서 숨을 내쉬고 정점에서 1초간 수축을 유지합니다.", "이제 숨을 들이마시며 다리를 천천히 시작 자세로 내립니다."], en: ["Lie with your back flat on a bench and your legs extended in front of you off the end.", "Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.", "As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.", "Now, as you inhale, slowly lower your legs back down to the starting position."] },
  "케이블 우드촙": { s: "Standing_Cable_Wood_Chop/0.jpg", e: "Standing_Cable_Wood_Chop/1.jpg", k: ["일반 손잡이를 케이블 타워에 연결하고 케이블을 가장 높은 도르래 위치로 옮깁니다.", "케이블을 옆으로 두고 서서 한 손으로 손잡이를 잡고 타워에서 멀어집니다. 도르래에서 대략 팔 하나 길이만큼 떨어져 케이블에 무게 긴장이 걸린 상태여야 합니다. 뻗은 팔은 케이블과 일직선을 이루어야 합니다.", "발을 어깨너비로 벌리고, 다른 손을 위로 뻗어 양손으로 손잡이를 잡습니다. 팔은 여전히 완전히 편 상태여야 합니다.", "한 동작으로, 상체를 회전시키면서 손잡이를 아래로 그리고 몸을 가로질러 앞쪽 무릎까지 당깁니다.", "축이 되는 뒷발을 회전시키고 무릎을 굽혀 전체 가동 범위를 확보하는 동안 허리와 팔은 곧게, 코어는 단단히 유지합니다.", "자세와 곧게 편 팔을 유지합니다. 천천히 통제된 동작으로 중립 위치로 돌아옵니다.", "실패 지점까지 반복합니다.", "그런 다음 자세를 바꿔 반대쪽에서 같은 동작을 반복합니다."], en: ["Connect a standard handle to a tower, and move the cable to the highest pulley position.", "With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.", "With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.", "In one motion, pull the handle down and across your body to your front knee while rotating your torso.", "Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.", "Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.", "Repeat to failure.", "Then, reposition and repeat the same series of movements on the opposite side."] },
  "앱 크런치 머신": { s: "Ab_Crunch_Machine/0.jpg", e: "Ab_Crunch_Machine/1.jpg", k: ["가벼운 저항을 선택하고 앱 머신에 앉아 발을 제공된 패드 아래에 넣고 위쪽 손잡이를 잡습니다. 제공된 패드에 삼두근을 얹은 채 팔은 90도로 굽혀야 합니다. 이것이 시작 자세입니다.", "동시에 상체를 크런치하면서 다리를 들어 올리기 시작합니다. 이 동작을 하면서 숨을 내쉽니다. 팁: 반드시 천천히 통제된 동작을 사용하세요. 다리와 발은 이완한 채 복근을 사용해 무게를 움직이는 데 집중합니다.", "1초간 멈춘 뒤 숨을 들이마시며 천천히 시작 자세로 돌아옵니다.", "정해진 반복 횟수만큼 동작을 반복합니다."], en: ["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.", "At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.", "After a second pause, slowly return to the starting position as you breathe in.", "Repeat the movement for the prescribed amount of repetitions."] },
  "케이블 슈러그": { s: "Cable_Shrugs/0.jpg", e: "Cable_Shrugs/1.jpg", k: ["낮은 도르래에 연결된 케이블 바 부착물을 어깨너비 또는 그보다 약간 넓은 오버핸드(손바닥이 아래를 향하는) 그립으로 잡습니다.", "도르래 가까이에 똑바로 서서 팔을 앞으로 편 채 바를 잡습니다. 이것이 시작 자세입니다.", "숨을 내쉬며 어깨를 최대한 높이 들어 올려 바를 듭니다. 정점에서 1초간 수축을 유지합니다. 팁: 팔은 항상 편 상태를 유지해야 합니다. 이두근으로 바를 드는 것을 삼가세요. 오직 어깨만 위아래로 움직여야 합니다.", "바를 원래 위치로 내립니다.", "권장 반복 횟수만큼 반복합니다."], en: ["Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.", "Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.", "Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.", "Lower the bar back to the original position.", "Repeat for the recommended amount of repetitions."] },

  // ── 카탈로그 대확장 자동 생성부 (gen-exercise-media.js — 이 마커 아래는 재실행 시 재생성) ──
  // 매칭=free-exercise-db 이미지+영문 스텝(+한국어 번역), steps-only=자체 작성(s/e 없음 → 단계 설명만 렌더). @plm SRS-032 SRS-046
  "펜들레이 로우": { k: ["바를 바닥에 두고 상체가 바닥과 거의 평행이 되도록 숙인다. 어깨너비보다 조금 넓게 오버핸드로 바를 잡는다. 이것이 시작 자세다.","숨을 내쉬며 바를 명치 아래쪽으로 당긴다. 상체 각도는 그대로 두고 팔꿈치를 뒤로 보낸다.","등 근육을 쥐어짜듯 수축시켜 잠깐 멈춘다.","숨을 들이마시며 바를 바닥까지 내려 완전히 정지시킨다. 매 반복을 정지 상태에서 새로 시작한다. 정해진 반복 횟수만큼 반복한다.","팁: 반동으로 들어 올리기 쉬운 종목이다. 바가 바닥에 닿을 때마다 완전히 멈추는 것이 이 운동의 핵심이고, 허리가 말리면 무게를 낮춘다."], en: ["Set the bar on the floor and hinge until your torso is nearly parallel to the ground. Take an overhand grip slightly wider than shoulder width. This is your starting position.","Exhale and pull the bar to your lower sternum, keeping the torso angle fixed and driving the elbows back.","Squeeze the back muscles and pause briefly.","Inhale and lower the bar all the way to the floor, coming to a full stop. Start each repetition from a dead stop. Repeat for the prescribed number of repetitions.","Tip: it is easy to turn this into a swing. The dead stop on the floor each rep is the point of the lift; lower the weight if your lower back rounds."] },
  "머신 레터럴 레이즈": { k: ["시트 높이를 조절해 어깨 관절이 기구의 회전축과 같은 높이에 오게 한다. 패드 아래에 팔을 대고 앉는다. 이것이 시작 자세다.","숨을 내쉬며 팔을 옆으로 들어 올린다. 어깨높이까지가 기준이다.","맨 위에서 어깨 옆 근육을 수축시켜 1초간 유지한다.","숨을 들이마시며 천천히 내린다. 정해진 반복 횟수만큼 반복한다.","팁: 덤벨과 달리 아래 구간에서도 저항이 걸린다. 반동으로 올리지 말고 천천히 내리는 데 시간을 더 쓴다."], en: ["Adjust the seat so your shoulder joint lines up with the machine's pivot. Sit with your arms against the pads. This is your starting position.","Exhale and raise your arms out to the sides, up to about shoulder height.","Squeeze the side delts at the top and hold for a second.","Inhale and lower slowly. Repeat for the prescribed number of repetitions.","Tip: unlike dumbbells, the machine keeps resistance in the bottom range. Do not swing it up; spend more time on the way down."] },
  "파머스 워크": { s: "Farmers_Walk/0.jpg", e: "Farmers_Walk/1.jpg", k: ["파머스 워크에는 다양한 기구를 쓸 수 있다. 전용 기구가 없다면 무거운 덤벨이나 짧은 바로도 수행할 수 있다. 기구 사이에 서는 것으로 시작한다.","손잡이를 잡은 뒤 등을 곧게 펴고 머리를 든 채 뒤꿈치로 바닥을 밀며 들어 올린다.","짧고 빠른 보폭으로 걷는다. 호흡을 멈추지 않는다. 정해진 거리(보통 15~30m)를 최대한 빠르게 이동한다."], en: ["There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren't available. Begin by standing between the implements.","After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.","Walk taking short, quick steps, and don't forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible."] },
  "노르딕 컬": { k: ["무릎을 꿇고 앉아 발목을 파트너가 잡아 주거나 고정 장치에 걸어 단단히 고정한다. 상체를 곧게 세우고 무릎부터 머리까지 일직선을 만든다. 이것이 시작 자세다.","숨을 들이마시며 햄스트링으로 버티면서 상체를 아주 천천히 앞으로 넘긴다. 허리를 굽히지 말고 무릎만 축으로 쓴다.","더 버틸 수 없는 지점에서 손으로 바닥을 짚어 받아 낸다.","바닥을 밀어 시작 자세로 돌아온다. 정해진 반복 횟수만큼 반복한다.","팁: 근육이 늘어나며 버티는 부하가 매우 커 다음 날 통증이 크게 오기 쉬운 종목이다. 처음에는 밴드나 손으로 보조해 범위를 줄이고, 주 1~2회 적은 횟수부터 천천히 늘린다. 경험자의 지도를 받으며 익히는 편이 좋다."], en: ["Kneel down and have a partner hold your ankles or lock them under a secure anchor. Keep your torso upright in a straight line from knees to head. This is your starting position.","Inhale and lower your torso forward very slowly, resisting with the hamstrings. Pivot at the knees without bending at the waist.","When you can no longer hold, catch yourself with your hands on the floor.","Push off the floor to return to the starting position. Repeat for the prescribed number of repetitions.","Tip: the lengthening load here is very high and soreness the next day is common. Start with band or hand assistance to shorten the range, keep the volume low once or twice a week, and learn it under the guidance of someone experienced."] },
  "쓰러스터": { k: ["바벨이나 덤벨을 어깨 앞에 올려 프론트 랙 자세를 잡고 어깨너비로 선다. 팔꿈치를 앞으로 든다. 이것이 시작 자세다.","숨을 들이마시며 프론트 스쿼트로 앉는다. 상체는 세운 채 허벅지가 바닥과 평행이 될 때까지 내려간다.","숨을 내쉬며 일어서는 힘을 그대로 이어 머리 위로 밀어 올린다. 스쿼트와 프레스를 한 동작으로 잇는 것이 핵심이다.","무게를 어깨 앞으로 되돌리며 곧바로 다음 반복으로 이어간다. 정해진 반복 횟수만큼 반복한다.","팁: 전신을 한 번에 쓰기 때문에 숨이 빨리 차오른다. 무게보다 자세가 무너지지 않는 횟수를 기준으로 잡고, 프론트 스쿼트와 오버헤드 프레스를 각각 익힌 뒤 합치는 편이 안전하다."], en: ["Hold a barbell or dumbbells in a front rack position at the shoulders, standing about shoulder width apart with the elbows up. This is your starting position.","Inhale and descend into a front squat, keeping the torso upright until the thighs are about parallel to the floor.","Exhale and drive up out of the squat, carrying that momentum straight into an overhead press. Linking the squat and press into one motion is the point of the lift.","Bring the weight back to the shoulders and go straight into the next repetition. Repeat for the prescribed number of repetitions.","Tip: working the whole body at once makes you breathless quickly. Choose reps by where your form holds rather than by load, and learn the front squat and overhead press separately before combining them."] },
  "버피": { k: ["어깨너비로 서서 시작한다. 이것이 시작 자세다.","쪼그려 앉아 양손을 발 앞 바닥에 짚는다.","두 발을 뒤로 차 플랭크 자세를 만들고, 원한다면 여기서 푸시업을 한 번 한다.","두 발을 다시 손 쪽으로 당겨 쪼그려 앉은 자세로 돌아온 뒤, 그대로 위로 점프하며 머리 위에서 손뼉을 친다. 착지하면 곧바로 다음 반복으로 이어간다.","팁: 지칠수록 허리가 꺼지고 착지가 거칠어진다. 횟수를 채우기보다 자세가 유지되는 만큼만 하고, 무릎·허리가 불편하면 점프를 빼고 걸어서 발을 옮기는 방식으로 바꾼다."], en: ["Start standing with your feet about shoulder width apart. This is your starting position.","Squat down and place both hands on the floor in front of your feet.","Kick your feet back into a plank position, and add a push-up here if you want one.","Jump the feet back toward your hands into the squat position, then jump up and clap overhead. Land and go straight into the next repetition.","Tip: as you tire the lower back sags and landings get sloppy. Stop at the point your form holds rather than chasing the rep count, and if the knees or back complain, step the feet instead of jumping."] },
  "펜듈럼 스쿼트": { k: ["펜듈럼 스쿼트 머신의 발판에 어깨너비로 발을 딛고 어깨 패드 아래에 선다. 등을 등받이에 붙이고 손잡이를 잡는다. 이것이 시작 자세다.","숨을 들이마시며 무릎을 굽혀 몸이 호를 그리며 내려가게 한다. 허벅지가 바닥과 평행이 되는 깊이를 기준으로 한다.","가장 낮은 지점에서 잠깐 멈춘다.","숨을 내쉬며 발판을 밀어 시작 자세로 올라온다. 정해진 반복 횟수만큼 반복한다.","팁: 궤적이 호를 그려 무릎과 허리 부담이 백스쿼트보다 적다. 발을 발판 아래쪽에 두면 대퇴사두, 위쪽에 두면 둔근·햄스트링이 더 쓰인다."], en: ["Stand on the platform of a pendulum squat machine with feet about shoulder width and your shoulders under the pads. Keep your back on the pad and hold the handles. This is your starting position.","Inhale and bend the knees so your body travels down along an arc, aiming for thighs about parallel to the platform.","Pause briefly at the bottom.","Exhale and drive through the platform back to the starting position. Repeat for the prescribed number of repetitions.","Tip: the arc path puts less demand on the knees and lower back than a back squat. Feet lower on the platform bias the quads; higher biases glutes and hamstrings."] },
  "벨트 스쿼트": { k: ["벨트 스쿼트 기구의 허리 벨트를 골반에 채우고 발판 위에 어깨너비로 선다. 손잡이가 있으면 가볍게 잡아 균형만 잡는다. 이것이 시작 자세다.","숨을 들이마시며 무릎을 굽혀 앉는다. 허벅지가 바닥과 평행이 되는 깊이를 기준으로 한다.","가장 낮은 지점에서 잠깐 멈춘다.","숨을 내쉬며 바닥을 밀어 일어선다. 정해진 반복 횟수만큼 반복한다.","팁: 무게가 골반에 걸려 어깨·척추에 실리지 않는 것이 이 종목의 장점이다. 상체를 세운 채 다리로만 밀어 올린다."], en: ["Fasten the belt of the belt squat machine around your hips and stand on the platform at about shoulder width. If there are handles, hold them lightly for balance only. This is your starting position.","Inhale and bend the knees to squat down, aiming for thighs about parallel to the floor.","Pause briefly at the bottom.","Exhale and drive through the floor to stand back up. Repeat for the prescribed number of repetitions.","Tip: the load hangs from the hips instead of sitting on the shoulders or spine — that is the point of the lift. Stay upright and drive with the legs only."] },
  "로우 (스미스)": { k: ["스미스머신 바를 무릎 아래 높이에 맞춘다. 상체를 숙여 바닥과 45도 안쪽이 되게 하고 오버핸드로 바를 잡는다. 이것이 시작 자세다.","숨을 내쉬며 바를 배 쪽으로 당긴다. 팔꿈치를 몸통 가까이 붙여 뒤로 보낸다.","등을 수축시킨 채 1초간 멈춘다.","숨을 들이마시며 팔이 펴질 때까지 천천히 내린다. 정해진 반복 횟수만큼 반복한다.","팁: 궤적이 고정돼 있어 자세를 유지하기 쉽다. 대신 발 위치가 어긋나면 허리에 부담이 가니 바 바로 아래에 서서 잡는다."], en: ["Set the Smith machine bar just below knee height. Hinge until your torso is under 45 degrees to the floor and take an overhand grip. This is your starting position.","Exhale and pull the bar toward your stomach, keeping the elbows close to the body and driving them back.","Hold for a second with the back contracted.","Inhale and lower slowly until the arms are extended. Repeat for the prescribed number of repetitions.","Tip: the fixed path makes the position easy to hold, but standing off-line loads the lower back. Set your feet directly under the bar."] },
  "숄더 프레스 (스미스)": { k: ["스미스머신 바 아래에 벤치를 놓고 앉는다. 바가 귀 옆·어깨 높이에 오도록 맞추고 어깨너비보다 조금 넓게 잡는다. 이것이 시작 자세다.","바를 살짝 밀어 고리를 풀고, 숨을 내쉬며 머리 위로 밀어 올린다.","맨 위에서 팔을 편 채 1초간 유지한다. 팔꿈치는 완전히 잠그지 않는다.","숨을 들이마시며 어깨 높이까지 천천히 내린다. 정해진 반복 횟수만큼 반복한다.","팁: 궤적이 수직으로 고정돼 있어 바가 머리에 가까이 지난다. 머리를 살짝 뒤로 빼되 목을 과하게 젖히지는 않는다."], en: ["Place a bench under the Smith machine bar and sit down. Set the bar at shoulder height beside your ears and grip slightly wider than shoulder width. This is your starting position.","Press slightly to unhook the catches, then exhale and press the bar overhead.","Hold for a second at the top with the arms extended, without locking the elbows hard.","Inhale and lower slowly back to shoulder height. Repeat for the prescribed number of repetitions.","Tip: the fixed vertical path brings the bar close to your head. Move your head back slightly rather than craning your neck."] },
  "슈러그 (스미스)": { k: ["스미스머신 바를 허벅지 높이에 맞추고 어깨너비로 잡은 채 선다. 팔은 편 채로 늘어뜨린다. 이것이 시작 자세다.","숨을 내쉬며 어깨를 귀 쪽으로 곧게 들어 올린다. 팔은 굽히지 않는다.","맨 위에서 승모근을 수축시켜 1초간 유지한다.","숨을 들이마시며 어깨를 천천히 내린다. 정해진 반복 횟수만큼 반복한다.","팁: 어깨를 돌리지 말고 위아래로만 움직인다. 무게가 무거우면 스트랩을 쓰면 악력보다 승모근이 먼저 지친다."], en: ["Set the Smith machine bar at thigh height, grip it at shoulder width and stand up. Let your arms hang straight. This is your starting position.","Exhale and lift your shoulders straight up toward your ears without bending the arms.","Squeeze the traps at the top and hold for a second.","Inhale and lower the shoulders slowly. Repeat for the prescribed number of repetitions.","Tip: move straight up and down rather than rolling the shoulders. On heavy sets, straps let the traps fail before your grip does."] },
  "해머스트렝스 체스트 프레스": { k: ["시트 높이를 조절해 손잡이가 가슴 중앙 높이에 오게 한다. 등과 어깨를 등받이에 붙이고 손잡이를 잡는다. 이것이 시작 자세다.","숨을 내쉬며 손잡이를 앞으로 밀어 팔을 편다. 팔꿈치를 완전히 잠그지 않고 살짝 여유를 둔다.","가슴을 쥐어짜듯 수축시킨 채 1초간 멈춘다.","숨을 들이마시며 가슴이 늘어나는 느낌이 들 때까지 손잡이를 천천히 되돌린다. 정해진 반복 횟수만큼 반복한다.","팁: 좌우 팔이 독립적으로 움직이는 기구라 약한 쪽이 티가 난다. 무게를 낮춰 양쪽 궤적을 같게 맞추는 편이 낫다."], en: ["Adjust the seat so the handles sit at mid-chest height. Keep your back and shoulders against the pad and grasp the handles. This is your starting position.","Exhale and press the handles forward until your arms are extended, keeping a slight bend in the elbows.","Squeeze your chest and hold for a second.","Inhale and return the handles slowly until you feel a stretch across the chest. Repeat for the prescribed number of repetitions.","Tip: the arms move independently on this machine, so a weaker side shows. Lower the load and match both paths rather than forcing the strong side."] },
  "디클라인 체스트 프레스 머신": { k: ["시트에 앉아 등을 등받이에 붙인다. 손잡이가 아랫가슴 높이에 오도록 시트를 맞추고 손잡이를 잡는다. 이것이 시작 자세다.","숨을 내쉬며 손잡이를 비스듬히 아래·앞으로 밀어 팔을 편다.","아랫가슴이 수축하는 느낌을 잡은 채 1초간 멈춘다.","숨을 들이마시며 천천히 되돌린다. 정해진 반복 횟수만큼 반복한다.","팁: 어깨가 앞으로 말리면 가슴 대신 어깨가 일한다. 견갑을 뒤·아래로 고정한 채 밀어낸다."], en: ["Sit with your back flat against the pad. Set the seat so the handles align with your lower chest and grasp them. This is your starting position.","Exhale and press the handles down and forward until your arms are extended.","Hold for a second while keeping tension in the lower chest.","Inhale and return slowly. Repeat for the prescribed number of repetitions.","Tip: if the shoulders roll forward the delts take over. Keep the shoulder blades set back and down as you press."] },
  "라잉 체스트 프레스 머신": { k: ["누운 자세의 프레스 머신에 등을 대고 눕는다. 손잡이가 가슴 옆에 오도록 위치를 잡고 손잡이를 잡는다. 이것이 시작 자세다.","숨을 내쉬며 손잡이를 천장 쪽으로 밀어 올린다.","맨 위에서 가슴을 수축시켜 1초간 유지한다.","숨을 들이마시며 가슴 옆까지 천천히 내린다. 정해진 반복 횟수만큼 반복한다.","팁: 궤적이 기구에 고정돼 있어 무게를 올리기 쉽다. 어깨가 아프면 가동 범위를 줄이고 무게를 낮춘다."], en: ["Lie back on the lying press machine. Position yourself so the handles sit beside your chest and grasp them. This is your starting position.","Exhale and press the handles toward the ceiling.","Squeeze the chest at the top and hold for a second.","Inhale and lower slowly until the handles are back beside your chest. Repeat for the prescribed number of repetitions.","Tip: the fixed path makes it easy to add load. If the shoulder complains, shorten the range and lower the weight."] },
  "컨버징 체스트 프레스 머신": { k: ["시트에 앉아 손잡이가 가슴 중앙에 오게 높이를 맞춘다. 등을 등받이에 붙이고 손잡이를 잡는다. 이것이 시작 자세다.","숨을 내쉬며 손잡이를 앞으로 민다. 이 기구는 밀수록 두 손이 안쪽으로 모이는 궤적이다.","두 손이 가장 가까워지는 지점에서 가슴을 쥐어짜듯 수축시켜 1초간 유지한다.","숨을 들이마시며 천천히 되돌린다. 정해진 반복 횟수만큼 반복한다.","팁: 모이는 궤적 덕분에 가슴 안쪽 수축이 잘 느껴진다. 끝에서 억지로 더 모으려 어깨를 앞으로 말지 않는다."], en: ["Sit and set the seat so the handles align with mid-chest. Keep your back on the pad and grasp the handles. This is your starting position.","Exhale and press forward. On this machine the handles converge inward as you press.","At the point where your hands are closest, squeeze the chest and hold for a second.","Inhale and return slowly. Repeat for the prescribed number of repetitions.","Tip: the converging path makes the inner chest contraction easy to feel. Do not round the shoulders forward to squeeze harder at the end."] },
  "원암 체스트 프레스 머신": { k: ["시트에 앉아 한 손으로만 손잡이를 잡는다. 반대 손은 시트나 몸통 옆을 잡아 상체를 고정한다. 이것이 시작 자세다.","숨을 내쉬며 손잡이를 앞으로 밀어 팔을 편다. 몸통이 따라 돌아가지 않게 코어로 버틴다.","가슴을 수축시킨 채 1초간 멈춘다.","숨을 들이마시며 천천히 되돌린다. 한쪽을 끝내고 반대쪽도 같은 횟수만큼 반복한다.","팁: 한쪽씩 하는 목적은 좌우 차이를 메우는 것이다. 약한 쪽 횟수에 맞춰 양쪽을 같게 한다."], en: ["Sit and take one handle with a single hand. Hold the seat or your side with the other hand to anchor your torso. This is your starting position.","Exhale and press the handle forward until the arm is extended. Brace so the torso does not rotate with it.","Hold for a second with the chest contracted.","Inhale and return slowly. Finish one side, then repeat for the same number of repetitions on the other.","Tip: the point of working one side at a time is to close a left-right gap. Match both sides to the weaker side's count."] },
  "시티드 케이블 체스트 프레스": { k: ["케이블 머신을 등지고 벤치에 앉는다. 도르래를 가슴 높이에 맞추고 양손으로 손잡이를 잡아 가슴 옆에 둔다. 이것이 시작 자세다.","숨을 내쉬며 손잡이를 앞으로 밀어 팔을 편다.","가장 멀리 민 지점에서 가슴을 수축시켜 1초간 유지한다.","숨을 들이마시며 가슴 옆까지 천천히 되돌린다. 정해진 반복 횟수만큼 반복한다.","팁: 케이블은 끝까지 장력이 걸려 바벨보다 수축 구간이 유리하다. 되돌릴 때 힘을 빼지 말고 버티며 내린다."], en: ["Sit on a bench with your back to the cable machine. Set the pulleys at chest height and hold a handle in each hand beside your chest. This is your starting position.","Exhale and press the handles forward until your arms are extended.","At full extension squeeze the chest and hold for a second.","Inhale and return slowly to beside your chest. Repeat for the prescribed number of repetitions.","Tip: cables keep tension through the whole range, which favours the contracted position. Resist on the way back instead of letting it snap."] },
  "스탠딩 케이블 체스트 프레스": { s: "Standing_Cable_Chest_Press/0.jpg", e: "Standing_Cable_Chest_Press/1.jpg", k: ["양쪽 풀리를 가슴 높이에 맞추고 적절한 무게를 선택한다. 케이블 앞으로 한두 걸음 나와 서서 양손에 손잡이를 하나씩 잡는다. 안정성을 위해 발을 앞뒤로 엇갈려 서도 좋다.","위팔이 90도가 되게 하고 견갑골을 모은다. 이것이 시작 자세다.","나머지 몸은 고정한 채 팔꿈치를 펴며 손잡이를 앞으로 밀어 몸 정면에서 모은다.","동작 맨 위에서 잠깐 멈춘 뒤 시작 자세로 되돌아간다."], en: ["Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.","Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.","Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.","Pause at the top of the motion, and return to the starting position."] },
  "라잉 케이블 체스트 프레스": { k: ["케이블 머신 사이에 벤치를 놓고 등을 대고 눕는다. 도르래를 가장 낮게 두고 양손으로 손잡이를 잡아 가슴 옆에 둔다. 이것이 시작 자세다.","숨을 내쉬며 손잡이를 천장 쪽으로 밀어 올린다.","맨 위에서 가슴을 쥐어짜듯 수축시켜 1초간 유지한다.","숨을 들이마시며 가슴 옆까지 천천히 내린다. 정해진 반복 횟수만큼 반복한다.","팁: 벤치 위치가 조금만 어긋나도 궤적이 틀어진다. 첫 세트는 가벼운 무게로 위치를 잡고 시작한다."], en: ["Set a bench between two cable stacks and lie back on it. Put the pulleys at their lowest setting and hold a handle in each hand beside your chest. This is your starting position.","Exhale and press the handles toward the ceiling.","Squeeze the chest at the top and hold for a second.","Inhale and lower slowly to beside your chest. Repeat for the prescribed number of repetitions.","Tip: a bench that is slightly off centre throws the path off. Use a light first set to find the position."] },
  "라슨 프레스": { k: ["플랫 벤치에 등을 대고 눕되 발을 바닥에 딛지 않고 벤치 앞으로 곧게 뻗어 든다. 견갑을 모아 벤치에 고정하고 바를 잡는다. 이것이 시작 자세다.","숨을 들이마시며 바를 가슴 중앙까지 천천히 내린다. 다리 반동을 쓸 수 없으므로 상체만으로 버틴다.","잠깐 멈춘 뒤 숨을 내쉬며 바를 밀어 올린다.","정해진 반복 횟수만큼 반복한다. 끝나면 바를 랙에 건다.","팁: 다리 지지를 뺀 만큼 균형이 불안정하다. 평소 벤치프레스보다 무게를 크게 낮추고, 무거운 세트는 보조자를 두고 한다."], en: ["Lie back on a flat bench but hold your legs straight out in front of you instead of planting your feet. Set your shoulder blades against the bench and grip the bar. This is your starting position.","Inhale and lower the bar slowly to mid-chest. With no leg drive available, control it with the upper body alone.","Pause briefly, then exhale and press the bar back up.","Repeat for the prescribed number of repetitions, then rack the bar.","Tip: removing leg support makes balance less stable. Use much less weight than your usual bench press, and keep a spotter for heavy sets."] },
  "피트 업 벤치프레스": { k: ["플랫 벤치에 등을 대고 눕고 두 발을 벤치 위로 올려 무릎을 굽힌다. 견갑을 모아 고정하고 바를 잡는다. 이것이 시작 자세다.","숨을 들이마시며 바를 가슴 중앙까지 천천히 내린다. 허리가 뜨지 않도록 배에 힘을 준다.","잠깐 멈춘 뒤 숨을 내쉬며 밀어 올린다.","정해진 반복 횟수만큼 반복한다. 끝나면 바를 랙에 건다.","팁: 발을 올리면 아치와 다리 반동이 사라져 가슴에 더 집중된다. 대신 균형이 나빠지므로 무게를 낮추고 보조자를 두는 편이 안전하다."], en: ["Lie back on a flat bench and place both feet up on the bench with knees bent. Set your shoulder blades and grip the bar. This is your starting position.","Inhale and lower the bar slowly to mid-chest, bracing so the lower back does not arch off the bench.","Pause briefly, then exhale and press back up.","Repeat for the prescribed number of repetitions, then rack the bar.","Tip: feet up removes the arch and leg drive, putting more work on the chest. Balance is worse, so lower the weight and keep a spotter."] },
  "디클라인 프레스 (스미스)": { k: ["디클라인 벤치를 스미스머신 바 아래에 놓고 등을 대고 눕는다. 바가 아랫가슴 위에 오도록 위치를 맞추고 잡는다. 이것이 시작 자세다.","바를 살짝 밀어 안전 고리를 풀고, 숨을 들이마시며 아랫가슴까지 천천히 내린다.","잠깐 멈춘 뒤 숨을 내쉬며 밀어 올린다.","정해진 반복 횟수만큼 반복한다. 끝나면 고리를 걸어 바를 고정한다.","팁: 머리가 아래로 향하는 자세라 어지러울 수 있다. 세트가 끝나면 곧바로 일어나지 말고 잠시 앉아 있다가 움직인다."], en: ["Set a decline bench under the Smith machine bar and lie back. Position yourself so the bar tracks over your lower chest and grip it. This is your starting position.","Press slightly to unhook the safety catches, then inhale and lower the bar slowly to your lower chest.","Pause briefly, then exhale and press back up.","Repeat for the prescribed number of repetitions, then re-hook the bar.","Tip: the head-down position can make you light-headed. After the set, sit up for a moment before standing."] },
  "와이드 그립 푸시업": { k: ["어깨너비보다 훨씬 넓게 손을 짚고 머리부터 발뒤꿈치까지 일직선이 되도록 푸시업 자세를 잡는다. 이것이 시작 자세다.","숨을 들이마시며 가슴이 바닥에 가까워질 때까지 몸을 천천히 내린다. 팔꿈치는 옆으로 벌어진다.","숨을 내쉬며 바닥을 밀어 시작 자세로 돌아온다.","정해진 반복 횟수만큼 반복한다.","팁: 손이 넓을수록 가슴 바깥쪽이 더 쓰이지만 어깨 부담도 커진다. 어깨 앞쪽이 결리면 손 너비를 좁힌다."], en: ["Set your hands well wider than shoulder width and get into a push-up position with a straight line from head to heels. This is your starting position.","Inhale and lower slowly until your chest is close to the floor; the elbows flare out to the sides.","Exhale and push the floor away to return to the starting position.","Repeat for the prescribed number of repetitions.","Tip: a wider hand position works the outer chest more but also loads the shoulder. Narrow the hands if the front of the shoulder complains."] },
  "데피싯 푸시업": { k: ["양손을 푸시업 바나 낮은 블록 위에 올려 손이 바닥보다 높게 만든다. 머리부터 발뒤꿈치까지 일직선을 유지한다. 이것이 시작 자세다.","숨을 들이마시며 가슴이 손 높이보다 아래로 내려갈 때까지 천천히 내린다.","가장 낮은 지점에서 가슴이 늘어나는 느낌을 잡고 잠깐 멈춘다.","숨을 내쉬며 밀어 올려 시작 자세로 돌아온다. 정해진 반복 횟수만큼 반복한다.","팁: 가동 범위가 넓어지는 만큼 어깨가 늘어난다. 처음에는 낮은 높이로 시작해 통증 없이 되는 범위까지만 내린다."], en: ["Place your hands on push-up bars or low blocks so they sit above floor level. Keep a straight line from head to heels. This is your starting position.","Inhale and lower slowly until your chest drops below the level of your hands.","Feel the stretch across the chest at the bottom and pause briefly.","Exhale and press back up to the starting position. Repeat for the prescribed number of repetitions.","Tip: the added range also stretches the shoulder. Start with a small deficit and only go as deep as stays pain-free."] },
  "체스트 서포티드 티바 로우": { k: ["티바 로우 머신의 패드에 가슴을 대고 엎드린다. 발을 발판에 딛고 손잡이를 잡는다. 이것이 시작 자세다.","숨을 내쉬며 손잡이를 몸 쪽으로 당긴다. 팔꿈치를 뒤로 보내고 견갑을 모은다.","등을 쥐어짜듯 수축시켜 1초간 유지한다.","숨을 들이마시며 팔이 펴질 때까지 천천히 되돌린다. 정해진 반복 횟수만큼 반복한다.","팁: 가슴을 받쳐 주므로 허리 부담 없이 등만 쓸 수 있다. 패드에서 몸을 떼며 반동을 주면 그 장점이 사라진다."], en: ["Lie face down with your chest on the pad of a chest-supported T-bar row. Plant your feet and take the handles. This is your starting position.","Exhale and pull the handles toward you, driving the elbows back and retracting the shoulder blades.","Squeeze the back and hold for a second.","Inhale and return slowly until the arms are extended. Repeat for the prescribed number of repetitions.","Tip: the chest pad lets you work the back without loading the lower back. Heaving off the pad throws that advantage away."] },
  "싯업": { s: "Sit-Up/0.jpg", e: "Sit-Up/1.jpg", k: ["바닥에 누워 발을 움직이지 않는 물체 아래에 고정하거나 파트너가 잡아 준다. 무릎은 구부린다.","두 손을 머리 뒤에 대고 손가락을 깍지 껴 고정한다. 이것이 시작 자세다.","상체를 들어 올려 허벅지와 V자를 이루게 한다. 이 구간에서 숨을 내쉰다.","수축을 1초간 느낀 뒤 숨을 들이마시며 상체를 시작 자세로 내린다.","권장 반복 횟수만큼 반복한다."], en: ["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.","Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."] },
  "디클라인 푸시업": { s: "Decline_Push-Up/0.jpg", e: "Decline_Push-Up/1.jpg", k: ["바닥에 엎드려 팔을 편 채 상체를 들어 올리고 손을 약 90cm 간격으로 짚는다. 발을 박스나 벤치 위에 올린다. 이것이 시작 자세다.","숨을 들이마시며 가슴이 바닥에 거의 닿을 때까지 몸을 내린다.","숨을 내쉬며 가슴을 쥐어짜듯 수축시키면서 상체를 시작 자세로 밀어 올린다.","맨 위 수축 자세에서 잠깐 멈춘 뒤 다시 몸을 내리며 필요한 횟수만큼 반복한다."], en: ["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."] },
  "클랩 푸시업": { k: ["어깨너비보다 약간 넓게 손을 짚고 머리부터 발뒤꿈치까지 일직선이 되도록 푸시업 자세를 잡는다. 코어에 힘을 주어 몸통을 단단히 고정한다. 이것이 시작 자세다.","숨을 들이마시며 가슴이 바닥에 가까워질 때까지 몸을 천천히 내린다.","숨을 내쉬며 바닥을 폭발적으로 밀어 상체가 공중에 뜨게 하고, 그 순간 빠르게 손뼉을 친 뒤 다시 손을 제자리에 짚으며 착지한다.","팔꿈치를 살짝 굽혀 충격을 흡수하며 곧바로 다음 반복으로 이어간다. 정해진 반복 횟수만큼 동작을 반복한다.","팁: 착지할 때 손목 부담을 줄이려면 팔꿈치를 편 채 떨어지지 말고 반드시 굽히면서 받아낸다. 일반 푸시업을 충분히 다진 뒤 무릎 클랩 푸시업부터 점진적으로 연습하면 안전하게 익힐 수 있다."], en: ["Get into a push-up position with your hands slightly wider than shoulder width, keeping your body in a straight line from head to heels. Brace your core to keep your torso rigid. This is your starting position.","Breathe in and slowly lower your body until your chest is close to the floor.","Breathe out and explosively push off the floor so your upper body leaves the ground, quickly clap your hands, then place them back and land in the starting position.","Absorb the landing by slightly bending your elbows and flow straight into the next rep. Repeat for the prescribed amount of repetitions.","Tip: To protect your wrists, never land with locked elbows—always bend them to absorb the impact. Master regular push-ups first and progress from kneeling clap push-ups to learn the movement safely."] },
  "닐링 푸시업": { k: ["바닥에 무릎을 대고 발목을 교차하거나 바닥에 편안히 둔 채, 어깨너비보다 약간 넓게 손을 짚는다. 무릎부터 머리까지 일직선이 되도록 골반을 앞으로 밀어 정렬한다. 이것이 시작 자세다.","숨을 들이마시며 팔꿈치를 굽혀 가슴이 바닥에 가까워질 때까지 몸을 천천히 내린다. 팔꿈치는 몸통에서 약 45도 정도 벌어지게 한다.","숨을 내쉬며 가슴 힘으로 바닥을 밀어 시작 자세로 돌아온다. 동작 맨 위에서 가슴을 1초간 수축시킨다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 엉덩이가 뒤로 빠지면 가슴 자극이 줄어든다. 무릎-골반-어깨가 일직선을 유지하도록 코어에 힘을 준다. 이 동작이 익숙해지면 일반 푸시업으로 넘어간다."], en: ["Kneel on the floor with your ankles crossed or resting comfortably, and place your hands slightly wider than shoulder width. Push your hips forward so your body forms a straight line from knees to head. This is your starting position.","Breathe in and bend your elbows to slowly lower your body until your chest is close to the floor. Keep your elbows at about a 45-degree angle from your torso.","Breathe out and push through your chest to return to the starting position. Squeeze your chest for a second at the top.","Repeat for the prescribed amount of repetitions.","Tip: If your hips drift back, chest stimulation decreases. Brace your core to keep your knees, hips, and shoulders in one straight line. Once this feels comfortable, progress to standard push-ups."] },
  "원암 푸시업": { s: "Single-Arm_Push-Up/0.jpg", e: "Single-Arm_Push-Up/1.jpg", k: ["바닥에 엎드린 자세로 시작한다. 발끝과 한쪽 팔로 체중을 지지하는 자세를 만든다. 지지하는 팔은 어깨 바로 아래에 완전히 편 채로 둔다. 다리는 뻗고, 이 동작에서는 일반 푸시업보다 발을 더 넓게 벌려 지지 기반을 넓혀야 할 수 있다.","좋은 자세를 유지하며 반대쪽 손을 등 뒤에 둔다. 이것이 시작 자세다.","팔꿈치를 굽혀 몸이 바닥에 닿을 때까지 내려간다.","천천히 내려간 뒤 팔을 펴서 시작 자세로 돌아온다."], en: ["Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up.","Maintain good posture, and place your free hand behind your back. This will be your starting position.","Lower yourself by allowing the elbow to flex until you touch the ground.","Descend slowly, and reverse direction be extending the arm to return to the starting position."] },
  "플랭크 푸시업": { k: ["팔꿈치와 전완을 바닥에 대고 머리부터 발뒤꿈치까지 일직선이 되는 플랭크 자세를 잡는다. 코어와 둔근에 힘을 주어 몸통을 고정한다. 이것이 시작 자세다.","한쪽 손바닥을 팔꿈치가 있던 자리에 짚고 팔을 펴며, 이어서 반대쪽 손도 짚어 푸시업 자세(하이 플랭크)로 올라간다. 올라가는 동안 숨을 내쉰다.","올라간 순서대로 한 팔씩 다시 팔꿈치를 내려 플랭크 자세로 돌아온다. 내려가는 동안 숨을 들이마신다.","리드하는 팔을 매 반복 또는 세트마다 번갈아 바꾸며 정해진 반복 횟수만큼 동작을 반복한다.","팁: 올라가고 내려가는 동안 골반이 좌우로 흔들리는 것이 가장 흔한 실수다. 발을 어깨너비보다 넓게 벌리고 코어를 조이면 몸통을 안정적으로 유지할 수 있다."], en: ["Start in a forearm plank with your elbows and forearms on the floor, body in a straight line from head to heels. Brace your core and glutes to keep your torso rigid. This is your starting position.","Place one palm where your elbow was and extend that arm, then follow with the other hand to press up into a high plank (push-up position). Breathe out as you press up.","Lower back down one arm at a time in the same order, returning to the forearm plank. Breathe in as you lower.","Alternate the leading arm each rep or each set, and repeat for the prescribed amount of repetitions.","Tip: The most common mistake is letting your hips rock side to side. Set your feet wider than shoulder width and squeeze your core to keep your torso stable."] },
  "링 푸시업": { k: ["링을 바닥 가까이 낮게 조절하고, 링을 잡은 채 팔을 편 푸시업 자세를 잡는다. 머리부터 발뒤꿈치까지 일직선을 유지하고 코어에 힘을 준다. 이것이 시작 자세다.","숨을 들이마시며 팔꿈치를 굽혀 가슴이 링 높이 부근에 올 때까지 몸을 천천히 내린다. 링이 흔들리지 않도록 어깨와 코어로 통제한다.","숨을 내쉬며 가슴 힘으로 링을 밀어 시작 자세로 돌아온다. 동작 맨 위에서 링을 살짝 바깥으로 돌리며 가슴을 수축시킨다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 링이 불안정할수록 어깨가 으쓱 올라가기 쉽다. 견갑골을 아래로 끌어내려 고정한 상태를 유지하고, 흔들림이 심하면 링 높이를 올려 난이도를 낮춘 뒤 점진적으로 낮춘다."], en: ["Set the rings low near the floor and get into a push-up position gripping the rings with your arms extended. Keep a straight line from head to heels and brace your core. This is your starting position.","Breathe in and bend your elbows to slowly lower your body until your chest is near ring level. Control the rings with your shoulders and core so they do not sway.","Breathe out and press the rings away using your chest to return to the starting position. At the top, turn the rings slightly outward and squeeze your chest.","Repeat for the prescribed amount of repetitions.","Tip: The more unstable the rings, the easier it is to shrug your shoulders up. Keep your shoulder blades pulled down and set, and if the sway is too much, raise the rings to reduce difficulty and lower them progressively."] },
  "플로어 프레스": { s: "Floor_Press/0.jpg", e: "Floor_Press/1.jpg", k: ["바를 걸 수 있도록 J훅을 적절한 높이로 조절한다. 머리가 파워랙 끝 근처에 오도록 바닥에 눕는다. 견갑골을 모은 상태를 유지하며 훅에서 바를 빼낸다.","바를 꽉 쥐고 양옆으로 찢듯이 당기는 느낌을 유지하며 가슴 아래쪽이나 윗배 쪽으로 바를 내린다. 동작 내내 팔꿈치를 몸통 쪽으로 붙인다. 위팔이 바닥에 닿을 때까지 내린 뒤 잠깐 멈추고, 무게를 내려찍거나 튕기지 않는다.","바와 손목, 팔꿈치가 일직선을 유지하도록 하면서 최대한 빠르게 바를 다시 밀어 올린다."], en: ["Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."] },
  "덤벨 스퀴즈 프레스": { k: ["플랫 벤치에 등을 대고 눕고, 양손에 덤벨을 뉴트럴 그립(손바닥이 서로 마주 보는 그립)으로 들어 가슴 위에서 서로 맞붙인다. 이것이 시작 자세다.","덤벨을 안쪽으로 강하게 맞누르는 힘을 유지한 채, 숨을 들이마시며 덤벨을 가슴 중앙까지 천천히 내린다.","숨을 내쉬며 덤벨을 계속 맞누른 상태로 시작 자세까지 밀어 올린다. 동작 맨 위에서 가슴 안쪽을 1초간 수축시킨다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 이 운동의 핵심은 무게가 아니라 덤벨을 안쪽으로 쥐어짜는 압력이다. 동작 내내 맞누르는 힘이 풀리지 않도록 가벼운 무게로 천천히 수행한다."], en: ["Lie back on a flat bench holding two dumbbells with a neutral grip (palms facing each other) and press them together over your chest. This is your starting position.","While actively squeezing the dumbbells together, breathe in and slowly lower them to the middle of your chest.","Breathe out and press the dumbbells back up to the starting position while maintaining the inward squeeze. Contract your inner chest for a second at the top.","Repeat for the prescribed amount of repetitions.","Tip: The key to this exercise is the inward pressure squeezing the dumbbells together, not the load. Use a lighter weight and move slowly so the squeeze never loosens throughout the movement."] },
  "스벤드 프레스": { s: "Svend_Press/0.jpg", e: "Svend_Press/1.jpg", k: ["선 자세로 시작한다.","가벼운 원판 두 장을 양손으로 맞대어 누른다. 원판을 가슴 가까이에 붙여 가슴 근육에 등척성 수축을 만든다. 손가락은 앞을 향하게 한다. 이것이 시작 자세다.","손바닥 사이의 원판을 꽉 누른 채 통제된 동작으로 팔을 몸 정면으로 곧게 뻗는다.","동작 끝에서 잠깐 멈춘 뒤 천천히 시작 자세로 되돌아간다."], en: ["Begin in a standing position.","Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.","Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.","Pause at the top of the motion, and then slowly return to the starting position."] },
  "디클라인 덤벨 플라이": { s: "Decline_Dumbbell_Flyes/0.jpg", e: "Decline_Dumbbell_Flyes/1.jpg", k: ["디클라인 벤치 끝에 다리를 고정하고, 양손에 덤벨을 하나씩 든 채 허벅지 위에 올리고 눕는다. 손바닥은 서로 마주 보게 한다.","누운 뒤 덤벨을 어깨너비로 몸 앞에 들어 올린다. 손바닥은 서로 마주 보고 팔은 바닥과 수직으로 완전히 편 상태여야 한다. 이것이 시작 자세다.","이두 힘줄에 부담이 가지 않도록 팔꿈치를 살짝 굽힌 채, 가슴에 스트레칭이 느껴질 때까지 두 팔을 넓은 호를 그리며 양옆으로 내린다. 이 구간에서 숨을 들이마신다. 팁: 동작 내내 팔 모양은 고정하고, 움직임은 어깨 관절에서만 일어나야 한다.","가슴 근육을 조이고 숨을 내쉬면서 팔을 시작 자세로 되돌린다. 팁: 내릴 때 그린 호와 같은 궤적으로 올린다.","수축 지점에서 1초간 유지하고 정해진 반복 횟수만큼 동작을 반복한다."], en: ["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."] },
  "시티드 케이블 플라이": { k: ["케이블 머신 중앙에 벤치를 두고, 양쪽 풀리를 가슴 높이 부근으로 맞춘다. 벤치에 앉아 등을 패드에 붙이고 양손으로 핸들을 잡아 팔을 옆으로 벌린다. 팔꿈치는 살짝 굽힌 각도로 고정한다. 이것이 시작 자세다.","숨을 내쉬며 팔꿈치 각도를 유지한 채 큰 호를 그리듯 양손을 가슴 앞 중앙으로 모은다. 팔이 아니라 가슴이 무게를 끌고 온다는 느낌에 집중한다.","양손이 만나는 지점에서 가슴을 1초간 강하게 수축시킨다.","숨을 들이마시며 가슴이 늘어나는 느낌이 들 때까지 같은 궤적으로 천천히 팔을 벌려 시작 자세로 돌아온다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 손을 모을 때 팔꿈치를 펴면 삼두에 힘이 분산된다. 동작 내내 팔꿈치 각도를 고정하고, 어깨가 앞으로 말리지 않도록 견갑골을 벤치에 붙인 채 유지한다."], en: ["Place a bench in the center of a cable machine and set both pulleys at about chest height. Sit with your back against the pad, grab the handles, and open your arms out to the sides with a slight, fixed bend in your elbows. This is your starting position.","Breathe out and bring both hands together in front of your chest in a wide arc, keeping the elbow angle fixed. Focus on your chest pulling the weight, not your arms.","Squeeze your chest hard for a second as your hands meet.","Breathe in and slowly open your arms along the same arc until you feel a stretch in your chest, returning to the starting position.","Repeat for the prescribed amount of repetitions.","Tip: Extending your elbows as you bring the hands together shifts tension to the triceps. Keep the elbow angle locked throughout, and keep your shoulder blades pinned to the bench so your shoulders do not roll forward."] },
  "덤벨 어라운드 더 월드": { s: "Around_The_Worlds/0.jpg", e: "Around_The_Worlds/1.jpg", k: ["플랫 벤치에 누워 양손에 덤벨을 들고 손바닥이 천장을 향하게 한다. 팁: 팔은 바닥과 평행하게 허벅지 옆에 둔다. 부상을 막으려면 팔꿈치를 살짝 굽힌 상태를 유지한다. 이것이 시작 자세다.","덤벨로 반원을 그리며 처음 위치에서 머리 위까지 이동시킨다. 동작 내내 팔은 바닥과 평행을 유지해야 한다. 이 구간에서 숨을 들이마신다.","숨을 내쉬며 동작을 역순으로 되돌려 중량을 시작 자세로 가져온다."], en: ["Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.","Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.","Reverse the movement to return the weight to the starting position as you exhale."] },
  "링 딥스": { s: "Ring_Dips/0.jpg", e: "Ring_Dips/1.jpg", k: ["양손으로 링을 하나씩 잡고, 가볍게 점프해 팔을 완전히 편 시작 자세를 만든다.","팔꿈치를 굽혀 팔이 90도 아래로 내려갈 때까지 몸을 내린다. 몸이 흔들리지 않게 하고 내려가는 내내 좋은 자세를 유지한다.","팔꿈치를 펴며 동작을 되돌려 시작 자세로 몸을 밀어 올린다.","원하는 반복 횟수만큼 반복한다."], en: ["Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position.","Repeat for the desired number of repetitions."] },
  "랜드마인 로우": { k: ["바벨 한쪽 끝을 랜드마인 거치대(또는 코너)에 고정하고, 반대쪽 끝에 플레이트를 끼운다. 바를 다리 사이에 두고 서서 힙 힌지로 상체를 숙인 뒤, V-핸들을 바 아래에 걸거나 양손으로 바 끝을 잡는다. 등은 곧게 편다. 이것이 시작 자세다.","숨을 내쉬며 팔꿈치를 몸 뒤쪽으로 당겨 바 끝을 배꼽 방향으로 끌어올린다. 동작 맨 위에서 견갑골을 모아 등을 1초간 수축시킨다.","숨을 들이마시며 팔이 펴질 때까지 바를 천천히 내려 시작 자세로 돌아온다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 무게가 무거워지면 상체가 일어나며 로우가 아니라 슈러그처럼 변하기 쉽다. 힙 힌지 각도를 동작 내내 고정하고, 팔이 아닌 등으로 당기는 데 집중한다."], en: ["Anchor one end of a barbell in a landmine attachment (or a corner) and load plates on the other end. Straddle the bar, hinge at the hips to lean your torso forward, and hook a V-handle under the bar or grip the end with both hands. Keep your back flat. This is your starting position.","Breathe out and drive your elbows back to pull the end of the bar toward your belly button. Squeeze your shoulder blades together for a second at the top.","Breathe in and slowly lower the bar until your arms are extended, returning to the starting position.","Repeat for the prescribed amount of repetitions.","Tip: As the weight gets heavy, the torso tends to rise and the row turns into a shrug. Keep your hip hinge angle fixed throughout and focus on pulling with your back, not your arms."] },
  "메도우스 로우": { k: ["바벨 한쪽 끝을 랜드마인 거치대(또는 코너)에 고정하고 반대쪽 끝에 플레이트를 끼운다. 바의 슬리브 옆에 옆으로 서서 스태거드 스탠스(바 쪽 다리를 뒤로)를 취하고, 힙 힌지로 상체를 숙여 바 끝(슬리브)을 오버핸드 그립으로 잡는다. 반대쪽 팔꿈치는 앞쪽 허벅지에 얹어 지지한다. 이것이 시작 자세다.","숨을 내쉬며 팔꿈치를 바깥 뒤쪽으로 당겨 슬리브를 골반 옆까지 끌어올린다. 동작 맨 위에서 견갑골을 뒤로 조여 광배근과 등 상부를 1초간 수축시킨다.","숨을 들이마시며 광배근이 충분히 늘어날 때까지 바를 천천히 내린다.","정해진 반복 횟수를 마친 뒤 반대쪽도 같은 방식으로 수행한다.","팁: 슬리브는 두꺼워 그립이 먼저 풀리기 쉽다. 스트랩을 활용하면 등이 지칠 때까지 당길 수 있고, 몸통 회전으로 반동을 만들지 않도록 상체 각도를 고정한다."], en: ["Anchor one end of a barbell in a landmine attachment (or a corner) and load the other end. Stand sideways next to the sleeve in a staggered stance (leg closest to the bar back), hinge at the hips, and grab the end of the sleeve with an overhand grip. Rest your free elbow on your front thigh for support. This is your starting position.","Breathe out and drive your elbow out and back to pull the sleeve up toward your hip. Squeeze your shoulder blade back for a second at the top, contracting your lat and upper back.","Breathe in and slowly lower the bar until you feel a full stretch in your lat.","Complete the prescribed reps, then perform the same on the other side.","Tip: The thick sleeve tends to exhaust your grip first. Use lifting straps so your back can work to fatigue, and keep your torso angle fixed to avoid generating momentum by rotating."] },
  "씰 로우": { k: ["높게 세팅한 벤치(씰 로우 벤치 또는 박스 위에 올린 플랫 벤치)에 가슴을 대고 엎드린다. 팔을 아래로 뻗어 바벨을 오버핸드 그립으로 어깨너비 정도로 잡는다. 이마나 턱을 살짝 들고 몸 전체를 벤치에 밀착한다. 이것이 시작 자세다.","숨을 내쉬며 팔꿈치를 위로 당겨 바가 벤치 밑면(가슴 아래)에 닿을 때까지 끌어올린다. 동작 맨 위에서 견갑골을 모아 등을 1초간 강하게 수축시킨다.","숨을 들이마시며 팔이 완전히 펴지고 견갑골이 벌어질 때까지 바를 천천히 내린다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 가슴이 벤치에서 뜨는 순간 반동이 개입된다. 이 운동의 목적은 치팅을 완전히 제거하는 것이므로, 가슴을 벤치에 붙인 채로만 당길 수 있는 무게를 선택한다."], en: ["Lie chest-down on an elevated bench (a seal row bench or a flat bench raised on boxes). Reach your arms straight down and grab a barbell with an overhand grip about shoulder width. Keep your whole body pressed into the bench. This is your starting position.","Breathe out and drive your elbows up, pulling the bar until it touches the underside of the bench beneath your chest. Squeeze your shoulder blades together hard for a second at the top.","Breathe in and slowly lower the bar until your arms are fully extended and your shoulder blades spread apart.","Repeat for the prescribed amount of repetitions.","Tip: The moment your chest lifts off the bench, momentum takes over. The point of this exercise is to remove cheating entirely, so choose a weight you can row while keeping your chest glued to the bench."] },
  "고릴라 로우": { k: ["케틀벨 두 개를 양발 사이 바닥에 놓고, 발을 어깨너비보다 약간 넓게 벌리고 선다. 힙 힌지로 상체를 깊게 숙여 양손으로 케틀벨 핸들을 잡는다. 등은 곧게 펴고 시선은 바닥 약간 앞을 본다. 이것이 시작 자세다.","한쪽 케틀벨로 몸을 지지한 채, 숨을 내쉬며 반대쪽 케틀벨을 팔꿈치를 뒤로 당겨 골반 옆까지 끌어올린다. 동작 맨 위에서 견갑골을 조여 등을 1초간 수축시킨다.","숨을 들이마시며 케틀벨을 천천히 바닥에 내려놓고, 곧바로 반대쪽 팔로 같은 동작을 수행한다.","좌우를 번갈아 가며 정해진 반복 횟수만큼 동작을 반복한다.","팁: 당기는 쪽 어깨를 따라 몸통이 크게 회전하면 등 자극이 새어 나간다. 지지하는 팔로 바닥을 단단히 눌러 상체를 고정하고, 등 전체가 지면과 거의 평행한 각도를 유지한다."], en: ["Place two kettlebells on the floor between your feet and stand slightly wider than shoulder width. Hinge deep at the hips and grab both kettlebell handles. Keep your back flat and eyes slightly ahead on the floor. This is your starting position.","Supporting yourself on one kettlebell, breathe out and row the other kettlebell up to your hip by driving the elbow back. Squeeze your shoulder blade for a second at the top.","Breathe in and slowly lower the kettlebell back to the floor, then immediately row with the opposite arm.","Alternate sides and repeat for the prescribed amount of repetitions.","Tip: If your torso rotates excessively with the rowing shoulder, tension leaks out of your back. Press the supporting arm firmly into the kettlebell to lock your torso, keeping your back nearly parallel to the floor."] },
  "레니게이드 로우": { s: "Alternating_Renegade_Row/0.jpg", e: "Alternating_Renegade_Row/1.jpg", k: ["케틀벨 두 개를 어깨너비 정도로 바닥에 놓는다. 푸시업을 하듯 발끝과 손으로 몸을 지지하고 몸은 곧게 편다. 케틀벨의 핸들을 잡아 상체를 지지한다. 안정성을 위해 발을 넓게 벌려야 할 수 있다.","한쪽 케틀벨을 바닥으로 눌러 지지하면서 반대쪽 케틀벨을 로우한다. 당기는 쪽 견갑골을 뒤로 당기며 팔꿈치를 굽혀 케틀벨을 옆구리까지 끌어올린다.","케틀벨을 바닥에 내려놓고 반대쪽 손으로 같은 동작을 시작한다. 여러 회 반복한다."], en: ["Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.","Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.","Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps."] },
  "풀오버 머신": { k: ["머신 시트 높이를 어깨 관절이 머신 회전축과 일치하도록 조절하고 앉는다. 등을 패드에 붙이고 안전벨트가 있다면 고정한 뒤, 머리 위의 바 또는 패드에 팔꿈치나 손을 얹는다. 이것이 시작 자세다.","숨을 내쉬며 광배근으로 바를 큰 호를 그리듯 아래로 당겨 복부 앞까지 끌어내린다. 팔꿈치를 편 각도로 유지하고 팔이 아닌 등이 당긴다는 느낌에 집중한다.","동작 맨 아래에서 광배근을 1초간 강하게 수축시킨다.","숨을 들이마시며 광배근이 충분히 늘어날 때까지 바를 천천히 머리 위 시작 자세로 되돌린다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 어깨가 으쓱 올라간 채 당기면 등 대신 팔과 승모근이 개입한다. 동작 내내 견갑골을 아래로 끌어내린 상태를 유지하면 광배근 전체를 넓게 자극할 수 있다."], en: ["Adjust the seat so your shoulder joint lines up with the machine's pivot point and sit down. Press your back into the pad, secure the belt if provided, and place your hands or elbows on the overhead bar or pads. This is your starting position.","Breathe out and pull the bar down in a wide arc using your lats until it reaches the front of your abdomen. Keep your elbow angle fixed and focus on your back doing the pulling, not your arms.","Squeeze your lats hard for a second at the bottom of the movement.","Breathe in and slowly return the bar overhead to the starting position until you feel a full stretch in your lats.","Repeat for the prescribed amount of repetitions.","Tip: Pulling with shrugged shoulders shifts the work to your arms and traps. Keep your shoulder blades pulled down throughout to stimulate the entire lat."] },
  "네거티브 풀업": { k: ["박스나 벤치를 밟고 올라가(또는 점프하여) 턱이 바 위에 오는 풀업 최상단 자세에서 시작한다. 오버핸드 그립으로 바를 잡고 견갑골을 아래로 끌어내려 어깨를 고정한다. 팁: 처음에는 반드시 박스를 사용해 낮은 높이에서 안전하게 시작 자세를 잡는다.","숨을 들이마시며 팔이 완전히 펴질 때까지 3~5초에 걸쳐 몸을 최대한 천천히 내린다. 내려가는 내내 등과 팔에 힘을 유지하며 낙하 속도를 통제한다.","맨 아래에서 어깨가 귀 쪽으로 완전히 딸려 올라가기 전에 발을 박스에 딛고 내려온다.","다시 박스를 밟고 최상단 자세로 올라가 정해진 반복 횟수만큼 동작을 반복한다.","팁: 내리는 시간을 통제하지 못하고 뚝 떨어지는 것이 가장 흔한 실수다. 통제가 어려우면 내리는 구간을 짧게 나누어 연습하고, 팔꿈치나 어깨에 무리가 느껴지면 밴드 보조 풀업으로 단계를 낮춘다."], en: ["Step on a box or bench (or jump) to start at the top of a pull-up with your chin over the bar. Use an overhand grip and pull your shoulder blades down to set your shoulders. Tip: Always use a box at first so you can get into the top position safely from a low height.","Breathe in and lower yourself as slowly as possible over 3 to 5 seconds until your arms are fully extended. Keep tension in your back and arms the entire way down to control the descent.","At the bottom, step back onto the box before your shoulders get pulled all the way up toward your ears.","Climb back to the top position and repeat for the prescribed amount of repetitions.","Tip: The most common mistake is dropping instead of controlling the descent. If control is difficult, practice shorter segments of the lowering phase, and if your elbows or shoulders feel strained, regress to band-assisted pull-ups."] },
  "스캐퓰러 풀업": { s: "Scapular_Pull-Up/0.jpg", e: "Scapular_Pull-Up/1.jpg", k: ["풀업 바를 오버핸드 그립으로 잡는다.","매달린 자세에서 팔 힘을 쓰지 않고 몸을 몇 센티미터 들어 올린다. 어깨를 으쓱하는 동작을 거꾸로 하듯 견갑골을 아래로 끌어내려 수행한다.","동작 끝에서 잠깐 멈춘 뒤 천천히 시작 자세로 되돌아가 반복한다."], en: ["Take a pronated grip on a pull-up bar.","From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.","Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions."] },
  "키핑 풀업": { k: ["어깨너비보다 약간 넓은 오버핸드 그립으로 바에 매달린다. 팁: 키핑 풀업은 스트릭트 풀업을 최소 수 회 이상 할 수 있는 어깨 힘이 갖춰진 뒤에 시도해야 하며, 처음에는 코치나 보조자의 지도 아래 스윙 동작부터 단계적으로 익힌다.","가슴을 바 앞으로 내미는 아치 자세와 발을 앞으로 보내는 할로우 자세를 번갈아 만들며 몸 전체로 리드미컬한 스윙(키핑)을 만든다. 어깨로 스윙을 주도하고 코어로 몸을 팽팽하게 유지한다.","몸이 할로우에서 뒤로 넘어가는 타이밍에 숨을 내쉬며 엉덩이를 살짝 접었다 펴는 힘과 당기는 힘을 합쳐 턱을 바 위로 끌어올린다.","턱이 바를 넘으면 몸을 살짝 밀어내듯 내려오면서 다음 스윙으로 자연스럽게 연결한다. 내려오는 동안 숨을 들이마신다.","리듬이 끊기지 않게 정해진 반복 횟수만큼 동작을 반복한다.","팁: 스윙 리듬이 무너진 채 반복을 이어가면 어깨에 부담이 쌓인다. 리듬이 깨지면 즉시 멈추고 스윙부터 다시 시작하며, 그립이 풀리기 전에 세트를 마친다."], en: ["Hang from the bar with an overhand grip slightly wider than shoulder width. Tip: Attempt kipping pull-ups only after you can perform at least several strict pull-ups, and learn the swing progressively under a coach's or spotter's guidance at first.","Create a rhythmic swing (kip) by alternating between an arch position (chest pushed forward past the bar) and a hollow position (feet forward). Drive the swing from your shoulders and keep your body tight with your core.","As your body swings back from the hollow position, breathe out and combine a quick hip drive with your pull to bring your chin over the bar.","Once your chin clears the bar, push yourself slightly away as you descend, flowing directly into the next swing. Breathe in on the way down.","Repeat for the prescribed amount of repetitions without breaking the rhythm.","Tip: Grinding out reps after the swing rhythm breaks down loads your shoulders. If the rhythm falls apart, stop immediately and restart the swing, and end the set before your grip fails."] },
  "스터넘 풀업": { s: "Gironda_Sternum_Chins/0.jpg", e: "Gironda_Sternum_Chins/1.jpg", k: ["어깨너비의 언더핸드 그립으로 풀업 바를 잡는다.","팔을 완전히 편 채 매달려 가슴을 내밀고 몸을 뒤로 기울인다. 팁: 동작 내내 뒤로 기울인 상태를 유지한다. 이것이 시작 자세다.","동작 내내 척추를 아치로 유지하고 머리를 바에서 최대한 멀리 뒤로 젖히면서 몸을 바 쪽으로 당기기 시작한다. 이 구간에서 숨을 내쉰다. 팁: 동작 상단에서는 고관절과 다리가 바닥과 45도 정도를 이룬다.","쇄골이 바를 지나 가슴 아래쪽(흉골)이 바에 닿을 때까지 계속 당긴다. 그 수축 상태를 1초간 유지한다. 팁: 이 구간을 마쳤을 때 머리는 바닥과 평행이 된다.","숨을 들이마시며 천천히 시작 자세로 돌아간다.","권장 반복 횟수만큼 반복한다."], en: ["Grasp the pull-up bar with a shoulder width underhand grip.","Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.","Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.","Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you've completed this portion of the movement; your head will be parallel to the floor.","Slowly start going back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."] },
  "머슬업": { s: "Muscle_Up/0.jpg", e: "Muscle_Up/1.jpg", k: ["손바닥 아랫부분이 링 위에 올라가는 폴스 그립으로 링을 잡는다. 팔꿈치를 구부리며 몸 옆으로 끌어내려 풀업을 시작한다.","풀업 최고 지점에 도달하면 어깨를 앞으로 말면서 링을 겨드랑이 쪽으로 당기고, 팔꿈치가 몸 뒤로 곧게 빠지도록 한다. 이렇게 하면 딥 구간으로 이어 갈 올바른 자세가 만들어진다.","통제력과 안정성을 유지하며 팔꿈치를 펴서 동작을 마무리한다.","바닥으로 내려올 때는 조심스럽게 내려온다."], en: ["Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.","As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.","Maintaining control and stability, extend through the elbow to complete the motion.","Use care when lowering yourself to the ground."] },
  "링 풀업": { k: ["어깨너비 정도로 걸린 링을 잡고 팔을 편 채 매달린다. 견갑골을 아래로 끌어내려 어깨를 고정하고 코어에 힘을 주어 몸의 흔들림을 억제한다. 이것이 시작 자세다.","숨을 내쉬며 팔꿈치를 아래로 당겨 몸을 끌어올린다. 당기는 동안 손목을 자연스럽게 회전시켜(내전 그립에서 뉴트럴 또는 언더핸드로) 턱이 링 높이를 넘게 한다.","최상단에서 등 근육을 1초간 강하게 수축시킨다.","숨을 들이마시며 팔이 완전히 펴지고 광배근이 늘어날 때까지 몸을 천천히 내린다. 링의 흔들림을 통제하며 내려간다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 링은 바와 달리 손목이 자유롭게 돌아가는 것이 장점이다. 억지로 그립을 고정하지 말고 당기는 궤적에 맞춰 손목이 자연히 회전하게 두면 팔꿈치와 어깨의 부담이 줄어든다."], en: ["Grab rings set about shoulder width apart and hang with your arms extended. Pull your shoulder blades down to set your shoulders and brace your core to minimize swinging. This is your starting position.","Breathe out and pull your elbows down to lift your body. Let your wrists rotate naturally as you pull (from pronated toward neutral or underhand) until your chin clears ring height.","Squeeze your back muscles hard for a second at the top.","Breathe in and slowly lower yourself until your arms are fully extended and your lats are stretched, controlling the sway of the rings on the way down.","Repeat for the prescribed amount of repetitions.","Tip: Unlike a fixed bar, rings let your wrists rotate freely—that is their advantage. Do not force a fixed grip; letting your wrists turn naturally along the pulling path reduces stress on your elbows and shoulders."] },
  "데드 행": { k: ["박스나 벤치를 밟고 어깨너비보다 약간 넓은 오버핸드 그립으로 바를 잡은 뒤, 발을 떼고 팔을 편 채 매달린다. 팁: 처음에는 발이 바닥에 닿을 듯한 낮은 바나 박스를 활용해 10~20초의 짧은 시간부터 점진적으로 늘린다.","견갑골을 살짝 아래로 끌어내려 어깨가 귀에 완전히 딸려 올라가지 않게 하고, 코어에 가볍게 힘을 주어 몸의 흔들림을 억제한다.","호흡을 참지 말고 자연스럽게 이어가며 정해진 시간 동안 자세를 유지한다. 어깨·광배근·전완이 늘어나는 느낌에 집중한다.","시간이 다 되면 박스를 딛거나 무릎을 살짝 굽혀 부드럽게 착지한다.","팁: 그립이 풀리기 직전까지 억지로 버티다 뛰어내리면 착지 충격이 크다. 여유가 조금 남았을 때 내려오고, 그립력이 부족하면 스트랩 없이 시간을 짧게 여러 세트로 나눈다."], en: ["Step on a box or bench, grab the bar with an overhand grip slightly wider than shoulder width, then lift your feet and hang with your arms extended. Tip: Start with a low bar or box where your feet can nearly touch the floor, beginning with short 10-20 second holds and building up progressively.","Pull your shoulder blades slightly down so your shoulders do not ride all the way up to your ears, and lightly brace your core to minimize swinging.","Do not hold your breath—breathe naturally and hold the position for the prescribed time. Focus on the stretch through your shoulders, lats, and forearms.","When time is up, step back onto the box or land softly with slightly bent knees.","Tip: Grinding until your grip fails and then dropping creates a hard landing. Come down while you still have some grip left, and if grip strength is the limit, split the hold into shorter sets rather than using straps."] },
  "백 익스텐션 머신": { k: ["머신 시트와 등 패드를 조절해 골반 상단이 회전축과 일치하도록 맞추고 앉는다. 발을 발판에 고정하고 안전벨트가 있으면 채운 뒤, 등 상부를 패드에 대고 가슴 앞에서 팔을 교차하거나 손잡이를 잡는다. 이것이 시작 자세다.","숨을 내쉬며 척추기립근의 힘으로 패드를 뒤로 밀어 상체를 천천히 편다. 반동 없이 부드럽게 가동 범위 끝까지 편다.","완전히 편 지점에서 허리 근육을 1초간 수축시킨다.","숨을 들이마시며 저항을 통제하면서 상체를 천천히 시작 자세로 되돌린다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 무게를 늘리려고 상체를 뒤로 휙 젖히면 자극이 새고 허리에 부담이 간다. 가동 범위 전체를 천천히 통제할 수 있는 무게로 척추기립근을 단련하는 데 집중한다."], en: ["Adjust the seat and back pad so the top of your pelvis lines up with the machine's pivot point, then sit down. Secure your feet on the platform, fasten the belt if provided, place your upper back against the pad, and cross your arms over your chest or hold the handles. This is your starting position.","Breathe out and press the pad back using your spinal erectors, slowly extending your torso. Move smoothly through the full range without momentum.","Squeeze your lower back muscles for a second at full extension.","Breathe in and slowly return your torso to the starting position while controlling the resistance.","Repeat for the prescribed amount of repetitions.","Tip: Whipping your torso back to move more weight leaks tension and stresses the lower back. Choose a weight you can control slowly through the entire range and focus on working the spinal erectors."] },
  "슈퍼맨": { s: "Superman/0.jpg", e: "Superman/1.jpg", k: ["바닥이나 운동 매트에 엎드려 몸을 곧게 편다. 팔은 앞으로 완전히 뻗는다. 이것이 시작 자세다.","팔, 다리, 가슴을 동시에 바닥에서 들어 올리고 이 수축 상태를 2초간 유지한다. 팁: 허리 근육을 쥐어짜듯 수축시켜야 최상의 효과를 얻을 수 있다. 이 동작 중에는 숨을 내쉬는 것을 잊지 않는다. 참고: 수축 자세를 유지할 때 하늘을 나는 슈퍼맨 같은 모습이 되어야 한다.","숨을 들이마시며 팔, 다리, 가슴을 천천히 시작 자세로 내린다.","프로그램에 정해진 반복 횟수만큼 반복한다."], en: ["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."] },
  "파이크 푸시업": { k: ["푸시업 자세에서 손을 어깨너비로 짚은 채 엉덩이를 높이 들어 몸이 거꾸로 된 V자가 되게 한다. 다리는 곧게 펴고 시선은 발 쪽을 향한다. 이것이 시작 자세다.","숨을 들이마시며 팔꿈치를 굽혀 정수리가 바닥에 가까워질 때까지 몸을 천천히 내린다. 팔꿈치는 옆으로 완전히 벌어지지 않게 약 45도 방향을 유지한다.","숨을 내쉬며 어깨 힘으로 바닥을 밀어 시작 자세로 돌아온다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 엉덩이 각도가 낮아지면 가슴 푸시업에 가까워진다. 동작 내내 엉덩이를 최대한 높게 유지해 부하가 어깨에 실리게 하고, 난이도를 높이려면 발을 박스 위에 올린다."], en: ["From a push-up position with hands at shoulder width, lift your hips high so your body forms an inverted V. Keep your legs straight and look back toward your feet. This is your starting position.","Breathe in and bend your elbows to slowly lower yourself until the top of your head is close to the floor. Keep your elbows at about 45 degrees rather than flaring them fully out.","Breathe out and press through your shoulders to push back up to the starting position.","Repeat for the prescribed amount of repetitions.","Tip: If your hip angle drops, the movement becomes more like a chest push-up. Keep your hips as high as possible so the load stays on your shoulders, and elevate your feet on a box to increase the difficulty."] },
  "핸드스탠드 푸시업": { s: "Handstand_Push-Ups/0.jpg", e: "Handstand_Push-Ups/1.jpg", k: ["벽을 등지고 허리를 굽혀 두 손을 어깨너비로 바닥에 짚는다.","팔을 편 채 다리를 차 올려 벽에 기댄다. 몸이 거꾸로 선 상태에서 팔과 다리를 완전히 펴고, 몸 전체를 최대한 곧게 유지한다. 팁: 처음이라면 보조자의 도움을 받는다. 또한 시선을 아래로 떨구지 말고 머리가 벽 쪽을 향하게 유지한다.","숨을 들이마시며 머리가 바닥에 거의 닿을 때까지 천천히 몸을 내린다. 팁: 머리 부상을 막으려면 반드시 천천히 내려오는 것이 무엇보다 중요하다.","숨을 내쉬며 팔꿈치가 거의 펴질 때까지 천천히 몸을 밀어 올린다.","권장 반복 횟수만큼 반복한다."], en: ["With your back to the wall bend at the waist and place both hands on the floor at shoulder width.","Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.","Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.","Push yourself back up slowly as you exhale until your elbows are nearly locked.","Repeat for the recommended amount of repetitions."] },
  "핸드스탠드 홀드": { k: ["벽 근처에 장애물이 없는 안전한 공간을 확보한다. 처음에는 벽에 발을 대고 지지하는 월 핸드스탠드부터 점진적으로 익히는 것이 안전하다.","양손을 어깨너비로 바닥에 짚고 손가락을 넓게 펴 바닥을 움켜쥔다. 한 다리씩 차올리거나 벽을 타고 올라가 몸을 수직으로 세운다.","팔꿈치를 완전히 펴고 어깨로 바닥을 밀어내듯 견갑골을 위로 올린다. 코어와 둔근에 힘을 주어 몸통·엉덩이·다리가 일직선이 되게 한다.","호흡을 멈추지 말고 짧고 일정하게 유지하며 정해진 시간 동안 자세를 유지한다.","내려올 때는 한 다리씩 천천히 내리거나 옆으로 돌아 나와 안전하게 착지한다.","팁: 허리가 꺾여 몸이 바나나처럼 휘는 것이 가장 흔한 실수다. 갈비뼈를 닫고 골반을 살짝 말아 몸을 일직선으로 유지한다."], en: ["Set up in a clear, safe space near a wall. Start with wall-supported handstands and progress gradually before attempting a freestanding hold.","Place your hands on the floor at shoulder width, spreading your fingers and gripping the ground. Kick up one leg at a time or walk your feet up the wall until your body is vertical.","Lock your elbows and push the floor away, elevating your shoulder blades. Brace your core and squeeze your glutes so your torso, hips, and legs form one straight line.","Do not hold your breath; keep breathing in short, steady breaths as you hold the position for the prescribed time.","To come down, lower one leg at a time or pivot out to the side and land safely.","Tip: The most common mistake is a banana-shaped arch in the lower back. Tuck your ribs and slightly tilt your pelvis to keep the body in one straight line."] },
  "푸시 프레스": { s: "Push_Press/0.jpg", e: "Push_Press/1.jpg", k: ["바벨을 랙에서 빼내 쇄골과 앞어깨 위에 얹는다(프론트 랙). 팔꿈치를 살짝 앞으로 들고, 발은 어깨너비로 서서 코어에 힘을 준다. 이것이 시작 자세다.","상체를 곧게 세운 채 무릎과 고관절을 살짝 굽혀 빠르게 반동 자세(딥)를 만든다. 팁: 내려가는 깊이는 쿼터 스쿼트 정도면 충분하다 — 깊이가 아니라 속도가 핵심이다.","숨을 내쉬며 다리로 바닥을 강하게 밀고, 그 추진력으로 바를 머리 위로 밀어 올려 팔꿈치를 완전히 편다. 바가 얼굴을 지날 때 머리를 살짝 뒤로 뺀다.","머리 위에서 잠깐 멈춘 뒤 통제하며 바를 어깨 위 시작 자세로 내린다. 정해진 반복 횟수만큼 반복한다."], en: ["Unrack the barbell into a front rack position across your collarbone and front delts, elbows slightly forward. Stand with feet shoulder-width apart and brace your core. This will be your starting position.","Keeping your torso upright, quickly dip by bending the knees and hips slightly. Tip: a quarter-squat depth is enough — the dip is about speed, not depth.","Breathe out and drive hard through the floor with your legs, using that momentum to press the bar overhead until your elbows are fully locked out. Move your head slightly back as the bar passes your face.","Pause briefly overhead, then lower the bar under control back to your shoulders. Repeat for the prescribed number of repetitions."] },
  "밴드 풀 어파트": { s: "Band_Pull_Apart/0.jpg", e: "Band_Pull_Apart/1.jpg", k: ["양손으로 밴드를 잡고 팔을 몸 정면으로 곧게 뻗은 자세로 시작한다.","리버스 플라이 동작처럼 양손을 옆으로 벌리며 동작을 시작한다.","동작 내내 팔꿈치를 편 상태를 유지하며 밴드를 가슴까지 가져온다. 운동 중에는 어깨를 뒤로 젖힌 상태를 유지한다.","동작 끝에서 잠깐 멈춘 뒤 통제하며 시작 자세로 되돌아간다."], en: ["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."] },
  "케이블 Y 레이즈": { k: ["케이블 풀리 두 개를 가장 낮은 위치로 내리고, 양손으로 반대쪽 케이블을 교차해서 잡는다(오른손에 왼쪽 케이블, 왼손에 오른쪽 케이블). 머신을 마주 보고 한두 걸음 물러나 팔을 아래로 뻗고 가슴을 편다. 이것이 시작 자세다.","숨을 내쉬며 팔꿈치를 거의 편 채 양팔을 대각선 위로 들어 올려 몸이 Y자가 되게 한다. 엄지가 위를 향하는 방향으로 올리며 어깨 높이보다 살짝 위까지 올린다.","최상단에서 어깨와 등 상부를 1초간 수축시킨다.","숨을 들이마시며 저항을 통제하면서 팔을 천천히 시작 자세로 내린다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 무게가 무거우면 승모근이 으쓱 올라가며 개입한다. 어깨를 내린 상태를 유지할 수 있는 가벼운 무게로 측면·후면 어깨와 하부 승모근을 정확히 자극하는 데 집중한다."], en: ["Set two cable pulleys to the lowest position and grab the opposite cables with crossed arms (left cable in right hand, right cable in left hand). Face the machine, step back a pace or two, and stand with arms extended down and chest up. This is your starting position.","Breathe out and raise both arms diagonally upward with nearly straight elbows so your body forms a Y shape. Lead with your thumbs pointing up and lift slightly above shoulder height.","Squeeze your shoulders and upper back for a second at the top.","Breathe in and slowly lower your arms back to the starting position while controlling the resistance.","Repeat for the prescribed amount of repetitions.","Tip: With too much weight, your traps shrug up and take over. Use a light weight that lets you keep your shoulders down, focusing on precisely stimulating the lateral and rear delts and lower traps."] },
  "체스트 서포티드 Y 레이즈": { k: ["인클라인 벤치를 30~45도로 세팅하고 가슴을 패드에 대고 엎드린다. 양손에 가벼운 덤벨을 들고 팔을 바닥 쪽으로 자연스럽게 늘어뜨린다. 이것이 시작 자세다.","숨을 내쉬며 팔을 Y자 모양(대각선 위 방향)으로 들어 올린다. 엄지가 위를 향하게 하고, 견갑골을 아래로 모아 내리는 느낌으로 하부 승모근과 어깨를 자극한다.","팔이 머리와 일직선에 가까워지면 1초간 멈춰 수축을 느낀다.","숨을 들이마시며 천천히 시작 자세로 내린다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 무게가 무거우면 반동을 쓰게 되어 승모근 상부만 개입한다. 가벼운 무게로 견갑골의 움직임에 집중한다."], en: ["Set an incline bench to 30-45 degrees and lie chest-down against the pad. Hold a light dumbbell in each hand with your arms hanging straight down. This will be your starting position.","As you breathe out, raise your arms up and out into a Y shape. Keep your thumbs pointing up and think of drawing your shoulder blades down and together to work the lower traps and shoulders.","When your arms are nearly in line with your head, pause for a second and feel the contraction.","Breathe in as you slowly lower back to the starting position.","Repeat the movement for the prescribed amount of repetitions.","Tip: Going too heavy forces momentum and shifts the work to the upper traps. Use light weights and focus on the movement of the shoulder blades."] },
  "오버헤드 플레이트 레이즈": { k: ["발을 어깨너비로 벌리고 서서 플레이트를 양손으로 3시-9시 방향으로 잡아 허벅지 앞에 둔다. 가슴을 펴고 코어에 힘을 준다. 이것이 시작 자세다.","숨을 내쉬며 팔꿈치를 살짝 굽힌 각도로 고정한 채 플레이트를 머리 위까지 호를 그리듯 들어 올린다.","머리 위에서 1초간 멈추며 어깨를 수축시킨다.","숨을 들이마시며 같은 궤적으로 플레이트를 천천히 허벅지 앞 시작 자세까지 내린다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 플레이트가 올라갈 때 허리를 뒤로 젖혀 반동을 쓰는 것이 가장 흔한 실수다. 코어를 조여 상체를 수직으로 고정하고, 전면 어깨의 힘만으로 통제할 수 있는 무게를 선택한다."], en: ["Stand with your feet shoulder width apart, holding a plate with both hands at the 3 and 9 o'clock positions, resting in front of your thighs. Keep your chest up and core braced. This is your starting position.","Breathe out and raise the plate in an arc up over your head, keeping a slight, fixed bend in your elbows.","Pause for a second overhead and contract your shoulders.","Breathe in and slowly lower the plate along the same arc back to the starting position in front of your thighs.","Repeat for the prescribed amount of repetitions.","Tip: The most common mistake is leaning back to swing the plate up. Brace your core to keep your torso vertical, and choose a weight your front delts can control on their own."] },
  "숄더 탭": { k: ["푸시업 자세(하이 플랭크)를 취한다. 손은 어깨 바로 아래에 두고, 머리부터 발뒤꿈치까지 몸이 일직선이 되게 한다. 이것이 시작 자세다.","코어에 힘을 준 채 한 손을 바닥에서 떼어 반대쪽 어깨를 가볍게 터치한다. 이때 골반이 좌우로 흔들리지 않게 유지한다.","손을 제자리로 되돌리고 반대 손으로 같은 동작을 한다. 자연스럽게 호흡하며 좌우 교대로 정해진 횟수만큼 반복한다.","팁: 발을 어깨너비보다 조금 넓게 벌리면 지지 면적이 커져 골반 흔들림을 줄이기 쉽다."], en: ["Get into a push-up position (high plank) with your hands directly under your shoulders and your body in a straight line from head to heels. This is your starting position.","Bracing your core, lift one hand off the floor and lightly tap the opposite shoulder. Keep your hips from rocking side to side.","Return the hand to the floor and repeat with the other hand. Breathe naturally and alternate sides for the prescribed number of repetitions.","Tip: Setting your feet slightly wider than shoulder width creates a bigger base and makes it easier to keep your hips still."] },
  "케틀벨 헤일로": { k: ["케틀벨을 거꾸로 뒤집어 양손으로 뿔(손잡이 양옆)을 잡고 얼굴 높이 가슴 앞에 든다. 어깨너비로 서서 코어에 힘을 준다. 이것이 시작 자세다.","케틀벨을 머리 주위로 천천히 원을 그리듯 돌린다. 한쪽 귀 옆을 지나 뒤통수 뒤로, 다시 반대쪽 귀 옆을 지나 시작 위치로 돌아온다. 케틀벨은 머리에 가깝게 붙여 움직인다.","자연스럽게 호흡하며 정해진 횟수만큼 돌린 뒤, 반대 방향으로도 같은 횟수를 반복한다.","팁: 케틀벨을 따라 몸통이 함께 흔들리기 쉽다. 갈비뼈를 내리고 코어를 조여 몸통은 고정한 채 팔과 어깨만 움직인다."], en: ["Hold a kettlebell upside down by the horns at chest height in front of your face. Stand shoulder-width apart and brace your core. This is your starting position.","Slowly circle the kettlebell around your head — past one ear, behind the back of your head, past the other ear, and back to the start. Keep the bell close to your head throughout.","Breathe naturally and complete the prescribed reps, then repeat in the opposite direction.","Tip: It's easy for your torso to sway with the bell. Keep your ribs down and core braced so only your arms and shoulders move."] },
  "드래그 컬": { s: "Drag_Curl/0.jpg", e: "Drag_Curl/1.jpg", k: ["언더핸드 그립(손바닥이 앞을 향함)으로 바벨을 잡고 팔꿈치를 상체 가까이 뒤쪽에 둔다. 이것이 시작 자세다.","숨을 내쉬며 팔꿈치를 뒤로 유지한 채, 바가 상체에 닿은 상태를 유지하며 끌어올리듯(드래그) 컬을 한다. 팁: 팔꿈치를 몸 옆에 고정하는 것이 아니라 뒤로 빼는 것이 포인트다. 또한 어깨가 들리지 않도록 한다.","바가 상체에 계속 닿아 있는 상태를 유지하며 천천히 시작 자세로 되돌아간다.","정해진 반복 횟수만큼 반복한다."], en: ["Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.","As you exhale, curl the bar up while keeping the elbows to the back as you \"Drag\" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.","Slowly go back to the starting position as you keep the bar in contact with the torso at all times.","Repeat for the recommended amount of repetitions."] },
  "조트맨 컬": { s: "Zottman_Curl/0.jpg", e: "Zottman_Curl/1.jpg", k: ["상체를 곧게 세우고 서서 양손에 덤벨을 들고 팔을 늘어뜨린다. 팔꿈치는 상체 가까이에 둔다.","손바닥이 서로 마주 보게 한다. 이것이 시작 자세다.","위팔을 고정한 채 숨을 내쉬며 이두근을 수축시켜 덤벨을 컬한다. 아래팔만 움직여야 한다. 손목을 돌려 손바닥이 위를 향하는 언더핸드 그립이 되게 한다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 동작을 이어 간다.","이두근을 쥐어짜듯 수축시키며 수축 자세를 1초간 유지한다.","수축 자세에서 손목을 돌려 엄지가 새끼손가락보다 높이 오는 오버핸드 그립(손바닥이 아래를 향함)으로 바꾼다.","오버핸드 그립을 유지한 채 천천히 덤벨을 내리기 시작한다.","덤벨이 허벅지에 가까워지면 손목을 돌려 손바닥이 몸을 향하는 중립 그립으로 되돌린다.","정해진 반복 횟수만큼 반복한다."], en: ["Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","Make sure the palms of the hands are facing each other. This will be your starting position.","While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a second as you squeeze the biceps.","Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.","Slowly begin to bring the dumbbells back down using the pronated grip.","As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.","Repeat for the recommended amount of repetitions."] },
  "크로스 바디 해머 컬": { s: "Cross_Body_Hammer_Curl/0.jpg", e: "Cross_Body_Hammer_Curl/1.jpg", k: ["양손에 덤벨을 들고 곧게 선다. 손은 몸 옆에 늘어뜨리고 손바닥은 몸 쪽을 향하게 한다.","손바닥이 몸 쪽을 향한 상태를 유지하고 팔을 비틀지 않은 채, 숨을 내쉬며 오른손 덤벨을 왼쪽 어깨를 향해 컬한다. 덤벨 윗부분을 어깨에 닿게 한 뒤 수축을 1초간 유지한다.","숨을 들이마시며 같은 궤적을 따라 천천히 덤벨을 내리고, 왼팔로 같은 동작을 반복한다.","양팔 각각 정해진 반복 횟수를 채울 때까지 번갈아 계속한다."], en: ["Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.","While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.","Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.","Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm."] },
  "웨이터 컬": { k: ["덤벨을 세워 위쪽 헤드를 양 손바닥으로 접시를 받치듯 아래에서 받쳐 든다. 팔을 편 채 곧게 선다. 이것이 시작 자세다.","팔꿈치를 몸통 옆에 고정한 채 숨을 내쉬며 덤벨을 어깨 높이까지 컬한다. 동작 내내 손바닥이 천장을 향하게 유지한다.","맨 위에서 이두근을 짜주듯 잠시 수축한 뒤, 숨을 들이마시며 천천히 시작 자세로 내린다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 팔꿈치가 앞으로 딸려 나오면 어깨가 개입한다. 팔꿈치를 옆구리에 붙인 채 이두근의 힘으로만 들어 올린다."], en: ["Hold a dumbbell vertically, cupping the top head from underneath with both palms as if carrying a tray. Stand tall with your arms extended. This is your starting position.","Keeping your elbows pinned to your sides, exhale and curl the dumbbell up to shoulder height. Keep your palms facing the ceiling throughout the movement.","Squeeze your biceps briefly at the top, then inhale and slowly lower back to the starting position.","Repeat for the prescribed number of repetitions.","Tip: If your elbows drift forward, your shoulders take over. Keep them locked at your sides so only your biceps do the lifting."] },
  "21 컬": { k: ["언더핸드 그립으로 어깨너비 정도 되게 바벨을 잡고 곧게 선다. 팔꿈치는 몸통 옆에 고정한다. 이것이 시작 자세다.","처음 7회는 하단 절반만 수행한다. 팔이 펴진 지점에서 전완이 바닥과 평행해지는 중간 지점까지만 올렸다가 내린다. 올릴 때 숨을 내쉬고 내릴 때 들이마신다.","다음 7회는 상단 절반만 수행한다. 중간 지점에서 바가 어깨 높이에 오는 맨 위까지 올렸다가 중간 지점까지만 내린다.","마지막 7회는 전체 가동범위로 컬한다. 총 21회가 한 세트다.","팁: 후반부에 반동을 쓰기 쉬운 종목이다. 평소 컬보다 가벼운 무게로 팔꿈치를 고정한 채 끝까지 통제한다."], en: ["Stand tall holding a barbell with an underhand grip about shoulder-width apart. Keep your elbows pinned to your sides. This is your starting position.","For the first 7 reps, perform only the bottom half: curl from full extension to the midpoint where your forearms are parallel to the floor, then lower. Exhale as you lift, inhale as you lower.","For the next 7 reps, perform only the top half: curl from the midpoint to the top with the bar at shoulder height, then lower back to the midpoint.","For the final 7 reps, curl through the full range of motion. All 21 reps make one set.","Tip: Momentum creeps in during the later reps. Use a lighter weight than your usual curl and keep your elbows fixed with full control to the end."] },
  "오버헤드 케이블 컬": { s: "Overhead_Cable_Curl/0.jpg", e: "Overhead_Cable_Curl/1.jpg", k: ["풀리 머신 양쪽에 무리가 없는 무게를 설정한다. 참고: 양쪽에 선택한 무게가 같은지 확인한다.","양쪽 풀리 높이를 조절해 어깨보다 높은 위치에 오도록 한다.","양쪽 가운데에 서서 언더핸드 그립(손바닥이 천장을 향함)으로 양쪽 손잡이를 잡는다. 팔은 완전히 뻗어 바닥과 평행이 되게 하고 발은 어깨너비로 벌린다. 몸이 양쪽 손잡이의 정중앙에 오도록 한다. 이것이 시작 자세다.","숨을 내쉬며 아래팔과 이두근이 닿을 때까지 양쪽 이두근을 천천히 쥐어짜듯 수축시킨다.","숨을 들이마시며 아래팔을 시작 자세로 되돌린다. 참고: 이 운동 중에는 아래팔을 제외한 온몸이 고정되어 있어야 한다.","프로그램에 정해진 반복 횟수만큼 반복한다."], en: ["To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.","Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.","Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.","While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.","While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.","Repeat for the recommended amount of repetitions prescribed in your program."] },
  "비하인드 백 케이블 컬": { k: ["케이블 머신의 낮은 도르래에 D-핸들을 연결하고, 머신을 등진 채 핸들을 잡은 손이 몸 뒤쪽으로 살짝 당겨질 때까지 한두 걸음 앞으로 나와 선다. 이것이 시작 자세다.","위팔을 고정한 채 숨을 내쉬며 핸들을 어깨 쪽으로 컬한다. 이두근이 늘어난 상태에서 시작하므로 수축을 끝까지 느끼며 올린다.","맨 위에서 이두근을 짜주듯 잠시 멈춘 뒤, 숨을 들이마시며 천천히 팔이 다시 뒤로 펴질 때까지 내린다.","정해진 횟수만큼 반복한 뒤 반대쪽 팔로 같은 동작을 수행한다.","팁: 케이블에 몸이 뒤로 끌려가지 않도록 반대쪽 발을 앞에 두는 스플릿 스탠스로 서면 자세가 안정된다."], en: ["Attach a D-handle to the low pulley of a cable machine. Facing away from the machine, step forward a pace or two until the handle pulls your arm slightly behind your body. This is your starting position.","Keeping your upper arm stationary, exhale and curl the handle toward your shoulder. The biceps starts from a stretched position, so focus on a full contraction as you lift.","Squeeze your biceps briefly at the top, then inhale and slowly lower until your arm extends back behind you.","Complete the prescribed reps, then repeat with the other arm.","Tip: Take a split stance with the opposite foot forward so the cable doesn't pull your body backward."] },
  "플레이트 컬": { k: ["원판의 양옆(3시·9시 방향)을 양손으로 잡고 팔을 아래로 늘어뜨린 채 곧게 선다. 이것이 시작 자세다.","팔꿈치를 몸통 옆에 고정한 채 숨을 내쉬며 원판을 가슴 높이까지 컬한다.","맨 위에서 이두근을 짜주듯 잠시 멈춘 뒤, 숨을 들이마시며 천천히 시작 자세로 내린다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 손목을 꺾어 들어 올리지 않는다. 손목은 곧게 유지하고 팔꿈치의 굽힘만으로 원판을 올린다."], en: ["Grip a weight plate at the 3 and 9 o'clock positions with both hands, arms hanging down, and stand tall. This is your starting position.","Keeping your elbows pinned to your sides, exhale and curl the plate up to chest height.","Squeeze your biceps briefly at the top, then inhale and slowly lower back to the starting position.","Repeat for the prescribed number of repetitions.","Tip: Don't flex your wrists to lift the plate. Keep them straight and raise the plate using only elbow flexion."] },
  "리버스 그립 푸시다운": { s: "Reverse_Grip_Triceps_Pushdown/0.jpg", e: "Reverse_Grip_Triceps_Pushdown/1.jpg", k: ["하이 풀리 머신에 바 어태치먼트(스트레이트 바 또는 EZ 바)를 연결하며 시작한다.","바 어태치먼트를 마주 보고 손바닥이 위를 향하는 언더핸드 그립으로 어깨너비로 잡는다. 광배근을 사용해 팔이 몸 옆에서 완전히 펴질 때까지 바를 내린다. 팁: 팔꿈치는 옆구리에 붙이고 발은 어깨너비로 벌린다. 이것이 시작 자세다.","숨을 들이마시며 바 어태치먼트를 가슴 높이까지 천천히 올린다. 아래팔만 움직여야 하며 팔꿈치와 위팔은 항상 몸 옆에 고정한다.","숨을 내쉬고 삼두근을 강하게 수축시키며 바를 원래 시작 자세로 다시 내린다.","권장 반복 횟수만큼 반복한다."], en: ["Start by setting a bar attachment (straight or e-z) on a high pulley machine.","Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.","Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.","Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.","Repeat for the recommended amount of repetitions."] },
  "트라이셉스 익스텐션 머신": { s: "Machine_Triceps_Extension/0.jpg", e: "Machine_Triceps_Extension/1.jpg", k: ["시트를 알맞은 높이로 조절하고 중량을 선택한다. 위팔을 패드에 붙이고 핸들을 잡는다. 이것이 시작 자세다.","팔꿈치를 펴서 아래팔을 위팔에서 멀어지게 밀며 동작을 수행한다.","동작이 끝나는 지점에서 잠깐 멈춘 뒤 천천히 중량을 시작 자세로 되돌린다.","타깃 근육의 긴장을 유지하기 위해, 세트가 끝날 때까지 중량이 스택에 완전히 닿지 않게 한다."], en: ["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.","Pause at the completion of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."] },
  "와이드 엘보 트라이셉스 프레스": { k: ["플랫 벤치에 누워 양손에 덤벨을 들고 가슴 위로 팔을 편다. 손바닥은 발쪽(오버핸드 그립)을 향하게 한다. 이것이 시작 자세다.","숨을 들이마시며 팔꿈치를 양옆으로 넓게 벌리면서 덤벨을 가슴 상부 옆까지 천천히 내린다.","숨을 내쉬며 삼두근의 힘으로 덤벨을 시작 자세까지 밀어 올린다. 맨 위에서 팔을 펴고 삼두근을 1초간 수축시킨다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 팔꿈치를 벌리는 만큼 어깨와 팔꿈치에 부담이 커질 수 있다. 가벼운 무게로 가동범위를 통제하며 수행한다."], en: ["Lie on a flat bench holding a dumbbell in each hand, arms extended over your chest with palms facing your feet (overhand grip). This is your starting position.","Inhale and slowly lower the dumbbells to the sides of your upper chest, letting your elbows flare out wide.","Exhale and press the dumbbells back to the starting position using your triceps. Lock out your arms and squeeze the triceps for a second at the top.","Repeat for the prescribed number of repetitions.","Tip: The wider elbow path can stress the shoulders and elbows. Use a light weight and control the range of motion."] },
  "리스트 롤러": { s: "Wrist_Roller/0.jpg", e: "Wrist_Roller/1.jpg", k: ["오버핸드 그립(손바닥이 아래를 향함)으로 리스트 롤러를 잡고 곧게 선다. 발은 어깨너비로 벌린다.","양팔을 천천히 들어 올려 몸 앞에서 완전히 뻗은 채 바닥과 평행이 되게 한다. 참고: 줄이 롤러에 감겨 있지 않은지 확인한다. 아래팔을 제외한 온몸은 고정되어 있어야 한다. 이것이 시작 자세다.","한 번에 한쪽 손목씩 위로 감아올리는 동작으로 줄을 롤러에 감아 무게를 바까지 끌어 올린다.","무게가 바에 닿으면 손목을 반대 방향으로 돌려 무게가 시작 위치에 도달할 때까지 천천히 내린다.","프로그램에 정해진 반복 횟수만큼 반복한다."], en: ["To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.","Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.","Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.","Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.","Repeat for the prescribed amount of repetitions in your program."] },
  "비하인드 백 리스트 컬": { s: "Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg", e: "Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/1.jpg", k: ["똑바로 선 자세에서 바벨을 엉덩이 뒤로 팔을 편 채 잡는다. 그립은 손바닥이 몸에서 멀어져 뒤쪽을 향하는 오버핸드 그립으로, 손 간격은 어깨너비로 한다.","시선은 정면을 향하고 발은 어깨너비로 벌린다. 이것이 시작 자세다.","숨을 내쉬며 손목을 천장 쪽으로 반원을 그리듯 말아 올려 바벨을 천천히 들어 올린다. 팁: 이 운동에서는 손목만 움직여야 한다.","수축 상태를 1초간 유지한 뒤 숨을 들이마시며 바벨을 시작 자세로 내린다.","정해진 반복 횟수만큼 동작을 반복한다.","끝나면 무릎을 굽혀 바벨을 스쿼트 랙이나 바닥에 내려놓는다. 팁: 바벨은 스쿼트 랙에서 집어 들거나 파트너에게 건네받는 것이 가장 수월하다."], en: ["Start by standing straight and holding a barbell behind your glutes at arm's length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.","You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.","While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.","Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you."] },
  "리버스 컬 (덤벨)": { s: "Standing_Dumbbell_Reverse_Curl/0.jpg", e: "Standing_Dumbbell_Reverse_Curl/1.jpg", k: ["양손에 덤벨을 하나씩 오버핸드 그립(손바닥이 아래를 향하게)으로 들고 똑바로 선다. 팔은 완전히 펴고 발은 어깨너비로 벌린다. 이것이 시작 자세다.","위팔을 고정한 채 숨을 내쉬며 이두근을 수축시켜 덤벨을 말아 올린다. 아래팔만 움직여야 한다. 이두근이 완전히 수축하고 덤벨이 어깨 높이에 올 때까지 동작을 이어간 뒤, 근육을 쥐어짜듯 수축 상태를 1초간 유지한다.","숨을 들이마시며 덤벨을 천천히 시작 자세로 내린다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."] },
  "리버스 컬 (케이블)": { s: "Reverse_Cable_Curl/0.jpg", e: "Reverse_Cable_Curl/1.jpg", k: ["로우 풀리에 연결한 바를 오버핸드 그립(손바닥이 아래를 향하게)으로 어깨너비로 잡고 상체를 곧게 세워 선다. 팔꿈치는 몸통 가까이 붙인다. 이것이 시작 자세다.","위팔을 고정한 채 숨을 내쉬며 이두근을 수축시켜 바를 말아 올린다. 아래팔만 움직여야 한다. 이두근이 완전히 수축하고 바가 어깨 높이에 올 때까지 동작을 이어간 뒤, 근육을 쥐어짜듯 수축 상태를 1초간 유지한다.","숨을 들이마시며 바를 천천히 시작 자세로 내린다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."] },
  "슈러그 (머신)": { s: "Calf-Machine_Shoulder_Shrug/0.jpg", e: "Calf-Machine_Shoulder_Shrug/1.jpg", k: ["카프 머신에 들어가 어깨 패드가 어깨 위에 오도록 자리 잡는다. 상체는 곧게 세우고 팔은 자연스럽게 몸 옆으로 늘어뜨린다. 이것이 시작 자세다.","숨을 내쉬며 어깨를 귀 쪽으로 끌어올리고 수축 상태를 1초간 충분히 유지한다.","숨을 들이마시며 천천히 시작 자세로 돌아온다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.","Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.","Slowly return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."] },
  "점프 슈러그": { k: ["오버핸드 그립으로 어깨너비 정도 되게 바벨을 잡고, 힙 힌지로 엉덩이를 뒤로 빼 바를 허벅지 중간 높이에 둔다. 등은 곧게, 가슴은 들어 올린다. 이것이 시작 자세다.","숨을 내쉬며 고관절·무릎·발목을 폭발적으로 펴서 점프하듯 몸을 세우고, 동시에 어깨를 귀 쪽으로 강하게 슈러그한다.","부드럽게 착지하며 바를 허벅지를 따라 시작 자세로 되돌리고, 자세를 정돈한 뒤 다음 반복을 수행한다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 팔로 바를 당기지 않는다. 팔은 바를 잡는 끈 역할만 하고 힘은 하체의 폭발적인 신전에서 나와야 한다."], en: ["Grip a barbell with an overhand grip about shoulder-width apart. Hinge at the hips to bring the bar to mid-thigh, back flat and chest up. This is your starting position.","Exhale and explosively extend your hips, knees, and ankles as if jumping, shrugging your shoulders hard toward your ears at the same time.","Land softly, guide the bar back down your thighs to the starting position, and reset before the next rep.","Repeat for the prescribed number of repetitions.","Tip: Don't pull with your arms. They act only as straps holding the bar — the power should come from the explosive extension of your lower body."] },
  "라잉 넥 컬": { k: ["목은 부담이 가기 쉬운 부위이므로 처음에는 중량 없이 작은 가동범위로 천천히 시작해 점진적으로 범위와 횟수를 늘려 간다.","플랫 벤치에 등을 대고 누워 머리가 벤치 끝 밖으로 나오게 한다. 어깨는 벤치에 붙이고 몸은 안정시킨다. 이것이 시작 자세다.","숨을 내쉬며 턱을 가슴 쪽으로 당겨 목 앞쪽 근육의 힘으로 머리를 천천히 들어 올린다.","숨을 들이마시며 머리를 천천히 시작 자세로 되돌린다. 정해진 횟수만큼 반복한다.","팁: 반동을 쓰거나 급하게 움직이지 않는다. 처음부터 끝까지 느리고 부드러운 통제가 이 운동의 핵심이다."], en: ["The neck is easy to overload, so start with no weight and a small range of motion, progressing gradually in range and reps.","Lie on your back on a flat bench with your head hanging off the end. Keep your shoulders on the bench and your body stable. This is your starting position.","Exhale and slowly curl your head up, tucking your chin toward your chest using the muscles at the front of your neck.","Inhale and slowly return your head to the starting position. Repeat for the prescribed number of repetitions.","Tip: Never use momentum or jerky movements. Slow, smooth control from start to finish is the whole point of this exercise."] },
  "라잉 넥 익스텐션": { k: ["목은 부담이 가기 쉬운 부위이므로 처음에는 중량 없이 작은 가동범위로 천천히 시작해 점진적으로 범위와 횟수를 늘려 간다.","플랫 벤치에 엎드려 누워 머리가 벤치 끝 밖으로 나오게 한다. 가슴과 어깨는 벤치에 붙이고 몸은 안정시킨다. 이것이 시작 자세다.","숨을 내쉬며 목 뒤쪽 근육의 힘으로 머리를 천천히 뒤로 들어 올린다. 과도하게 젖히지 말고 목이 몸통과 일직선이 되는 지점까지만 올린다.","숨을 들이마시며 머리를 천천히 시작 자세로 내린다. 정해진 횟수만큼 반복한다.","팁: 가동범위 욕심을 내지 않는다. 끝 범위에서 억지로 젖히기보다 중간 범위를 느리게 통제하는 것이 목 뒤 근육을 단련하는 데 더 낫다."], en: ["The neck is easy to overload, so start with no weight and a small range of motion, progressing gradually in range and reps.","Lie face down on a flat bench with your head hanging off the end. Keep your chest and shoulders on the bench and your body stable. This is your starting position.","Exhale and slowly raise your head backward using the muscles at the back of your neck. Don't hyperextend — stop where your neck is in line with your torso.","Inhale and slowly lower your head back to the starting position. Repeat for the prescribed number of repetitions.","Tip: Don't chase range of motion. Slow control through the mid-range works the back of the neck better than forcing the end range."] },
  "박스 스쿼트": { s: "Box_Squat/0.jpg", e: "Box_Squat/1.jpg", k: ["박스 스쿼트는 원하는 깊이까지 스쿼트하면서 스쿼트 동작의 폭발적인 힘을 기를 수 있는 운동이다. 파워랙 안에서 뒤에 적절한 높이의 박스를 두고 시작한다. 보통은 허벅지가 바닥과 평행이 되는 깊이에 맞는 박스 높이를 기준으로 하되, 원하면 더 높거나 낮게 훈련할 수 있다.","바 아래로 들어가 바를 어깨 뒤쪽에 걸친다. 견갑골을 모으고 팔꿈치를 앞으로 돌려 바를 어깨 위에서 구부린다는 느낌으로 단단히 고정한다. 허리에 단단한 아치를 만든 채 랙에서 바를 빼고 뒤로 물러나 자세를 잡는다. 발을 넓게 벌리면 등·둔근·내전근·햄스트링이 더 강조되고, 좁게 서면 대퇴사두근 발달에 더 좋다. 머리는 정면을 향한다.","등, 어깨, 코어에 힘을 준 채 무릎과 엉덩이를 바깥으로 밀며 내려가기 시작한다. 엉덩이를 뒤로 빼며 앉아 박스에 걸터앉는다. 이상적으로는 정강이가 바닥과 수직이 되어야 한다. 박스에 닿으면 잠깐 멈추고 고관절 굴곡근의 힘을 뺀다. 절대 박스에서 반동으로 튕겨 일어나지 않는다.","무게중심을 뒤꿈치에 두고 발과 무릎을 바깥으로 밀면서, 머리가 동작을 이끌도록 박스에서 위로 힘차게 일어난다. 머리부터 발끝까지 긴장을 유지하며 끝까지 올라간다."], en: ["The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."] },
  "포즈 스쿼트": { k: ["스쿼트 랙에서 바벨을 승모근 위에 얹고 어깨너비 스탠스로 선다. 가슴을 들고 코어를 조인다. 이것이 시작 자세다.","숨을 크게 들이마셔 복압을 잡은 채 허벅지가 바닥과 평행이 되거나 그 아래까지 천천히 앉는다.","맨 아래 지점에서 2~3초간 정지한다. 힘을 빼고 주저앉는 것이 아니라 자세와 긴장을 그대로 유지한 채 버틴다.","숨을 내쉬며 발바닥 전체로 바닥을 밀어 시작 자세로 일어난다. 정해진 횟수만큼 반복한다.","팁: 정지 구간에서 상체가 앞으로 숙여지거나 무릎이 안쪽으로 무너지기 쉽다. 평소 스쿼트보다 가벼운 무게로 자세를 지키는 데 집중한다."], en: ["Set up in a squat rack with the barbell across your traps and stand with a shoulder-width stance. Chest up, core braced. This is your starting position.","Take a big breath, brace, and slowly squat down until your thighs are at or below parallel.","Pause at the bottom for 2-3 seconds. Don't relax and sink — hold your position and keep full-body tension.","Exhale and drive through your whole foot to stand back up to the starting position. Repeat for the prescribed reps.","Tip: During the pause it's easy for the chest to drop or the knees to cave in. Use less weight than your regular squat and focus on holding position."] },
  "오버헤드 스쿼트": { s: "Overhead_Squat/0.jpg", e: "Overhead_Squat/1.jpg", k: ["바벨을 몸 앞 바닥에 두고 시작한다. 발은 어깨너비보다 넓게 벌린다.","무릎을 구부리고 오버핸드 그립(손바닥이 몸 쪽을 향함)으로 바벨을 잡는다. 들어 올리기 전에 손 간격은 어깨너비보다 넓게 잡는다. 자세가 잡히면 바벨을 가슴 위에 얹을 수 있는 위치까지 들어 올린다.","바벨을 머리 위, 머리보다 약간 뒤쪽으로 올리고 팔을 완전히 편다. 머리는 항상 든 상태를 유지하고 등도 곧게 편다. 견갑골을 뒤로 모은다. 이것이 시작 자세다.","숨을 들이마시며 허벅지가 바닥과 평행이 될 때까지 무릎을 구부려 천천히 내려간다. 팁: 부상을 피하려면 등을 곧게 편 상태를 유지하고, 팔은 항상 머리 위에서 뻗은 상태여야 한다.","숨을 내쉬며 발과 다리 힘으로 무게를 시작 자세까지 밀어 올린다.","정해진 반복 횟수만큼 반복한다."], en: ["Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.","Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.","Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.","Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.","Now use your feet and legs to help bring the weight back up to the starting position while exhaling.","Repeat for the recommended amount of repetitions."] },
  "저처 스쿼트": { s: "Zercher_Squats/0.jpg", e: "Zercher_Squats/1.jpg", k: ["안전을 위해 스쿼트 랙 안에서 수행하는 것이 가장 좋다. 먼저 자신의 키에 맞는 높이로 랙에 바를 건다. 올바른 높이는 허리보다 높고 가슴보다 낮은 지점이다. 높이를 맞추고 중량을 끼웠으면 양손을 맞잡고 아래팔과 위팔 사이 팔꿈치 안쪽에 바를 얹는다.","바를 들어 올려 아래팔 위에 얹는다. 제대로 잡았다면 팔짱을 낀 자세 위로 바가 가로놓인 모습이 된다.","랙에서 물러나 발을 어깨너비의 미디엄 스탠스로 벌리고 발끝은 살짝 바깥을 향하게 한다. 시선을 아래로 두면 균형이 무너지므로 항상 고개를 들고 등은 곧게 유지한다. 이것이 시작 자세다. 팁: 여기서는 전반적인 발달을 노리는 미디엄 스탠스를 기준으로 설명하지만, 발 너비는 다른 스탠스를 선택해도 된다.","고개를 들고 곧은 자세를 유지하며 무릎을 굽혀 바를 내린다. 허벅지와 종아리 사이 각도가 90도보다 약간 작아질 때까지(허벅지가 바닥과 평행한 지점보다 살짝 더 내려갈 때까지) 내려가며, 이 구간에서 숨을 들이마신다. 팁: 올바르게 수행했다면 무릎 앞면과 발끝이 수직의 가상 일직선을 이룬다. 무릎이 발끝보다 앞으로 나가면 무릎에 불필요한 부담이 실리는 잘못된 자세다.","숨을 내쉬며 주로 발볼로 바닥을 밀어 다리를 다시 펴면서 바를 들어 올려 시작 자세로 돌아온다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.","Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."] },
  "스모 스쿼트": { s: "Plie_Dumbbell_Squat/0.jpg", e: "Plie_Dumbbell_Squat/1.jpg", k: ["덤벨 한쪽 머리 아래를 양손으로 받쳐 들고 똑바로 선다. 다리를 어깨너비보다 넓게 벌리고 무릎은 살짝 굽힌다.","발끝은 바깥을 향하게 한다. 팁: 동작 내내 팔은 고정한다. 이것이 시작 자세다.","천천히 무릎을 굽혀 허벅지가 바닥과 평행해질 때까지 내려간다. 내리는(신장성) 구간이므로 숨을 들이마신다.","숨을 내쉬며 주로 발뒤꿈치로 바닥을 밀어 몸을 시작 자세로 되돌린다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.","Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.","Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.","Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."] },
  "피스톨 스쿼트": { k: ["난이도가 매우 높은 동작이므로 처음에는 뒤에 박스를 두고 앉는 박스 피스톨이나, 기둥·링을 잡는 보조 버전으로 점진적으로 익혀 간다.","한 다리로 서서 반대 다리와 양팔을 몸 앞으로 뻗는다. 이것이 시작 자세다.","숨을 들이마시며 한 다리로 엉덩이가 발뒤꿈치에 가까워질 때까지 천천히 앉는다. 뻗은 다리는 바닥에 닿지 않게 유지하고, 가슴은 최대한 들어 올린다.","숨을 내쉬며 발바닥 전체로 바닥을 밀어 시작 자세로 일어난다.","정해진 횟수만큼 반복한 뒤 반대쪽 다리로 같은 동작을 수행한다.","팁: 바닥에서 발뒤꿈치가 뜨면 발목 가동성이 부족하다는 신호다. 발뒤꿈치에 얇은 원판을 받치거나 가동성 운동을 먼저 병행한다."], en: ["This is a very demanding movement — build up progressively with box pistols (squatting to a box behind you) or an assisted version holding a pole or rings.","Stand on one leg with the other leg and both arms extended in front of you. This is your starting position.","Inhale and slowly squat down on one leg until your hips are close to your heel. Keep the extended leg off the floor and your chest as upright as possible.","Exhale and drive through your whole foot to stand back up to the starting position.","Complete the prescribed reps, then repeat on the other leg.","Tip: If your heel lifts off the floor, that's a sign of limited ankle mobility. Place a small plate under your heel or work on mobility first."] },
  "월 싯": { k: ["벽에 등을 기대고 발을 벽에서 한 걸음 정도 앞에 어깨너비로 둔다.","등을 벽에 붙인 채 무릎이 90도가 될 때까지 미끄러지듯 내려간다. 허벅지는 바닥과 평행, 정강이는 수직이 되게 한다. 이것이 유지 자세다.","자연스럽게 호흡하며 정해진 시간 동안 자세를 유지한다. 허벅지 앞쪽의 자극에 집중한다.","시간이 다 되면 발로 바닥을 밀며 벽을 따라 일어난다.","팁: 무릎이 발끝보다 앞으로 나가면 무릎에 부담이 실린다. 발을 충분히 앞에 두어 정강이가 수직을 유지하게 한다."], en: ["Lean your back against a wall with your feet about one step away from it, shoulder-width apart.","Keeping your back flat against the wall, slide down until your knees reach 90 degrees. Thighs parallel to the floor, shins vertical. This is your hold position.","Breathe naturally and hold the position for the prescribed time, focusing on the tension in the front of your thighs.","When time is up, push through your feet and slide back up the wall to stand.","Tip: If your knees travel past your toes, they take extra stress. Set your feet far enough forward to keep your shins vertical."] },
  "점프 스쿼트": { s: "Freehand_Jump_Squat/0.jpg", e: "Freehand_Jump_Squat/1.jpg", k: ["양팔을 가슴 앞에서 교차한다.","고개를 들고 등을 곧게 편 채 발을 어깨너비로 벌린다.","등을 곧게 펴고 가슴을 든 채 숨을 들이마시며 허벅지가 바닥과 평행해지거나 그보다 낮아질 때까지 앉는다.","이제 허벅지를 스프링처럼 사용해 주로 발볼로 바닥을 밀며 최대한 높이 수직으로 점프한다. 이 구간에서 숨을 내쉰다.","바닥에 착지하면 곧바로 다시 앉았다가 점프한다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["Cross your arms over your chest.","With your head up and your back straight, position your feet at shoulder width.","Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.","Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.","When you touch the floor again, immediately squat down and jump again.","Repeat for the recommended amount of repetitions."] },
  "박스 점프": { s: "Front_Box_Jump/0.jpg", e: "Front_Box_Jump/1.jpg", k: ["적당한 높이의 박스를 앞쪽 30~60cm 지점에 둔다. 발을 어깨너비로 벌리고 선다. 이것이 시작 자세다.","점프를 준비하며 팔을 뒤로 스윙하면서 살짝 앉는다.","이 자세에서 반동을 이용해 고관절·무릎·발목을 힘차게 펴며 최대한 높이 점프한다. 팔은 앞과 위로 스윙한다.","무릎을 굽힌 채 박스 위에 착지해 다리로 충격을 흡수한다. 내려올 때는 박스에서 바닥으로 뛰어내려도 되지만, 한 발씩 걸어 내려오는 것이 더 좋다."], en: ["Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.","Perform a short squat in preparation for jumping, swinging your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time."] },
  "레터럴 박스 점프": { s: "Lateral_Box_Jump/0.jpg", e: "Lateral_Box_Jump/1.jpg", k: ["낮은 박스를 옆에 두고 편안하게 선다. 이것이 시작 자세다.","신장 반사를 일으키도록 쿼터 스쿼트 깊이로 빠르게 내려앉았다가, 즉시 방향을 바꿔 위와 옆으로 점프한다.","발이 박스를 충분히 넘을 수 있도록 무릎을 높이 끌어 올린다.","박스 중앙에 착지하며 다리로 충격을 흡수한다.","조심스럽게 박스 반대편으로 뛰어 내려가고, 좌우로 오가며 여러 회 반복한다."], en: ["Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.","Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.","Bring your knees high enough to ensure your feet have good clearance over the box.","Land on the center of the box, using your legs to absorb the impact.","Carefully jump down to the other side of the box, and continue going back and forth for several repetitions."] },
  "프로그 점프": { s: "Frog_Hops/0.jpg", e: "Frog_Hops/1.jpg", k: ["양손을 머리 뒤에 대고 서서, 상체를 세우고 고개를 든 채 스쿼트 자세로 앉는다. 이것이 시작 자세다.","불필요하게 높이 뛰지 말고 앞으로 1~2m가량 점프한다. 발이 바닥에 닿으면 다리로 충격을 흡수하고 곧바로 다시 점프한다. 이 동작을 5~10회 반복한다."], en: ["Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."] },
  "레터럴 스쿼트": { k: ["다리를 어깨너비의 두 배 정도로 넓게 벌리고 발끝은 약간 바깥을 향하게 선다. 가슴을 들고 코어에 힘을 준다. 이것이 시작 자세다.","숨을 들이마시며 한쪽 무릎을 굽혀 체중을 그쪽으로 옮기면서 엉덩이를 뒤로 빼며 앉는다. 반대쪽 다리는 편 상태를 유지하고 등은 곧게 세운다.","숨을 내쉬며 굽힌 다리로 바닥을 밀어 중앙 시작 자세로 돌아온다.","반대쪽으로 같은 동작을 수행하며 좌우 교대로 정해진 횟수만큼 반복한다.","팁: 굽힌 쪽 발뒤꿈치가 바닥에서 뜨지 않게 체중을 발 전체에 싣는다. 무릎은 항상 발끝과 같은 방향을 향해야 한다."], en: ["Stand with your feet about twice shoulder-width apart, toes pointed slightly out. Chest up, core braced. This is your starting position.","Inhale and shift your weight to one side, bending that knee and sitting your hips back while keeping the other leg straight. Keep your back upright.","Exhale and push through the bent leg to return to the center starting position.","Repeat to the other side, alternating for the prescribed number of repetitions.","Tip: Keep the heel of the bent leg flat on the floor with your weight spread across the whole foot. Your knee should always track in line with your toes."] },
  "리버스 런지": { k: ["골반 너비로 서서 손은 허리에 올리거나 가슴 앞에 모은다. 이것이 시작 자세다.","숨을 들이마시며 한 발을 뒤로 크게 내딛고, 양 무릎이 90도가 될 때까지 몸을 수직으로 낮춘다. 뒷무릎은 바닥에 닿기 직전까지 내리고 상체는 곧게 세운다.","숨을 내쉬며 앞발 뒤꿈치로 바닥을 밀어 시작 자세로 돌아온다.","좌우 교대로, 또는 한쪽씩 정해진 횟수만큼 반복한다.","팁: 앞무릎이 안쪽으로 무너지지 않게 발끝과 같은 방향을 유지한다. 뒤로 내딛는 방식이라 앞무릎에 실리는 부담이 적어 런지 입문에 적합하다."], en: ["Stand with your feet hip-width apart, hands on your hips or clasped in front of your chest. This is your starting position.","Inhale and take a big step backward, lowering your body straight down until both knees reach 90 degrees. Bring the back knee just above the floor and keep your torso upright.","Exhale and push through the front heel to return to the starting position.","Repeat alternating legs, or complete all reps on one side before switching.","Tip: Keep the front knee tracking over your toes, not caving inward. Stepping backward puts less stress on the front knee, making this a great entry point to lunges."] },
  "레터럴 런지": { k: ["골반 너비로 서서 가슴을 들고 코어에 힘을 준다. 이것이 시작 자세다.","숨을 들이마시며 한 발을 옆으로 크게 내딛는 동시에 그쪽 무릎을 굽히고 엉덩이를 뒤로 빼며 앉는다. 반대쪽 다리는 편 상태를 유지한다.","숨을 내쉬며 내디딘 발로 바닥을 힘차게 밀어 시작 자세로 돌아온다.","좌우 교대로 정해진 횟수만큼 반복한다.","팁: 무릎만 앞으로 굽히지 말고 힙 힌지로 엉덩이를 뒤로 빼야 무릎 부담이 줄고 엉덩이와 허벅지가 함께 자극된다."], en: ["Stand with your feet hip-width apart, chest up and core braced. This is your starting position.","Inhale and take a big step out to the side, bending that knee and sitting your hips back as you land. Keep the other leg straight.","Exhale and push off the stepping foot forcefully to return to the starting position.","Alternate sides for the prescribed number of repetitions.","Tip: Hinge at the hips and sit back rather than just bending the knee forward — this reduces knee stress and works the glutes and thighs together."] },
  "커시 런지": { s: "Crossover_Reverse_Lunge/0.jpg", e: "Crossover_Reverse_Lunge/1.jpg", k: ["발을 어깨너비로 벌리고 선다. 이것이 시작 자세다.","한 발을 뒤로 빼고 고관절과 앞무릎을 굽혀 리버스 런지를 수행한다. 이때 상체를 앞다리 쪽으로 가로질러 회전한다.","잠깐 멈춘 뒤 시작 자세로 돌아오고, 반대쪽으로 같은 동작을 수행하며 좌우를 번갈아 이어간다."], en: ["Stand with your feet shoulder width apart. This will be your starting position.","Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.","After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."] },
  "점프 런지": { k: ["한 발을 앞에 둔 런지 자세에서 양 무릎을 90도로 굽혀 몸을 낮춘다. 이것이 시작 자세다.","숨을 내쉬며 양발로 바닥을 폭발적으로 밀어 점프하고, 공중에서 앞뒤 다리를 교체한다.","반대쪽 런지 자세로 착지하며 무릎을 굽혀 충격을 부드럽게 흡수한다. 착지 후 균형을 잡고 곧바로 다음 점프로 잇는다.","좌우 교대로 정해진 횟수만큼 반복한다. 동작 내내 상체는 곧게 세운다.","팁: 착지할 때 무릎이 흔들리면 속도를 늦추고 점프 높이를 낮춘다. 높이보다 착지의 안정이 우선이다."], en: ["Start in a lunge position with one foot forward, both knees bent to 90 degrees. This is your starting position.","Exhale and explosively push off the floor with both feet, switching your legs in mid-air.","Land in a lunge with the opposite leg forward, bending your knees to absorb the impact softly. Find your balance, then flow into the next jump.","Alternate legs for the prescribed number of repetitions, keeping your torso upright throughout.","Tip: If your knees wobble on landing, slow down and jump lower. A stable landing matters more than jump height."] },
  "오버헤드 런지": { k: ["양손에 덤벨을 들고 팔을 편 채 머리 위로 곧게 들어 올린다. 코어를 조이고 골반 너비로 선다. 이것이 시작 자세다.","숨을 들이마시며 한 발을 앞으로 크게 내딛고 양 무릎이 90도가 될 때까지 몸을 낮춘다. 덤벨은 계속 머리 위에서 수직을 유지한다.","숨을 내쉬며 앞발로 바닥을 밀어 시작 자세로 돌아온다.","좌우 교대로 정해진 횟수만큼 반복한다.","팁: 동작 중 팔꿈치가 굽거나 덤벨이 앞으로 기울면 어깨 안정성이 부족한 것이다. 가벼운 무게로 시작해 머리 위 고정부터 익힌다."], en: ["Hold a dumbbell in each hand and press them straight overhead with arms locked. Brace your core and stand with feet hip-width apart. This is your starting position.","Inhale and take a big step forward, lowering your body until both knees reach 90 degrees. Keep the dumbbells vertical over your head the entire time.","Exhale and push through the front foot to return to the starting position.","Alternate legs for the prescribed number of repetitions.","Tip: If your elbows bend or the dumbbells drift forward, your overhead stability isn't there yet. Start light and master holding the weight locked out first."] },
  "스플릿 스쿼트": { k: ["양손에 덤벨을 들고 한 발은 앞, 한 발은 뒤에 둔 스플릿 스탠스로 선다. 상체는 곧게 세운다. 이것이 시작 자세다.","숨을 들이마시며 뒷무릎이 바닥에 닿기 직전까지 몸을 수직으로 낮춘다. 체중은 앞발에 대부분 싣는다.","숨을 내쉬며 앞발 전체로 바닥을 밀어 시작 자세로 일어난다. 발 위치는 그대로 유지한다.","정해진 횟수만큼 반복한 뒤 다리를 바꿔 같은 동작을 수행한다.","팁: 발 앞뒤 간격이 좁으면 균형이 무너지고 무릎이 발끝을 크게 넘어간다. 앞뒤로 충분히 벌리고 좌우는 골반 너비를 유지한다."], en: ["Hold a dumbbell in each hand and stand in a split stance, one foot forward and one foot back. Keep your torso upright. This is your starting position.","Inhale and lower your body straight down until your back knee is just above the floor. Keep most of your weight on the front foot.","Exhale and drive through the whole front foot to stand back up, keeping your feet in place.","Complete the prescribed reps, then switch legs and repeat.","Tip: A stance that's too short wrecks your balance and pushes the front knee far past your toes. Take a long enough split and keep your feet hip-width apart laterally."] },
  "글루트 햄 레이즈": { s: "Glute_Ham_Raise/0.jpg", e: "Glute_Ham_Raise/1.jpg", k: ["먼저 기구를 몸에 맞게 조절한다. 엎드린 자세로 롤러 사이의 발판에 발을 대고 고정한다. 무릎은 패드 바로 뒤에 오게 한다.","동작의 맨 아래 지점에서 시작한다. 등의 아치를 유지한 채 무릎을 구부리며 동작을 시작한다. 이때 발끝으로 발판을 강하게 민다. 상체를 곧게 유지하며 몸이 수직으로 설 때까지 이어 간다.","내려가는 동작을 통제하며 시작 자세로 되돌아간다."], en: ["Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.","Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.","Return to the starting position, keeping your descent under control."] },
  "스탠딩 레그 컬": { s: "Standing_Leg_Curl/0.jpg", e: "Standing_Leg_Curl/1.jpg", k: ["머신 레버를 키에 맞게 조절하고, 상체를 허리에서 앞으로 30~45도 정도 숙인 자세를 잡는다(기울인 자세가 햄스트링 동원에 더 유리하다). 레버 패드는 오른쪽 다리 뒤쪽(종아리 아래 몇 센티미터 지점)에 대고, 오른쪽 다리 앞면은 머신 패드 위에 올린다.","상체를 앞으로 숙인 상태를 유지하며 다리를 완전히 편 채 머신 옆 손잡이를 잡는다. 발끝은 곧게 둔다. 이것이 시작 자세다.","숨을 내쉬며 허벅지가 패드에서 떨어지지 않는 범위에서 오른쪽 다리를 최대한 위로 컬한다. 완전히 수축된 지점에 도달하면 1초간 유지한다.","숨을 들이마시며 다리를 처음 자세로 되돌린다. 정해진 반복 횟수만큼 반복한다.","이제 왼쪽 다리로 같은 동작을 수행한다."], en: ["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.","Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.","As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.","Perform the same exercise now for the left leg."] },
  "케이블 풀 스루": { s: "Pull_Through/0.jpg", e: "Pull_Through/1.jpg", k: ["로프나 핸들을 연결한 로우 풀리 앞 1m가량 지점에 선다. 머신을 등지고 케이블을 다리 사이에 둔 채 발을 넓게 벌린다.","힙 힌지로 상체를 숙이며 양손을 다리 사이로 최대한 멀리 뻗는 것으로 동작을 시작한다. 무릎은 살짝 굽힌 상태를 유지한다. 팔을 편 채 고관절을 펴면서 똑바로 일어선다. 어깨로 끌어올리지 말고 모든 동작이 고관절에서 시작되도록 한다."], en: ["Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.","Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips."] },
  "리버스 하이퍼익스텐션": { s: "Reverse_Hyperextension/0.jpg", e: "Reverse_Hyperextension/1.jpg", k: ["적절한 무게를 장착한 뒤 패드 사이에 발을 끼운다. 상단 패드에 엎드려 엉덩이가 뒤로 걸쳐 늘어지게 하고, 손잡이를 잡아 자세를 고정한다.","고관절을 접어 다리를 앞으로 당기며 동작을 시작한다.","고관절을 펴서 다리를 뒤로 차올리며 동작을 반전시킨다. 이 동작에서 고관절을 과도하게 펴지 않는 것이 매우 중요하며, 최대 가동범위 직전에서 멈춘다.","다시 고관절을 접어 캐리지를 최대한 앞으로 당기며 되돌아간다.","원하는 반복 횟수만큼 반복한다."], en: ["Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.","To begin the movement, flex the hips, pulling the legs forward.","Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.","Return by again flexing the hip, pulling the carriage forward as far as you can.","Repeat for the desired number of repetitions."] },
  "데드리프트 하이 풀": { k: ["폭발적인 전신 동작이므로 가벼운 무게나 빈 봉으로 데드리프트와 업라이트 로우를 각각 익힌 뒤 점진적으로 연결하는 것이 안전하다.","어깨너비로 서서 오버핸드 그립으로 바를 잡고, 힙 힌지로 엉덩이를 뒤로 빼며 등을 곧게 편다. 이것이 시작 자세다.","숨을 내쉬며 다리와 엉덩이를 폭발적으로 펴서 바를 끌어 올리고, 그 추진력을 이어받아 팔꿈치를 높이 세우며 바를 가슴 높이까지 당긴다.","숨을 들이마시며 바를 컨트롤해 허벅지를 따라 시작 자세로 내리고, 정해진 반복 횟수만큼 반복한다.","팁: 팔로 먼저 당기지 않는다 — 하체의 폭발력이 먼저이고 팔은 마지막에 따라온다."], en: ["This is an explosive full-body movement — learn the deadlift and upright row separately with light weight or an empty bar, then progress gradually.","Stand shoulder-width apart, grab the bar with an overhand grip, and hinge at the hips with your back flat. This is your starting position.","Exhale and explosively extend your legs and hips to pull the bar up, letting the momentum carry it to chest height as your elbows drive high.","Inhale and lower the bar under control along your thighs back to the starting position. Repeat for the prescribed amount of repetitions.","Tip: Don't pull with your arms first — the lower-body drive comes first and the arms follow last."] },
  "파이어 하이드런트": { k: ["매트 위에 네발기기 자세를 잡는다. 손은 어깨 아래, 무릎은 엉덩이 아래에 두고 코어에 힘을 주어 등을 평평하게 유지한다. 이것이 시작 자세다.","숨을 내쉬며 무릎을 90도로 구부린 채 한쪽 다리를 옆으로 들어 올린다. 골반이 기울지 않는 범위까지만 올린다.","동작 맨 위에서 1초간 멈춰 둔근 측면의 수축을 느낀다.","숨을 들이마시며 천천히 시작 자세로 되돌린다. 한쪽을 정해진 횟수만큼 반복한 뒤 반대쪽도 수행한다.","팁: 다리를 높이 올리려고 몸통을 반대쪽으로 기울이는 것이 흔한 실수다. 몸통과 골반은 고정하고 움직임은 오직 고관절에서만 일어나야 한다."], en: ["Get on all fours on a mat with your hands under your shoulders and knees under your hips. Brace your core and keep your back flat. This will be your starting position.","As you breathe out, lift one leg out to the side with the knee bent at 90 degrees. Only raise it as high as you can without tilting your pelvis.","Pause for a second at the top and feel the contraction in the side of your glutes.","Breathe in as you slowly return to the starting position. Complete the prescribed reps on one side, then switch sides.","Tip: A common mistake is leaning the torso to the opposite side to lift the leg higher. Keep your torso and pelvis fixed; the movement should come only from the hip joint."] },
  "클램셸": { k: ["옆으로 누워 무릎을 약 90도로 구부리고 두 다리를 포갠다. 머리는 아래팔로 받치고, 발뒤꿈치·엉덩이·등이 일직선이 되게 한다. 이것이 시작 자세다.","숨을 내쉬며 두 발뒤꿈치를 붙인 채 위쪽 무릎을 조개가 열리듯 천장 방향으로 들어 올린다.","동작 맨 위에서 1초간 멈춰 둔근 측면의 수축을 느낀 뒤, 숨을 들이마시며 천천히 무릎을 내린다.","한쪽을 정해진 횟수만큼 반복한 뒤 반대쪽도 수행한다.","팁: 골반이 뒤로 굴러가며 허리로 동작하는 것이 흔한 실수다. 골반을 바닥과 수직으로 고정하고 고관절 회전만으로 무릎을 연다. 강도를 높이려면 무릎 위에 미니 밴드를 두른다."], en: ["Lie on your side with your knees bent about 90 degrees and legs stacked. Support your head with your forearm, keeping your heels, hips, and back in a straight line. This will be your starting position.","As you breathe out, keep your heels together and lift your top knee toward the ceiling, opening like a clamshell.","Pause for a second at the top, feeling the contraction in the side of your glutes, then breathe in as you slowly lower the knee.","Complete the prescribed reps on one side, then switch sides.","Tip: A common mistake is rolling the pelvis backward and working from the lower back. Keep your pelvis stacked perpendicular to the floor and open the knee only through hip rotation. Add a mini band above the knees for more resistance."] },
  "프로그 펌프": { k: ["바닥에 등을 대고 누워 양 발바닥을 서로 붙이고 무릎을 바깥으로 벌린다. 덤벨을 골반 위에 올려 양손으로 잡는다. 이것이 시작 자세다.","숨을 내쉬며 발날 바깥쪽으로 바닥을 누르면서 엉덩이를 힘차게 들어 올리고, 최고 지점에서 둔근을 강하게 수축시킨다.","1초간 유지한 뒤 숨을 들이마시며 엉덩이가 바닥에 닿기 직전까지 천천히 내린다.","정해진 반복 횟수만큼 리듬감 있게 반복한다. 팁: 허리를 과도하게 젖히지 말고 골반을 살짝 말아 올린다는 느낌으로 둔근에 집중한다."], en: ["Lie on your back with the soles of your feet together and knees flared out. Rest a dumbbell on your hips and hold it with both hands. This is your starting position.","Exhale and drive your hips up forcefully, pressing through the outer edges of your feet, and squeeze your glutes hard at the top.","Hold for a second, then inhale and lower your hips slowly until they almost touch the floor.","Repeat rhythmically for the prescribed amount of repetitions. Tip: Don't overarch your lower back — tuck your pelvis slightly and focus on the glutes."] },
  "버드 독": { k: ["매트 위에 네발기기 자세를 잡는다. 손은 어깨 아래, 무릎은 엉덩이 아래에 두고 코어에 힘을 주어 등을 평평하게 유지한다. 이것이 시작 자세다.","숨을 내쉬며 한쪽 팔을 앞으로, 반대쪽 다리를 뒤로 동시에 뻗는다. 뻗은 팔·몸통·다리가 일직선이 되게 하고 둔근을 조인다.","끝 지점에서 1~2초간 멈춰 균형을 유지한다. 이때 골반과 어깨는 바닥과 평행을 유지해야 한다.","숨을 들이마시며 천천히 시작 자세로 돌아온 뒤 반대쪽 팔·다리로 반복한다. 양쪽을 번갈아 정해진 횟수만큼 수행한다.","팁: 다리를 높이 차올리며 허리가 꺾이는 것이 흔한 실수다. 다리는 엉덩이 높이까지만 뻗고, 배꼽을 당겨 허리의 중립을 고정한다."], en: ["Get on all fours on a mat with your hands under your shoulders and knees under your hips. Brace your core and keep your back flat. This will be your starting position.","As you breathe out, extend one arm forward and the opposite leg back at the same time. Keep the extended arm, torso, and leg in a straight line and squeeze your glutes.","Pause for one to two seconds at the end position, keeping your balance. Your hips and shoulders should stay parallel to the floor.","Breathe in as you slowly return to the starting position, then repeat with the opposite arm and leg. Alternate sides for the prescribed reps.","Tip: A common mistake is kicking the leg too high and arching the lower back. Extend the leg only to hip height and draw your navel in to keep the spine neutral."] },
  "글루트 킥백 머신": { k: ["머신의 가슴 패드에 상체를 기대고 손잡이를 잡은 뒤, 한쪽 발바닥을 발판 위에 올린다. 이것이 시작 자세다.","숨을 내쉬며 발뒤꿈치로 발판을 밀어 다리를 뒤로 곧게 뻗고, 최고 지점에서 둔근을 1초간 강하게 수축시킨다.","숨을 들이마시며 무게에 저항하면서 천천히 시작 자세로 돌아온다.","정해진 반복 횟수를 마친 뒤 반대쪽 다리도 같은 방식으로 수행한다. 팁: 허리를 젖혀 반동을 쓰지 말고 코어를 고정한 채 둔근의 힘만으로 밀어낸다."], en: ["Lean your torso against the chest pad, grab the handles, and place one foot on the platform. This is your starting position.","Exhale and push the platform back through your heel until your leg is fully extended, squeezing your glute hard for a second at the top.","Inhale and return slowly to the starting position, resisting the weight.","Complete the prescribed reps, then switch legs. Tip: Don't arch your back for momentum — keep your core braced and push with glute strength only."] },
  "글루트 킥백": { s: "Glute_Kickback/0.jpg", e: "Glute_Kickback/1.jpg", k: ["바닥이나 운동 매트에 무릎을 꿇고 허리를 숙여, 팔을 상체와 수직으로 앞으로 뻗어 무릎 대고 엎드린 자세(팔 간격은 어깨너비)를 만든다. 머리는 정면을 보고, 무릎은 햄스트링과 종아리가 90도를 이루도록 구부린다. 이것이 시작 자세다.","숨을 내쉬며 90도로 구부린 무릎 각도를 유지한 채 햄스트링이 등과 일직선이 될 때까지 오른쪽 다리를 들어 올린다. 동작 내내 둔근을 수축시키고 맨 위에서 1초간 수축을 유지한다. 팁: 동작 끝에서 허벅지는 바닥과 평행, 종아리는 바닥과 수직이 되어야 한다.","숨을 들이마시며 처음 자세로 되돌아간 뒤 왼쪽 다리로 반복한다.","정해진 반복 횟수를 모두 채울 때까지 다리를 번갈아 계속한다."], en: ["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."] },
  "케이블 힙 어브덕션": { k: ["케이블 머신의 도르래를 가장 낮게 설정하고 발목 스트랩을 바깥쪽 발목에 착용한 뒤, 머신 옆으로 서서 기둥이나 손잡이를 잡아 몸을 고정한다. 이것이 시작 자세다.","숨을 내쉬며 다리를 곧게 편 채 옆으로 들어 올려 둔근 측면(중둔근)을 수축시킨다.","최고 지점에서 잠깐 멈춘 뒤 숨을 들이마시며 천천히 시작 자세로 돌아온다.","정해진 반복 횟수를 마친 뒤 반대쪽도 같은 방식으로 수행한다. 팁: 상체를 반대쪽으로 기울여 반동을 쓰지 말고, 가동 범위가 좁더라도 골반을 수평으로 유지한다."], en: ["Set the pulley to the lowest position and attach an ankle strap to your outer ankle. Stand sideways to the machine and hold the frame for balance. This is your starting position.","Exhale and raise your leg out to the side with the knee straight, contracting the side of your glutes.","Pause briefly at the top, then inhale and return slowly to the starting position.","Complete the prescribed reps, then switch sides. Tip: Don't lean away for momentum — keep your pelvis level even if the range of motion is small."] },
  "케이블 힙 어덕션": { s: "Cable_Hip_Adduction/0.jpg", e: "Cable_Hip_Adduction/1.jpg", k: ["로우 풀리 앞에 정면을 보고 서서 한쪽 다리는 풀리 가까이에, 다른 쪽 다리는 멀리 둔다.","발목 커프를 케이블에 연결하고, 풀리 쪽에 있는 다리의 발목에 착용한다.","이제 웨이트 스택에서 옆으로 넓게 물러서서 풀리 기구의 바를 잡는다.","커프를 차지 않은 발(먼 쪽 발)로 서고, 커프를 찬 다리가 로우 풀리 쪽으로 당겨지게 둔다. 이것이 시작 자세다.","허벅지 안쪽(내전근) 힘으로 커프를 찬 다리를 반대쪽 다리 앞으로 교차하듯 모아 동작을 수행한다. 이 구간에서 숨을 내쉰다.","숨을 들이마시며 천천히 시작 자세로 되돌아간다.","정해진 반복 횟수만큼 반복한 뒤 반대쪽 다리로 같은 동작을 반복한다."], en: ["Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.","Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.","Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.","Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.","Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg."] },
  "레터럴 레그 레이즈": { k: ["옆으로 누워 아래쪽 팔로 머리를 받치고 몸을 일직선으로 만든다. 이것이 시작 자세다.","숨을 내쉬며 위쪽 다리를 곧게 편 채 천천히 들어 올린다. 발끝은 정면을 향하게 유지한다.","최고 지점에서 1초간 멈춰 둔근 측면의 수축을 느낀 뒤, 숨을 들이마시며 천천히 내린다.","정해진 반복 횟수를 마친 뒤 반대쪽으로 돌아누워 같은 방식으로 수행한다. 팁: 골반이 뒤로 넘어가지 않게 몸통을 고정하고, 다리를 높이 올리기보다 둔근의 긴장을 유지하는 데 집중한다."], en: ["Lie on your side with your head resting on your lower arm and your body in a straight line. This is your starting position.","Exhale and slowly raise your top leg, keeping it straight and your toes pointing forward.","Pause for a second at the top, feeling the side of your glutes contract, then inhale and lower slowly.","Complete the prescribed reps, then switch sides. Tip: Keep your torso steady so your pelvis doesn't roll back — focus on keeping tension in the glutes rather than lifting the leg as high as possible."] },
  "레터럴 밴드 워크": { k: ["미니 밴드를 무릎 위(또는 발목)에 두르고, 발을 어깨너비로 벌려 밴드에 장력을 만든다. 엉덩이를 뒤로 빼고 무릎을 살짝 구부린 하프 스쿼트 자세를 잡는다. 이것이 시작 자세다.","자세를 유지한 채 한쪽 발을 옆으로 한 걸음 내딛고, 반대쪽 발을 따라 붙인다. 이때도 밴드의 장력이 풀리지 않을 만큼 발 간격을 유지한다.","호흡을 자연스럽게 이어가며 한 방향으로 정해진 걸음 수만큼 이동한 뒤, 반대 방향으로 같은 걸음 수만큼 돌아온다.","이동 내내 둔근 측면에 긴장이 유지되는 것을 느낀다.","팁: 무릎이 안쪽으로 모이거나 상체가 좌우로 흔들리는 것이 흔한 실수다. 무릎을 발끝 방향으로 밀어내고 골반 높이를 일정하게 유지한다."], en: ["Place a mini band above your knees (or around your ankles) and stand with your feet shoulder-width apart to create tension in the band. Push your hips back and bend your knees into a half-squat stance. This will be your starting position.","Holding this stance, take a step to the side with one foot, then follow with the other foot. Keep enough distance between your feet so the band never goes slack.","Breathing naturally, walk the prescribed number of steps in one direction, then return the same number of steps the other way.","Feel constant tension in the sides of your glutes throughout the walk.","Tip: Letting the knees cave in or rocking the torso side to side are common mistakes. Push your knees out over your toes and keep your hip height level."] },
  "데드 버그": { s: "Dead_Bug/0.jpg", e: "Dead_Bug/1.jpg", k: ["등을 대고 누워 두 손을 천장을 향해 곧게 뻗는다.","발·무릎·고관절을 들어 올려 각각 90도가 되게 한다.","숨을 강하게 내쉬어 갈비뼈를 끌어내리고 허리를 바닥에 밀착시키며, 골반을 말아 올리고 둔근에 힘을 준다. 이 자세를 동작 내내 유지한다. 이것이 시작 자세다.","한쪽 다리의 무릎과 고관절을 펴서 다리가 바닥 바로 위에 오도록 뻗으며 동작을 시작한다.","동작 중 허리가 뜨려고 하므로 허리와 골반의 위치를 그대로 유지한다.","코어에 힘을 유지한 채 뻗은 다리를 시작 자세로 되돌린다.","반대쪽도 같은 방식으로, 세트가 끝날 때까지 번갈아 반복한다."], en: ["Begin lying on your back with your hands extended above you toward the ceiling.","Bring your feet, knees, and hips up to 90 degrees.","Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.","Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.","Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.","Stay tight and return the working leg to the starting position.","Repeat on the opposite side, alternating until the set is complete."] },
  "V 싯업": { s: "Jackknife_Sit-Up/0.jpg", e: "Jackknife_Sit-Up/1.jpg", k: ["바닥이나 매트에 등을 대고 누워 팔을 머리 위로 곧게 뻗고 다리도 쭉 편다. 이것이 시작 자세다.","숨을 내쉬며 허리를 접어 다리와 팔을 동시에 들어 올려 V자 모양으로 맞닿게 한다. 팁: 다리는 편 채 바닥에서 약 35~45도 각도로 들고, 팔은 편 채 다리와 평행하게 유지한다. 상체는 바닥에서 떨어져 있어야 한다.","숨을 들이마시며 팔과 다리를 시작 자세로 내린다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.","As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.","While inhaling, lower your arms and legs back to the starting position.","Repeat for the recommended amount of repetitions."] },
  "할로우 락": { k: ["바닥에 등을 대고 누워 양팔을 머리 위로 뻗고 다리를 모아 편다. 허리를 바닥에 밀착시키며 어깨와 다리를 바닥에서 살짝 들어 올려 몸이 얕은 바나나 모양이 되게 한다. 이것이 할로우 자세이자 시작 자세다.","몸의 긴장을 그대로 유지한 채 흔들의자처럼 몸 전체를 앞뒤로 부드럽게 흔든다.","호흡을 멈추지 말고 짧고 일정하게 유지하며 정해진 횟수 또는 시간 동안 반복한다.","팁: 허리가 바닥에서 뜨면 자세가 무너진 것이다. 허리 밀착이 어려우면 무릎을 구부리거나 팔을 몸 옆에 두는 쉬운 변형부터 시작한다."], en: ["Lie on your back with your arms extended overhead and legs straight and together. Press your lower back into the floor and lift your shoulders and legs slightly off the ground so your body forms a shallow banana shape. This is the hollow position and your starting position.","Keeping your body rigid, rock smoothly back and forth like a rocking chair.","Do not hold your breath; keep breathing in short, steady breaths and continue for the prescribed reps or time.","Tip: If your lower back lifts off the floor, the position has broken down. If keeping it pressed down is difficult, start with an easier variation with bent knees or arms at your sides."] },
  "플러터 킥": { s: "Flutter_Kicks/0.jpg", e: "Flutter_Kicks/1.jpg", k: ["플랫 벤치에 엎드려 골반을 벤치 끝에 걸치고, 다리는 편 채 발끝을 바닥에서 높이 띄우며, 양팔은 벤치 위에서 앞쪽 모서리를 잡는다.","둔근과 햄스트링에 힘을 주어 다리를 골반 높이까지 편다. 이것이 시작 자세다.","왼쪽 다리를 오른쪽 다리보다 높이 들어 올리며 동작을 시작한다.","이어서 왼쪽 다리를 내리는 동시에 오른쪽 다리를 들어 올린다.","물장구를 치듯 좌우를 번갈아 가며 다리마다 정해진 반복 횟수를 채운다. 동작은 항상 통제된 상태로 유지한다. 팁: 동작 중에는 자연스럽게 호흡한다."], en: ["On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.","Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.","Start the movement by lifting the left leg higher than the right leg.","Then lower the left leg as you lift the right leg.","Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement."] },
  "시저 킥": { s: "Scissor_Kick/0.jpg", e: "Scissor_Kick/1.jpg", k: ["바닥이나 운동 매트(선택) 위에 등을 붙이고 눕는다. 두 팔은 양옆으로 완전히 펴고 손바닥은 아래를 향하게 한다. 참고: 팔은 동작 내내 고정한다.","무릎을 살짝 구부린 채 다리를 들어 올려 발뒤꿈치가 바닥에서 15cm 정도 뜨게 한다. 이것이 시작 자세다.","왼쪽 다리를 45도 정도까지 들어 올리는 동시에 오른쪽 다리는 발뒤꿈치가 바닥에서 5~7cm 정도 남을 때까지 내린다.","오른쪽 다리를 올리고 왼쪽 다리를 내리며 동작을 교차한다. 동작 중 호흡을 멈추지 않는다.","권장 반복 횟수만큼 반복한다."], en: ["To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.","With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.","Repeat for the recommended amount of repetitions."] },
  "토 터치": { s: "Toe_Touchers/0.jpg", e: "Toe_Touchers/1.jpg", k: ["바닥이나 매트에 등을 밀착시키고 눕는다. 양팔은 손바닥이 아래를 향하게 하여 몸 옆에 둔다.","양다리는 서로 붙인다. 무릎을 살짝 굽힌 채 다리가 바닥과 거의 수직이 될 때까지 천천히 들어 올린다. 발바닥은 바닥과 평행하게 한다.","팔을 바닥에서 45도 각도로 완전히 뻗는다. 이것이 시작 자세다.","허리를 바닥에 붙인 채 상체를 천천히 들어 올려 손으로 발끝을 터치하듯 뻗는다. 이 구간에서 숨을 내쉰다.","숨을 들이마시며 상체와 팔을 천천히 시작 자세로 내린다. 팔은 발끝을 향해 곧게 뻗은 상태를 유지한다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.","Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.","Repeat for the recommended amount of repetitions."] },
  "힐 터치": { s: "Alternate_Heel_Touchers/0.jpg", e: "Alternate_Heel_Touchers/1.jpg", k: ["무릎을 굽히고 발을 바닥에 45~60cm 간격으로 벌린 채 눕는다. 양팔은 몸 옆으로 뻗는다. 이것이 시작 자세다.","상체를 앞으로 들어 올리며 오른쪽으로 8~10cm가량 크런치하여 오른쪽 발뒤꿈치를 터치하고 수축 상태를 1초간 유지한다. 이 동작을 하며 숨을 내쉰다.","숨을 들이마시며 천천히 시작 자세로 돌아온다.","이번에는 상체를 앞으로 들어 올리며 왼쪽으로 8~10cm가량 크런치하여 왼쪽 발뒤꿈치를 터치하고 수축 상태를 1초간 유지한다. 동작 중에는 숨을 내쉬고, 숨을 들이마시며 시작 자세로 돌아온다. 양쪽 발뒤꿈치를 모두 터치하면 1회로 센다.","정해진 반복 횟수를 채울 때까지 좌우를 번갈아 이어간다."], en: ["Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.","Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.","Now go back slowly to the starting position as you inhale.","Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.","Continue alternating sides in this manner until all prescribed repetitions are done."] },
  "사이드 크런치": { s: "Oblique_Crunches/0.jpg", e: "Oblique_Crunches/1.jpg", k: ["허리를 바닥에 밀착시키고 눕는다. 한 손은 머리 옆에 대고 다른 손은 몸 옆 바닥에 둔다.","발은 들어 올려 평평한 곳에 올려 둔다.","이제 머리에 손을 댄 쪽 어깨를 들어 올린다.","어깨와 상체를 위로 들어 올려 무릎에 닿게 한다. 예를 들어 오른손을 머리 옆에 댔다면 오른쪽 팔꿈치가 왼쪽 무릎에 닿을 때까지 상체를 들어 올린다. 반대로 왼쪽 팔꿈치로 오른쪽 무릎을 터치하는 식으로도 동일하게 수행할 수 있다.","무릎과 팔꿈치가 닿으면 상체를 내려 시작 자세로 돌아온다.","내리는(신장성) 구간에서 숨을 들이마시고 올라가는(단축성) 구간에서 숨을 내쉰다.","양쪽 모두 정해진 반복 횟수를 채울 때까지 번갈아 이어간다."], en: ["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.","Make sure your feet are elevated and resting on a flat surface.","Now lift the shoulder in which your hand is touching your head.","Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.","After your knee touches your elbow, lower your body until you have reached the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."] },
  "사이드 벤드": { s: "Dumbbell_Side_Bend/0.jpg", e: "Dumbbell_Side_Bend/1.jpg", k: ["왼손에 덤벨을 들고(손바닥이 몸통을 향하게) 오른손은 허리에 얹은 채 똑바로 선다. 발은 어깨너비로 벌린다. 이것이 시작 자세다.","등을 곧게 펴고 고개를 든 채 허리만 오른쪽으로 최대한 굽힌다. 옆으로 굽히며 숨을 들이마신다. 1초간 멈춘 뒤 숨을 내쉬며 시작 자세로 돌아온다. 팁: 허리 외의 몸은 고정한다.","이번에는 왼쪽으로 굽히며 같은 동작을 반복한다. 1초간 멈춘 뒤 시작 자세로 돌아온다.","정해진 반복 횟수만큼 수행한 뒤 덤벨을 반대 손으로 바꿔 든다."], en: ["Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions and then change hands."] },
  "디클라인 크런치": { s: "Decline_Crunch/0.jpg", e: "Decline_Crunch/1.jpg", k: ["디클라인 벤치 끝에 다리를 고정하고 눕는다.","팔꿈치를 안쪽으로 모은 채 두 손을 머리 양옆에 가볍게 댄다. 팁: 손가락을 머리 뒤에서 깍지 끼지 않는다.","복근을 더 잘 고립시키기 위해 허리를 벤치에 눌러 붙이면서 어깨를 벤치에서 말아 올리기 시작한다.","복근을 수축시키고 숨을 내쉬면서 허리로 벤치를 계속 강하게 누른다. 어깨는 벤치에서 10cm 정도만 들리면 되고 허리는 벤치에 붙어 있어야 한다. 동작 맨 위에서 복근을 강하게 수축시켜 1초간 유지한다. 팁: 느리고 통제된 동작에 집중한다 — 반동을 쓰면 스스로를 속이는 셈이다.","1초간 수축한 뒤 숨을 들이마시며 천천히 시작 자세로 내려온다.","권장 반복 횟수만큼 반복한다."], en: ["Secure your legs at the end of the decline bench and lie down.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."] },
  "라잉 니 레이즈": { k: ["바닥에 등을 대고 누워 양손을 엉덩이 옆이나 아래에 두고 다리를 곧게 뻗는다. 이것이 시작 자세다.","숨을 내쉬며 무릎을 굽혀 가슴 쪽으로 천천히 끌어 올리고, 아랫배가 수축되는 것을 느낀다.","잠깐 멈춘 뒤 숨을 들이마시며 다리를 천천히 뻗어 발뒤꿈치가 바닥에 닿기 직전까지 내린다.","정해진 반복 횟수만큼 반복한다. 팁: 허리가 바닥에서 뜨지 않도록 아랫배에 힘을 유지한다 — 뜬다면 가동 범위를 줄인다."], en: ["Lie on your back with your hands beside or under your hips and your legs extended. This is your starting position.","Exhale and slowly draw your knees toward your chest, feeling your lower abs contract.","Pause briefly, then inhale and extend your legs slowly until your heels are just above the floor.","Repeat for the prescribed amount of repetitions. Tip: Keep your lower back pressed to the floor — if it arches, shorten the range of motion."] },
  "행잉 니 레이즈": { k: ["풀업 바에 어깨너비 오버핸드 그립으로 매달려 몸을 곧게 편다. 이것이 시작 자세다.","숨을 내쉬며 무릎을 굽혀 가슴 쪽으로 끌어 올리고, 최고 지점에서 골반을 살짝 말아 아랫배를 강하게 수축시킨다.","1초간 유지한 뒤 숨을 들이마시며 다리를 천천히 시작 자세로 내린다.","몸의 반동을 죽인 뒤 정해진 반복 횟수만큼 반복한다. 팁: 몸이 흔들리며 반동을 쓰면 자극이 새어 나간다 — 견갑골을 살짝 아래로 당겨 어깨를 고정하고 천천히 수행한다."], en: ["Hang from a pull-up bar with a shoulder-width overhand grip, body straight. This is your starting position.","Exhale and draw your knees up toward your chest, tucking your pelvis slightly at the top to fully contract your lower abs.","Hold for a second, then inhale and lower your legs slowly to the starting position.","Kill any swing, then repeat for the prescribed amount of repetitions. Tip: Swinging bleeds tension away — pull your shoulder blades slightly down to lock your shoulders and move slowly."] },
  "패러럴 바 니 레이즈": { s: "Knee_Hip_Raise_On_Parallel_Bars/0.jpg", e: "Knee_Hip_Raise_On_Parallel_Bars/1.jpg", k: ["버티컬 레그 레이즈 기구에 올라 아래팔을 몸통 옆 패드에 얹고 핸들을 잡는다. 팔은 90도로 굽힌 상태가 된다.","상체를 곧게 세우고 허리를 기구 패드에 밀착시키며 다리는 바닥을 향해 곧게 늘어뜨린다. 이것이 시작 자세다.","숨을 내쉬며 다리를 편 채 들어 올린다. 다리가 바닥과 거의 평행해질 때까지 올린 뒤 수축 상태를 1초간 유지한다. 팁: 반동이나 스윙을 사용하지 않는다.","숨을 들이마시며 천천히 시작 자세로 돌아온다.","정해진 반복 횟수만큼 동작을 반복한다."], en: ["Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.","The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.","Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.","Slowly go back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."] },
  "패러럴 바 레그 레이즈": { k: ["패러럴 바(딥스 바)에 올라 팔을 편 채 몸을 지지하고, 어깨를 아래로 눌러 견갑골을 고정한다. 이것이 시작 자세다.","숨을 내쉬며 다리를 곧게 편 채 바닥과 수평이 될 때까지 천천히 들어 올린다.","최고 지점에서 1초간 멈춰 복근을 수축시킨 뒤, 숨을 들이마시며 다리를 천천히 내린다.","몸통이 흔들리지 않게 유지하며 정해진 반복 횟수만큼 반복한다. 팁: 다리를 곧게 펴기 어렵다면 무릎을 굽힌 니 레이즈부터 시작해 점진적으로 다리를 펴 나간다."], en: ["Mount the parallel bars with your arms straight, pressing your shoulders down to lock your shoulder blades. This is your starting position.","Exhale and raise your legs, keeping them straight, until they are parallel to the floor.","Pause for a second at the top, contracting your abs, then inhale and lower your legs slowly.","Keep your torso steady and repeat for the prescribed amount of repetitions. Tip: If straight legs are too hard, start with bent-knee raises and progressively straighten your legs."] },
  "드래곤 플래그": { k: ["플랫 벤치에 누워 머리 뒤쪽 벤치 모서리(또는 기둥)를 양손으로 단단히 잡는다. 난이도가 매우 높은 동작이므로 무릎을 구부린 턱 변형이나 니 레이즈부터 점진적으로 힘을 쌓은 뒤 시도하는 것이 안전하다.","숨을 내쉬며 어깨와 상부 등만 벤치에 남기고 다리와 몸통을 일직선으로 들어 올린다. 몸이 어깨 위에 수직으로 세워진 지점이 맨 위다.","코어와 둔근의 긴장을 유지한 채 숨을 들이마시며 몸을 일직선 그대로 천천히 내린다. 벤치에 닿기 직전까지 내렸다가 다시 들어 올린다.","허리를 통제할 수 있는 범위에서 정해진 횟수만큼 반복한다.","팁: 엉덩이가 접히면 플래그가 아니라 레그 레이즈가 된다. 어깨부터 발끝까지 한 판자처럼 고정하는 것이 핵심이다."], en: ["Lie on a flat bench and firmly grip the edge of the bench (or an upright) behind your head. This is a very advanced movement, so it is safest to build up gradually with bent-knee tuck variations or knee raises before attempting the full version.","As you breathe out, lift your legs and torso as one straight line, leaving only your shoulders and upper back on the bench. The top position is your body stacked vertically over your shoulders.","Keeping your core and glutes tight, breathe in and lower your body slowly in one straight line. Stop just before touching the bench, then raise back up.","Repeat for the prescribed reps within a range your lower back can control.","Tip: If your hips bend, it becomes a leg raise, not a flag. The key is keeping your body rigid as a single plank from shoulders to toes."] },
  "리버스 플랭크": { k: ["바닥에 앉아 다리를 곧게 뻗고 양손을 엉덩이 뒤 어깨 아래에 짚는다. 손끝은 발 쪽을 향하게 한다.","숨을 내쉬며 엉덩이를 들어 올려 발뒤꿈치부터 어깨까지 몸이 일직선이 되게 만든다. 이것이 유지 자세다.","둔근과 코어에 힘을 준 채 자연스럽게 호흡하며 정해진 시간 동안 버틴다.","엉덩이가 처지기 시작하면 내려와 휴식한 뒤 반복한다. 팁: 시선은 천장을 향하고 엉덩이를 위로 밀어 올린다는 느낌을 유지한다 — 어깨가 귀 쪽으로 솟지 않게 가슴을 연다."], en: ["Sit on the floor with your legs extended and your hands under your shoulders behind you, fingers pointing toward your feet.","Exhale and lift your hips until your body forms a straight line from heels to shoulders. This is the hold position.","Keep your glutes and core engaged and breathe naturally, holding for the prescribed time.","When your hips start to sag, come down, rest, and repeat. Tip: Look at the ceiling and keep driving your hips up — open your chest so your shoulders don't shrug toward your ears."] },
  "엘보 투 니": { s: "Elbow_to_Knee/0.jpg", e: "Elbow_to_Knee/1.jpg", k: ["바닥에 누워 오른쪽 다리를 구부린 왼쪽 무릎 위에 교차해 올린다. 두 손은 머리 뒤에서 깍지 끼고, 견갑골이 바닥에 닿은 상태에서 시작한다. 이것이 시작 자세다.","척추를 구부리고 상체를 회전시켜 왼쪽 팔꿈치를 오른쪽 무릎으로 가져간다.","시작 자세로 돌아와 원하는 반복 횟수만큼 반복한 뒤 반대쪽으로 바꾼다."], en: ["Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.","Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.","Return to the starting position and repeat the movement for the desired number of repetitions before switching sides."] },
  "스파이더맨 플랭크": { k: ["팔꿈치를 어깨 아래에 두고 플랭크 자세를 잡아 머리부터 발뒤꿈치까지 일직선을 유지한다. 이것이 시작 자세다.","숨을 내쉬며 한쪽 무릎을 같은 쪽 팔꿈치를 향해 옆으로 끌어 올리고, 옆구리(복사근)가 수축되는 것을 느낀다.","숨을 들이마시며 다리를 시작 자세로 되돌리고, 반대쪽도 같은 방식으로 번갈아 수행한다.","정해진 반복 횟수 또는 시간 동안 반복한다. 팁: 무릎을 끌어올 때 엉덩이가 솟거나 골반이 돌아가지 않도록 코어를 단단히 고정한다."], en: ["Set up in a forearm plank with your elbows under your shoulders and your body in a straight line from head to heels. This is your starting position.","Exhale and draw one knee out to the side toward the same-side elbow, feeling your obliques contract.","Inhale and return the leg to the starting position, then alternate sides.","Repeat for the prescribed reps or time. Tip: Keep your core braced so your hips don't pike up or rotate as the knee comes forward."] },
  "팔로프 프레스": { s: "Pallof_Press/0.jpg", e: "Pallof_Press/1.jpg", k: ["케이블 머신에 일반 핸들을 연결하고, 가능하면 케이블을 어깨 높이로 맞춘다. 어렵다면 낮은 풀리로도 충분하다.","케이블 쪽으로 몸의 옆면이 향하게 서서 양손으로 핸들을 잡고 머신에서 멀어지도록 걸어 나온다. 풀리에서 팔 길이 정도 떨어져 케이블에 중량의 장력이 걸려 있어야 한다.","발을 골반 너비로 벌리고 무릎을 살짝 구부린 채 핸들을 가슴 중앙에 붙잡아 둔다. 이것이 시작 자세다.","두 팔을 완전히 펴며 핸들을 가슴에서 앞으로 밀어낸다. 코어는 단단히 조인 상태를 유지한다.","몇 초간 버틴 뒤 시작 자세로 돌아온다.","세트가 끝나면 반대 방향을 보고 같은 방식으로 반복한다."], en: ["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."] },
  "랜드마인 180": { s: "Landmine_180s/0.jpg", e: "Landmine_180s/1.jpg", k: ["바벨을 랜드마인 기구에 끼우거나 코너에 단단히 고정한다. 적절한 무게로 중량을 끼운다.","바를 바닥에서 들어 올려 양손으로 잡고 팔을 앞으로 뻗어 어깨 높이에 둔다. 발은 넓게 벌린다. 이것이 시작 자세다.","몸통과 고관절을 회전시키며 바를 한쪽 옆 아래까지 크게 스윙한다. 동작 내내 팔은 편 상태를 유지한다.","동작을 되돌려 반대쪽 끝까지 바를 스윙한다.","세트가 끝날 때까지 좌우를 번갈아 이어간다."], en: ["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.","Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.","Reverse the motion to swing the weight all the way to the opposite side.","Continue alternating the movement until the set is complete."] },
  "토즈 투 바": { k: ["풀업 바에 어깨너비보다 약간 넓은 오버핸드 그립으로 매달린다. 견갑골을 살짝 아래로 당겨 어깨가 귀에서 멀어지게 능동적으로 매달린다. 처음에는 무릎을 가슴까지 올리는 니 레이즈부터 점진적으로 가동범위를 늘리는 것이 안전하다.","숨을 내쉬며 코어에 힘을 주고, 골반을 뒤로 말아 올리며 다리를 들어 발끝으로 바를 터치한다.","숨을 들이마시며 다리를 통제하에 천천히 내려 시작 자세로 돌아온다.","몸의 흔들림을 정리한 뒤 정해진 횟수만큼 반복한다.","팁: 다리 힘만으로 차올리면 허리에 부담이 가고 스윙이 커진다. 복근으로 골반을 말아 올리는 감각에 집중하고, 어렵다면 무릎을 구부려 수행한다."], en: ["Hang from a pull-up bar with an overhand grip slightly wider than shoulder width. Hang actively by pulling your shoulder blades slightly down, away from your ears. It is safest to progress gradually, starting with knee raises to the chest before working up to full range.","As you breathe out, brace your core, curl your pelvis up and back, and raise your legs until your toes touch the bar.","Breathe in as you lower your legs slowly and under control back to the starting position.","Let any swinging settle, then repeat for the prescribed reps.","Tip: Kicking up with leg strength alone stresses the lower back and creates swing. Focus on curling the pelvis up with your abs, and bend your knees if the straight-leg version is too difficult."] },
  "L-싯 홀드": { k: ["패럴렛(또는 딥 바·바닥)에 양손을 짚고 팔을 편 채 어깨를 아래로 눌러 몸을 띄운다. 처음에는 무릎을 구부린 턱 싯이나 한 다리만 펴는 변형부터 점진적으로 익히는 것이 안전하다.","숨을 내쉬며 두 다리를 모아 바닥과 평행이 될 때까지 앞으로 뻗어 몸이 L자가 되게 한다.","무릎을 펴고 발끝을 곧게 뻗은 채, 짧고 일정한 호흡으로 정해진 시간 동안 자세를 유지한다.","천천히 다리를 내려 마무리하고, 세트 사이에 충분히 휴식한다.","팁: 어깨가 귀 쪽으로 솟으면 버티기 어려워진다. 손으로 바닥을 강하게 밀어 견갑골을 내리누르는 것이 핵심이다."], en: ["Place your hands on parallettes (or dip bars/the floor), lock your arms, and press your shoulders down to lift your body off the ground. It is safest to progress gradually, starting with a bent-knee tuck sit or a one-leg-extended variation.","As you breathe out, extend both legs together in front of you until they are parallel to the floor, forming an L shape.","Keep your knees locked and toes pointed, and hold the position for the prescribed time while breathing in short, steady breaths.","Lower your legs slowly to finish, and rest fully between sets.","Tip: If your shoulders shrug up toward your ears, the hold collapses. The key is pushing hard into the ground and pressing your shoulder blades down."] },
  "토르소 로테이션 머신": { k: ["머신에 앉아 가슴 패드에 상체를 밀착하고 하체를 패드에 고정한 뒤, 몸통을 한쪽으로 회전한 지점에서 시작 자세를 잡는다.","숨을 내쉬며 복사근의 힘으로 몸통을 반대쪽으로 천천히 회전시킨다.","끝 지점에서 잠깐 멈춘 뒤 숨을 들이마시며 무게에 저항하면서 시작 자세로 돌아온다.","정해진 반복 횟수를 마친 뒤 방향을 바꿔 같은 방식으로 수행한다. 팁: 팔이나 반동으로 돌리지 말고 가동 범위를 무리하게 늘리지 않는다 — 가볍고 컨트롤된 회전이 핵심이다."], en: ["Sit in the machine with your chest against the pad and your lower body locked in, starting with your torso rotated to one side.","Exhale and rotate your torso slowly to the other side using your obliques.","Pause briefly at the end, then inhale and return to the starting position, resisting the weight.","Complete the prescribed reps, then switch directions. Tip: Don't use your arms or momentum, and don't force extra range — light, controlled rotation is key."] },
  "행 클린": { s: "Hang_Clean/0.jpg", e: "Hang_Clean/1.jpg", k: ["어깨너비의 더블 오버핸드 그립 또는 훅 그립으로 바를 잡고, 허벅지 중간 높이에 바를 늘어뜨린 채 시작한다. 등은 곧게 펴고 상체는 약간 앞으로 기울인다.","고관절·무릎·발목을 폭발적으로 펴며 중량을 위로 끌어올린다. 동시에 어깨를 귀 쪽으로 으쓱하듯 들어 올린다.","곧바로 발뒤꿈치로 지면을 밀며 일어선다. 상체를 세우고 팔꿈치를 높이 유지한 채 완전히 선 자세가 될 때까지 이어간다."], en: ["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."] },
  "클린 앤 프레스": { s: "Clean_and_Press/0.jpg", e: "Clean_and_Press/1.jpg", k: ["어깨너비로 서서 무릎이 팔 안쪽에 오게 한다. 등을 평평하게 유지한 채 무릎과 고관절을 굽혀, 팔을 완전히 편 상태에서 어깨너비보다 약간 넓은 오버핸드 그립으로 바를 잡는다. 팔꿈치는 바깥쪽을 향하게 한다. 바는 정강이에 가깝게 두고, 어깨는 바 바로 위나 약간 앞에 위치시킨다. 등을 평평하게 세팅한다. 이것이 시작 자세다.","무릎을 펴며 바를 당기기 시작한다. 등의 각도를 일정하게 유지하면서 고관절을 앞으로 밀고 어깨를 같은 속도로 올리며, 바를 몸에 붙인 채 수직으로 계속 들어 올린다.","바가 무릎을 지나면 점프하듯 발목·무릎·고관절을 강하게 편다. 그러면서 손으로 바의 경로를 유지하고, 어깨를 으쓱하며 동작의 탄력을 이용해 바를 최대한 높이 끌어올린다. 바는 몸 가까이로 이동해야 하며 팔꿈치는 바깥쪽을 향하게 유지한다.","바가 최고점에 이르면 발이 바닥에서 떨어지며 바 아래로 몸을 끌어 내리기 시작한다. 사용하는 중량에 따라 이 과정의 움직임은 조금 달라질 수 있다. 바 아래로 들어가면서 스쿼트 자세로 내려간다.","바가 최고 높이에 도달하면 팔꿈치를 바 아래로 돌려 넣는다. 상체를 곧게 세운 채 어깨 앞쪽에 바를 랙 하고, 고관절과 무릎을 굽혀 바의 무게를 흡수한다.","클린 자세로 바를 든 채 완전히 일어선다.","발을 움직이지 않은 채 숨을 내쉬며 바를 머리 위로 프레스한다. 바는 통제하며 내린다."], en: ["Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.","Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.","As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.","At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.","As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.","Stand to full height, holding the bar in the clean position.","Without moving your feet, press the bar overhead as you exhale. Lower the bar under control ."] },
  "클린 풀": { s: "Clean_Pull/0.jpg", e: "Clean_Pull/1.jpg", k: ["바닥의 바벨을 정강이에 가깝게 두고, 다리 바로 바깥에서 오버핸드 그립 또는 훅 그립으로 잡는다. 체중을 발뒤꿈치에 실어 엉덩이를 낮추고, 등은 곧게, 시선은 정면, 가슴은 세우고, 어깨는 바 약간 앞에 위치시킨다. 이것이 시작 자세다.","첫 번째 풀은 발뒤꿈치로 지면을 밀며 무릎을 펴는 것으로 시작한다. 등의 각도는 그대로 유지하고 팔은 편 채 팔꿈치는 바깥쪽을 향한다. 바가 무릎 위에 도달할 때까지 통제하며 중량을 움직인다.","다음은 클린의 주된 가속 구간인 두 번째 풀이다. 바가 허벅지 중간에 가까워지면 고관절을 펴기 시작한다. 점프하듯 고관절·무릎·발목을 펴며 속도로 바를 위로 가속시킨다. 팔로 적극적으로 당겨 가속할 필요는 없다. 두 번째 풀이 끝나는 시점에는 몸이 완전히 펴지고 약간 뒤로 기울며 팔은 여전히 편 상태여야 한다. 완전 신전은 폭발적이고 순간적으로 이루어져야 하며, 필요 이상으로 신전을 끌지 않는다."], en: ["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary."] },
  "파워 스내치": { s: "Power_Snatch/0.jpg", e: "Power_Snatch/1.jpg", k: ["바닥에 중량을 끼운 바벨을 두고 시작한다. 바는 정강이에 닿을 정도로 가깝게 두고 와이드 그립으로 잡는다. 발은 골반 바로 아래에 두고 필요한 만큼 발끝을 바깥으로 돌린다. 가슴을 세우고 시선을 정면에 둔 채 엉덩이를 낮춘다. 어깨는 바 약간 앞에 위치시킨다. 이것이 시작 자세다.","첫 번째 풀은 발뒤꿈치 앞쪽으로 지면을 밀며 바를 바닥에서 들어 올리는 것으로 시작한다. 바가 무릎을 지날 때까지 등의 각도는 그대로 유지한다.","고관절·무릎·발목을 펴며 두 번째 풀로 전환해 바를 최대한 빠르게 끌어올린다. 바는 몸에 가깝게 유지한다. 최대 신전 시점에 어깨를 으쓱하고 팔꿈치가 옆으로 굽어지게 한다.","발을 약간 더 넓은 받는 자세로 옮기면서 바를 머리 위로 올림과 동시에 바 아래로 몸을 끌어 내린다. 바는 부분 스쿼트 자세에서 받는다. 바를 머리 위까지 계속 올려 팔꿈치를 완전히 편 상태로 받는다.","중량을 머리 위에 든 채 일어선다."], en: ["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.","Return to a standing position with the weight over head."] },
  "행 스내치": { s: "Hang_Snatch/0.jpg", e: "Hang_Snatch/1.jpg", k: ["오버핸드 그립 또는 훅 그립의 와이드 그립으로 바를 잡는다. 발은 골반 바로 아래에 두고 발끝은 바깥으로 돌린다. 무릎은 살짝 굽히고 상체는 앞으로 기울인다. 척추는 완전히 펴고 시선은 정면에 둔다. 바는 고관절 높이에 위치시킨다. 이것이 시작 자세다.","다리와 고관절을 폭발적으로 편다. 최대 신전 시점에 어깨를 으쓱하고 팔꿈치가 옆으로 굽어지게 한다.","발을 받는 자세로 옮기면서 바를 머리 위로 올림과 동시에 바 아래로 힘차게 몸을 끌어 내린다. 몸을 최대한 낮추고 팔을 머리 위로 완전히 편 상태로 바를 받는다.","중량을 머리 위에 든 채 일어선다. 이어서 통제하며 중량을 바닥으로 내린다."], en: ["Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.","Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.","Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control."] },
  "스플릿 저크": { s: "Split_Jerk/0.jpg", e: "Split_Jerk/1.jpg", k: ["바를 어깨 앞쪽에 랙 한 채 서서 딥으로 시작한다. 발을 골반 바로 아래에 두고, 엉덩이를 뒤로 빼지 않으면서 무릎을 굽힌다.","살짝만 내려갔다가 최대한 강하게 방향을 되돌린다. 발뒤꿈치로 지면을 밀어 최대한의 속도와 힘을 만들고, 바가 어깨를 떠날 때 머리를 경로에서 빼내는 것을 잊지 않는다. 발이 바닥에서 떨어지는 순간, 가능한 한 빠르게 받는 자세로 발을 옮겨야 한다.","발이 지면을 밀지 않는 짧은 순간, 바를 위로 미는 힘이 몸을 아래로 내려가게 한다. 발은 한 발은 앞, 한 발은 뒤인 스플릿 스탠스로 옮기고 무릎은 부분적으로 굽힌다. 팔을 머리 위로 완전히 편 상태로 바를 받는다.","두 발을 모으며 선 자세로 돌아온다."], en: ["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.","Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.","In the brief moment the feet are not actively driving against the platform, the athlete's effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.","Return to a standing position, bringing the feet together."] },
  "프레스 언더": { k: ["역도 보조 훈련 동작이므로 빈 봉이나 PVC 파이프로 오버헤드 스쿼트 자세를 충분히 익힌 뒤 점진적으로 연습하는 것이 안전하다.","스내치 그립(넓은 그립)으로 바를 목 뒤 승모근 위에 얹고 어깨너비보다 약간 넓게 선다. 이것이 시작 자세다.","숨을 들이마셔 코어를 고정한 뒤, 바를 밀어 올리는 대신 몸을 아래로 낮추면서 팔을 펴 스쿼트 바닥 자세에서 바를 머리 위에 록아웃한다.","바를 머리 위에 고정한 채 숨을 내쉬며 일어선 뒤, 바를 목 뒤로 되돌려 정해진 반복 횟수만큼 반복한다.","팁: 바는 제자리에 두고 몸이 바 아래로 내려간다는 느낌이 핵심이다 — 발뒤꿈치가 뜨지 않게 체중을 발 중앙에 둔다."], en: ["This is an Olympic lifting drill — master the overhead squat position with an empty bar or PVC pipe first and progress gradually.","Place the bar behind your neck with a wide snatch grip and stand slightly wider than shoulder width. This is your starting position.","Inhale and brace your core, then instead of pressing the bar up, drop your body down into a squat while extending your arms, locking the bar out overhead at the bottom.","Exhale and stand up with the bar locked overhead, then return it behind your neck and repeat for the prescribed amount of repetitions.","Tip: The bar stays in place — your body moves down under it. Keep your weight over midfoot so your heels don't lift."] },
  "랜드마인 스쿼트 앤 프레스": { k: ["바벨 한쪽 끝을 랜드마인(또는 코너)에 고정하고, 반대쪽 끝을 양손으로 감싸 가슴 앞에 든다. 발은 어깨너비로 벌리고 선다. 이것이 시작 자세다.","숨을 들이마시며 가슴을 세운 채 엉덩이를 뒤로 빼면서 허벅지가 바닥과 평행이 될 때까지 스쿼트로 앉는다.","숨을 내쉬며 발바닥 전체로 바닥을 밀어 일어서고, 그 힘을 이어받아 바 끝을 앞쪽 대각선 위로 밀어 팔을 뻗는다.","바를 다시 가슴 앞으로 통제하며 내려 시작 자세로 돌아온다.","정해진 반복 횟수만큼 동작을 반복한다.","팁: 스쿼트와 프레스를 따로 끊어 하면 리듬과 힘 전달이 사라진다. 일어서는 하체의 추진력이 프레스로 자연스럽게 이어지도록 한 동작으로 연결한다."], en: ["Anchor one end of a barbell in a landmine (or a corner) and hold the other end with both hands at your chest. Stand with your feet shoulder-width apart. This will be your starting position.","As you breathe in, keep your chest up and squat down by pushing your hips back until your thighs are parallel to the floor.","As you breathe out, drive through your whole foot to stand up, and carry that momentum into pressing the end of the bar up and away until your arms are extended.","Lower the bar back to your chest under control and return to the starting position.","Repeat the movement for the prescribed amount of repetitions.","Tip: Splitting the squat and press into two separate motions kills the rhythm and power transfer. Link them into one fluid movement so the leg drive flows directly into the press."] },
  "케틀벨 하이 풀": { s: "Kettlebell_Sumo_High_Pull/0.jpg", e: "Kettlebell_Sumo_High_Pull/1.jpg", k: ["케틀벨을 두 발 사이 바닥에 놓는다. 발을 넓게 벌리고 양손으로 케틀벨을 잡는다. 무릎을 굽힌 채 엉덩이를 최대한 뒤로 빼고 가슴과 고개는 든다. 이것이 시작 자세다.","고관절과 무릎을 펴면서 동시에 팔꿈치를 높이 들어 케틀벨을 어깨 높이까지 끌어올린다. 동작을 되돌려 시작 자세로 돌아온다."], en: ["Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.","Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position."] },
  "터키시 겟업": { s: "Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg", e: "Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg", k: ["바닥에 등을 대고 누워 팔꿈치를 펴며 케틀벨을 머리 위로 프레스해 든다. 케틀벨을 든 쪽 무릎을 굽힌다.","케틀벨을 든 팔은 항상 편 상태(락아웃)를 유지하며 반대쪽으로 몸을 돌리고, 반대 팔로 바닥을 짚어 몸을 앞으로 일으킨다. 짚은 손으로 밀어 앉은 자세를 만든 뒤 한쪽 무릎을 세운 런지 자세로 이어간다.","케틀벨을 올려다보면서 천천히 일어선다. 동작을 역순으로 되돌려 시작 자세로 돌아온 뒤 반복한다."], en: ["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.","While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat."] },
  "케틀벨 어라운드 더 월드": { k: ["어깨너비로 서서 케틀벨을 한 손에 들고 몸 옆에 둔다. 코어에 힘을 주고 상체를 곧게 세운다. 이것이 시작 자세다.","케틀벨을 몸 뒤로 돌려 반대 손으로 넘겨 받고, 이어서 몸 앞에서 다시 원래 손으로 넘기며 몸 주위로 원을 그린다.","자연스럽게 호흡하며 일정한 속도로 정해진 반복 횟수만큼 돌린 뒤, 방향을 바꿔 같은 횟수를 반복한다.","팁: 케틀벨을 따라 몸통이 흔들리지 않게 골반과 코어를 고정한다 — 손을 바꿔 잡는 순간에도 시선은 정면을 유지한다."], en: ["Stand shoulder-width apart holding a kettlebell in one hand at your side. Brace your core and keep your torso upright. This is your starting position.","Pass the kettlebell behind your body to the other hand, then around the front back to the starting hand, drawing a circle around your body.","Breathe naturally and circle at a steady pace for the prescribed reps, then reverse direction and repeat.","Tip: Keep your hips and core locked so your torso doesn't sway with the bell — keep your eyes forward during the hand-offs."] },
  "슬레드 푸시": { s: "Sled_Push/0.jpg", e: "Sled_Push/1.jpg", k: ["푸시 슬레드에 원하는 중량을 싣는다.","팔을 완전히 편 채 핸들을 잡고 슬레드에 몸을 기울여 안정적인 운동 자세를 취한다. 고관절과 무릎을 펴서 후면 사슬(포스테리어 체인)을 단련하는 데 집중하며 슬레드를 최대한 빠르게 민다."], en: ["Load your pushing sled with the desired weight.","Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain."] },
  "슬레드 풀": { k: ["슬레드에 스트랩이나 로프를 연결하고 하네스 또는 손잡이를 잡은 뒤, 슬레드 반대 방향으로 몸을 기울인다. 이것이 시작 자세다.","코어를 고정하고 무릎을 굽힌 낮은 자세로, 한 걸음씩 바닥을 강하게 밀며 슬레드를 끌고 전진한다. 뒤로 걸으며 끄는 방식도 가능하다.","자연스럽게 호흡하며 정해진 거리나 시간 동안 이동한 뒤 휴식하고 반복한다.","팁: 상체만 기울여 팔로 끌지 않는다 — 다리로 바닥을 밀어내는 힘으로 슬레드를 움직인다."], en: ["Attach a strap or rope to the sled, grab the harness or handles, and lean away from the sled. This is your starting position.","Brace your core, stay low with your knees bent, and drive the ground away step by step to pull the sled forward. Walking backward also works.","Breathe naturally and move for the prescribed distance or time, then rest and repeat.","Tip: Don't just lean and pull with your arms — the power comes from your legs driving into the ground."] },
  "수트케이스 캐리": { k: ["덤벨 하나를 한쪽 손에 들고 어깨너비로 선다. 어깨를 뒤로 젖히고 상체를 곧게 세워 몸이 무게 쪽으로 기울지 않게 한다. 이것이 시작 자세다.","코어와 옆구리에 힘을 준 채 자연스럽게 호흡하며 일정한 보폭으로 정해진 거리나 시간 동안 걷는다.","덤벨을 안전하게 내려놓고 반대쪽 손으로 바꿔 같은 거리를 걷는다.","팁: 정면에서 봤을 때 양쪽 어깨 높이가 수평이어야 한다 — 몸이 기울면 무게를 줄인다."], en: ["Hold a dumbbell in one hand and stand shoulder-width apart. Pull your shoulders back and stay tall so your body doesn't lean toward the weight. This is your starting position.","Brace your core and obliques, breathe naturally, and walk with even steps for the prescribed distance or time.","Set the dumbbell down safely, switch hands, and walk the same distance.","Tip: Your shoulders should stay level when viewed from the front — if you're tilting, use a lighter weight."] },
  "월 볼": { k: ["벽에서 약 반 걸음 떨어져 발을 어깨너비로 벌리고 서서, 메디신 볼을 턱 아래 가슴 앞에 받쳐 든다. 벽의 목표 지점(보통 약 3m 높이)을 정한다. 이것이 시작 자세다.","숨을 들이마시며 가슴을 세운 채 허벅지가 바닥과 평행이 될 때까지 스쿼트로 앉는다.","숨을 내쉬며 폭발적으로 일어서고, 하체의 추진력을 이어받아 볼을 목표 지점으로 던진다.","벽에서 떨어지는 볼을 가슴 앞에서 받아내며 그대로 다음 스쿼트로 부드럽게 이어간다.","정해진 횟수만큼 리듬을 유지하며 반복한다.","팁: 팔 힘만으로 던지면 금방 지친다. 던지는 힘의 대부분은 다리에서 나온다는 점을 기억하고, 볼을 받을 때는 무게를 흡수하듯 함께 앉는다."], en: ["Stand about half a step from a wall with your feet shoulder-width apart, holding a medicine ball at your chest just under your chin. Pick a target on the wall (usually around 9-10 feet high). This will be your starting position.","As you breathe in, keep your chest up and squat down until your thighs are parallel to the floor.","As you breathe out, stand up explosively and use the leg drive to throw the ball at the target.","Catch the ball at chest level as it comes down and flow directly into the next squat.","Repeat for the prescribed reps, keeping a steady rhythm.","Tip: Throwing with just your arms burns out quickly. Remember most of the power comes from your legs, and sink into the squat as you catch the ball to absorb its weight."] },
  "메디신 볼 슬램": { k: ["어깨너비로 서서 메디신 볼을 양손으로 잡고 몸 앞에 둔다. 이것이 시작 자세다.","숨을 들이마시며 볼을 머리 위로 높이 들어 올려 몸을 최대한 편다.","숨을 강하게 내쉬며 코어와 광배근의 힘으로 볼을 바닥에 힘껏 내리친다. 엉덩이를 뒤로 빼며 상체를 숙여 힘을 전달한다.","튀어 오른 볼을 잡거나 바닥에서 집어 들어 곧바로 다음 반복으로 이어가며, 정해진 반복 횟수만큼 수행한다.","팁: 팔로만 던지지 않는다 — 몸 전체를 채찍처럼 사용하고, 내리칠 때 등이 둥글게 말리지 않게 코어를 유지한다."], en: ["Stand shoulder-width apart holding a medicine ball in front of you with both hands. This is your starting position.","Inhale and raise the ball high overhead, fully extending your body.","Exhale forcefully and slam the ball into the floor using your core and lats, hinging your hips back as your torso folds forward.","Catch the ball on the bounce or pick it up and flow straight into the next rep, repeating for the prescribed amount of repetitions.","Tip: Don't throw with just your arms — whip your whole body into it, and keep your core braced so your back doesn't round on the slam."] },
  "베어 크롤": { k: ["네발 기기 자세에서 손은 어깨 아래, 무릎은 골반 아래에 두고 무릎을 바닥에서 살짝 띄운다. 등은 평평하게 유지한다. 이것이 시작 자세다.","반대쪽 손과 발을 동시에 앞으로 옮기며 작은 보폭으로 전진한다. 자연스럽게 호흡을 유지한다.","정해진 거리나 시간 동안 이동하며, 뒤로 이동하는 방식과 번갈아 수행할 수도 있다.","팁: 엉덩이가 솟거나 좌우로 흔들리지 않게 한다 — 등 위에 물컵을 올려놓았다고 상상하며 몸통을 수평으로 유지한다."], en: ["Start on all fours with your hands under your shoulders and knees under your hips, then lift your knees slightly off the floor. Keep your back flat. This is your starting position.","Move your opposite hand and foot forward at the same time, advancing with small steps while breathing naturally.","Travel for the prescribed distance or time; you can also alternate with crawling backward.","Tip: Don't let your hips rise or sway side to side — imagine balancing a cup of water on your back and keep your torso level."] },
  "프론트 레버 홀드": { k: ["풀업 바에 어깨너비 오버핸드 그립으로 매달리고, 견갑골을 아래로 당겨 능동적으로 매달린다. 매우 높은 근력이 필요한 동작이므로 턱 레버(무릎 접기)→한 다리 레버 순으로 점진적으로 습득하는 것이 안전하며, 밴드로 몸을 받쳐 연습할 수도 있다.","숨을 내쉬며 팔을 편 채 광배근으로 바를 눌러 내리듯 몸을 뒤로 들어 올려, 몸 전체가 바닥과 평행한 일직선이 되게 한다. 시선은 발끝 방향을 향한다.","코어와 둔근을 조여 엉덩이가 처지지 않게 하고, 짧고 일정한 호흡으로 정해진 시간 동안 자세를 유지한다.","천천히 몸을 내려 매달린 자세로 돌아온다.","팁: 엉덩이가 접히거나 처지면 레버가 아니다. 어깨부터 발끝까지 한 판자로 고정하고, 유지가 안 되면 더 쉬운 전 단계로 돌아가 힘을 쌓는다."], en: ["Hang from a pull-up bar with a shoulder-width overhand grip, pulling your shoulder blades down into an active hang. This move demands a lot of strength, so it is safest to progress step by step — tuck lever, then one-leg lever — and you can also practice with a band supporting your body.","As you breathe out, keep your arms straight and press the bar down with your lats, raising your body backward until it forms a straight line parallel to the floor. Look toward your toes.","Squeeze your core and glutes so your hips do not sag, and hold the position for the prescribed time while breathing in short, steady breaths.","Lower your body slowly back to a hang.","Tip: If your hips bend or sag, it is no longer a lever. Lock your body as one plank from shoulders to toes, and if you cannot hold it, go back to an easier progression and build strength."] },
  "버피 브로드 점프": { k: ["발을 어깨너비로 벌리고 선다. 이것이 시작 자세다.","손을 바닥에 짚고 두 발을 뒤로 차 플랭크 자세를 만든 뒤, 가슴이 바닥에 닿도록 푸시업 자세로 내려간다.","가슴을 바닥에서 밀어내며 두 발을 손 쪽으로 당겨 착지한다.","일어서는 힘을 이어받아 팔을 앞으로 스윙하며 최대한 멀리 앞으로 점프하고, 무릎을 굽혀 부드럽게 착지한다.","착지 지점에서 바로 다음 버피로 이어가며, 힘을 쓸 때 내쉬는 리듬으로 호흡을 유지한 채 정해진 횟수만큼 반복한다.","팁: 착지 시 무릎이 안쪽으로 모이면 부담이 커진다. 발끝과 무릎을 같은 방향으로 정렬하고 엉덩이로 충격을 흡수한다."], en: ["Stand with your feet shoulder-width apart. This will be your starting position.","Place your hands on the floor, kick both feet back into a plank, and lower into a push-up until your chest touches the ground.","Push your chest off the floor and jump both feet forward toward your hands.","Carry the momentum of standing up into swinging your arms forward and jumping as far forward as you can, landing softly with bent knees.","Flow straight into the next burpee from where you land, exhaling on each effort, and repeat for the prescribed reps.","Tip: Letting the knees cave inward on landing increases stress. Keep your knees tracking over your toes and absorb the impact with your hips."] },
  "버피 오버 더 바": { k: ["바닥에 놓인 바벨 옆에 나란히 선다. 이것이 시작 자세다.","손을 바닥에 짚고 두 발을 뒤로 차 가슴이 바닥에 닿는 버피를 수행한다.","가슴을 밀어내며 두 발을 당겨 일어선 뒤, 두 발로 바벨을 뛰어넘어 반대편에 착지한다. 무릎을 굽혀 부드럽게 착지한다.","반대편에서 바로 다음 버피로 이어가고, 힘을 쓸 때 내쉬는 리듬으로 정해진 횟수만큼 왕복 반복한다.","팁: 지치면 바를 뛰어넘을 때 발끝이 바에 걸리기 쉽다. 무릎을 충분히 들어 올리고, 필요하면 한 발씩 넘어가는 스텝 오버로 전환해 페이스를 유지한다."], en: ["Stand sideways next to a barbell on the floor. This will be your starting position.","Place your hands on the floor, kick your feet back, and perform a burpee with your chest touching the ground.","Push up, jump your feet back in, and stand, then jump over the barbell with both feet and land softly on the other side with bent knees.","Flow straight into the next burpee on that side, exhaling on each effort, and repeat back and forth for the prescribed reps.","Tip: When fatigued, it is easy to catch your toes on the bar during the jump. Lift your knees high, and switch to stepping over one foot at a time if needed to keep your pace."] },
  "점핑 잭": { k: ["발을 모으고 팔을 몸 옆에 붙인 채 곧게 선다. 이것이 시작 자세다.","가볍게 점프하며 다리를 어깨너비보다 넓게 벌리는 동시에 양팔을 머리 위로 들어 올린다.","다시 점프하며 다리를 모으고 팔을 몸 옆으로 내려 시작 자세로 돌아온다.","자연스럽게 호흡하며 일정한 리듬으로 정해진 횟수나 시간 동안 반복한다. 팁: 무릎을 살짝 굽혀 착지 충격을 부드럽게 흡수하고, 발 앞쪽부터 가볍게 착지한다."], en: ["Stand tall with your feet together and arms at your sides. This is your starting position.","Jump lightly, spreading your legs wider than shoulder width while raising your arms overhead.","Jump again to bring your feet together and your arms back to your sides, returning to the starting position.","Breathe naturally and repeat at a steady rhythm for the prescribed reps or time. Tip: Keep a slight bend in your knees to absorb the landing softly, landing lightly on the balls of your feet."] },
  "하이 니": { k: ["발을 골반 너비로 벌리고 서서 가슴을 세우고 시선은 정면을 향한다. 이것이 시작 자세다.","제자리에서 달리듯 한쪽 무릎을 골반 높이까지 빠르게 끌어올리고, 반대쪽 팔을 자연스럽게 흔든다.","발이 바닥에 닿자마자 반대쪽 무릎을 끌어올리며 앞꿈치로 가볍고 빠르게 리듬을 이어간다.","호흡은 리듬에 맞춰 짧게 내쉬며, 정해진 시간 또는 횟수만큼 반복한다.","팁: 속도를 올리면 상체가 뒤로 젖혀지기 쉽다. 코어에 힘을 주어 몸통을 곧게 세우고, 무릎 높이보다 지면 접촉을 짧게 가져가는 데 집중한다."], en: ["Stand with your feet hip-width apart, chest up, eyes forward. This will be your starting position.","As if running in place, quickly drive one knee up to hip height while swinging the opposite arm naturally.","The moment that foot touches down, drive the other knee up, staying light and quick on the balls of your feet.","Exhale in short breaths matching the rhythm, and continue for the prescribed time or reps.","Tip: As speed increases, it is easy to lean the torso backward. Brace your core to stay upright, and focus on short ground contact rather than knee height."] },
  "프론트 레버 레이즈": { k: ["상급 맨몸 동작이므로 무릎을 가슴에 붙인 턱 레버나 저항 밴드 보조로 점진적으로 습득하는 것이 안전하다.","풀업 바에 어깨너비 오버핸드 그립으로 매달려 팔을 편 채 견갑골을 아래로 당겨 어깨를 고정한다. 이것이 시작 자세다.","숨을 내쉬며 팔을 편 채 광배근과 코어의 힘으로 몸 전체를 일직선으로 유지하면서 바닥과 수평이 될 때까지 들어 올린다.","수평 지점에서 잠깐 버틴 뒤 숨을 들이마시며 컨트롤하면서 천천히 시작 자세로 내린다.","정해진 반복 횟수만큼 반복한다. 팁: 허리가 꺾이면 긴장이 새어 나간다 — 골반을 말아 몸을 한 장의 판자처럼 만들고, 수평이 어렵다면 무릎 굽힌 턱 레버 레이즈부터 단계적으로 진행한다."], en: ["This is an advanced bodyweight movement — build up gradually with the tuck lever (knees to chest) or resistance-band assistance.","Hang from a pull-up bar with a shoulder-width overhand grip, arms straight, pulling your shoulder blades down to lock your shoulders. This is your starting position.","Exhale and, keeping your arms straight and your body in one rigid line, raise your entire body with your lats and core until it is parallel to the floor.","Hold briefly at horizontal, then inhale and lower slowly under control back to the starting position.","Repeat for the prescribed amount of repetitions. Tip: A sagging lower back leaks tension — tuck your pelvis to make your body one solid plank, and if horizontal is too hard, progress from bent-knee tuck lever raises."] },
};
